INSERT INTO public.economics_cases
  (subsection, case_id, title, context, statements, answer_key, tactical_explanations, difficulty_level, sort_order, tier)
VALUES
( '3.1', 'CASE 3.1.01', 'Labour as human resources', 'Evaluate claims about labour as a factor of production:', ARRAY['Managers who coordinate schedules supply labour as human resources alongside coordination duties.', 'Insurance claims handlers processing policies supply labour in a service firm.', 'Labour is restricted to manual shop-floor work and excludes planners or accountants.', 'Installing software is a want rather than labour because the service is intangible.', 'Seasonal pickers fall outside labour because their employment lasts only weeks.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Management deploys human resources even when it also involves entrepreneurship.', 'TRUE — Office and service staff are human resources classified as labour.', 'FALSE — Labour includes all human resources, not only physical manual tasks.', 'FALSE — Skilled intangible work is still labour as human resources.', 'FALSE — Paid seasonal workers still supply human resources classified as labour.'], '3/5', 1, 'full' ),
( '3.1', 'CASE 3.1.02', 'Styrian winemaker harvest season', 'A Styrian winemaker hires seasonal pickers, leases a bottling line, and manages fermentation schedules. Evaluate:', ARRAY['The hillside vineyards represent the land factor as natural resources.', 'Seasonal pickers and the cellar master both supply labour for the winery.', 'The leased bottling line counts as capital even though the winery does not own it.', 'Fermentation knowledge applied to blending draws on knowledge as a production factor.', 'Barrel orders are capital decisions, so entrepreneurship is absent.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Vineyards are natural resources and therefore part of land.', 'TRUE — All human resources in production, seasonal or permanent, are labour.', 'TRUE — Productive equipment used in operations is capital whether owned or leased.', 'TRUE — Production knowledge and experience are important factors in winemaking.', 'FALSE — Coordinating factors and contracts is entrepreneurship.'], '3/5', 2, 'full' ),
( '3.1', 'CASE 3.1.03', 'Land and natural resources', 'Analyze what the land factor includes in production:', ARRAY['River water used to irrigate crops represents a natural-resource land input.', 'Timber ready for milling is land because it originates from trees.', 'Mineral rights are capital because they can be bought and sold.', 'Oak barrels are land because oak comes from forests.', 'Land refers only to fenced factory sites and excludes forests or fisheries.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Water sources used in production are natural resources within land.', 'FALSE — Processed logs for milling are inputs; standing forests are land.', 'FALSE — Unextracted minerals are natural resources within land.', 'FALSE — Processed barrels used in production are capital.', 'FALSE — Land includes fisheries, forests, and minerals as natural resources.'], '2/5', 3, 'full' ),
( '3.1', 'CASE 3.1.04', 'Capital in production', 'Assess statements about capital as a factor of production:', ARRAY['Leased diagnostic tools used by technicians still function as capital.', 'Spare parts inventory kept for same-day repairs is capital supporting service delivery.', 'Machinery, plant, vehicles, and financial resources used in operations are capital.', 'Cash reserves held to finance payroll between invoice cycles form part of capital.', 'A fleet of delivery vans used to ship finished goods is capital.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Leased equipment used in production is capital.', 'TRUE — Inventories used to deliver services belong to capital.', 'TRUE — Capital includes equipment and financial resources applied to production.', 'TRUE — Financial resources used to operate the business are capital.', 'TRUE — Vehicles used in production and distribution are capital equipment.'], '3/5', 4, 'full' ),
( '3.1', 'CASE 3.1.05', 'AT&S substrate production shift', 'AT&S Leoben runs a shift plating PCBs while sourcing laminate and scheduling engineers. Analyze:', ARRAY['Clean-room tools and testing rigs on the line are capital in secondary production.', 'Engineers monitoring substrate thickness supply specialised labour.', 'Plant management coordinating materials, staff, and orders supplies entrepreneurship.', 'Materials are land because copper is extracted from the earth.', 'Knowledge is a consumer good unless the firm registers patents.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Manufacturing equipment is part of the capital factor.', 'TRUE — Engineering and inspection work is skilled human resource use.', 'TRUE — Coordinating production factors and timing is entrepreneurship.', 'FALSE — Raw and processed inputs are combined with other factors; finished goods are outputs.', 'FALSE — Knowledge applied in production is a recognised factor.'], '3/5', 5, 'full' ),
( '3.1', 'CASE 3.1.06', 'Entrepreneurship role', 'Evaluate claims about entrepreneurship among the factors of production:', ARRAY['Entrepreneurship brings land, labour, and capital together to organise production.', 'Uncertainty is borne by lenders alone, not by entrepreneurs.', 'Financial resources are entrepreneurship because both involve business decisions.', 'Hiring staff converts all coordination into labour with no entrepreneurship left.', 'Selecting equipment is capital allocation only, so entrepreneurship is absent.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Entrepreneurship coordinates the other factors and bears organisational responsibility.', 'FALSE — Owners and organisers bear business uncertainty as entrepreneurship.', 'FALSE — Finance is capital; entrepreneurship coordinates rather than replaces it.', 'FALSE — Coordination and risk-bearing remain entrepreneurship with employees present.', 'FALSE — Choosing and organising inputs reflects entrepreneurship.'], '2/5', 6, 'full' ),
( '3.1', 'CASE 3.1.07', 'Knowledge and technology', 'Analyze knowledge and technology as production factors:', ARRAY['Diagnostic software licences used by repair technicians represent technology in services.', 'Experience with fermentation techniques contributes knowledge to winemaking output.', 'Technology used at a repair bench counts as a production factor in a service firm.', 'Technology counts as a factor only where a firm manufactures physical hardware.', 'Design know-how is capital because it is stored on servers.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Technology used to deliver services is a production factor.', 'TRUE — Production knowledge and experience are important factors in practice.', 'TRUE — Technology applied in production matters in services, not only factories.', 'FALSE — Technology also matters in service businesses such as IT support.', 'FALSE — Know-how applied to production is knowledge, not capital by storage medium.'], '3/5', 7, 'full' ),
( '3.1', 'CASE 3.1.08', 'Tina and Steve repair weekend', 'Tina and Steve refurbish laptops, install software, and bill for weekend support calls. Evaluate:', ARRAY['Their venture combines knowledge, labour, technology, capital, and entrepreneurship.', 'Coordinating bookings, parts orders, and repairs supplies entrepreneurship.', 'Diagnostic tools and software licences represent technology in their service model.', 'Spare screens and batteries held for repairs are capital inputs for the workshop.', 'Their technical troubleshooting supplies labour as human resources.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Their model uses skills, tools, finance, and coordination together.', 'TRUE — Organising resources and bearing business uncertainty is entrepreneurship.', 'TRUE — Technology used to perform services is a production factor.', 'TRUE — Inventories used to deliver services are capital.', 'TRUE — Support and repair work deploys skilled human resources classified as labour.'], '3/5', 8, 'full' ),
( '3.1', 'CASE 3.1.09', 'Combining production factors', 'Evaluate how businesses combine factors to create offerings:', ARRAY['Service firms combine labour with capital, technology, and entrepreneurial coordination.', 'A business combines factors of production to offer goods and/or services to customers.', 'Whichever factor is dominant replaces the need for any other factor.', 'Only manufacturing combines factors; services use labour alone.', 'Automated lines remove labour and knowledge from PCB production entirely.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Service delivery integrates multiple factors, not labour alone.', 'TRUE — Businesses exist by combining resources to deliver goods or services.', 'FALSE — One dominant factor does not remove the need to combine others.', 'FALSE — Service and manufacturing firms both combine multiple factors.', 'FALSE — Manufacturing still uses labour, knowledge, and coordination alongside capital.'], '3/5', 9, 'full' ),
( '3.1', 'CASE 3.1.10', 'Winemaker integrated factors', 'Assess factor use in a winemaker''s integrated operations:', ARRAY['Oak barrels held for ageing wine are capital supporting the production process.', 'Experience with fermentation adds knowledge alongside other factors in winemaking.', 'A winemaker with large vineyards combines land, labour, capital, and entrepreneurship.', 'Vineyard soil fertility is land; bottling machinery at the same site is capital.', 'Only permanent employees supply labour; seasonal staff are excluded.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Equipment and inventories used in production belong to capital.', 'TRUE — Knowledge and experience can be important production factors.', 'TRUE — Winemaking blends natural resources, workforce, equipment, and management.', 'TRUE — Natural resources are land; equipment is capital even on the same property.', 'FALSE — Seasonal and permanent workers both supply human resources as labour.'], '4/5', 10, 'full' ),
( '3.1', 'CASE 3.1.11', 'Entrepreneurship versus labour', 'Analyze distinctions between entrepreneurship and labour:', ARRAY['Entrepreneurship and capital are different: capital is resources used; entrepreneurship organises them.', 'Every planning hour is capital because plans are stored digitally.', 'Performing repairs while owning the shop can include both labour and entrepreneurship.', 'Founder coordination of suppliers and staff supplies entrepreneurship separate from task work.', 'Risk-bearing is labour because it consumes working hours.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Capital is resources; entrepreneurship coordinates those resources.', 'TRUE — Planning is human resource work; digital storage does not make it capital.', 'TRUE — Task work is labour; running and coordinating the venture is entrepreneurship.', 'TRUE — Organising factors is entrepreneurship; performing tasks is labour.', 'FALSE — Bearing uncertainty and coordinating resources is entrepreneurship.'], '3/5', 11, 'full' ),
( '3.1', 'CASE 3.1.12', 'Leased equipment as capital', 'Evaluate whether leased assets count as capital:', ARRAY['A leased bottling line still functions as capital for a winery in production.', 'Leased warehouse robots used beside manual pickers are capital in a distribution hub.', 'Renting premises means no installed tools count as capital.', 'Hire-purchase machines are land because they stand in a workshop.', 'Seasonal leases turn machinery into land because work happens outdoors.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Capital includes productive equipment whether owned or leased.', 'TRUE — Machinery used in operations is part of the capital factor.', 'FALSE — Leased premises do not reclassify installed tools away from capital.', 'FALSE — Equipment used in production is capital regardless of ownership form.', 'FALSE — Leased harvesters remain capital, not land.'], '2/5', 12, 'full' ),
( '3.1', 'CASE 3.1.13', 'Forestry crew and harvesters', 'A forestry crew fells timber using leased harvesters before winter closes mountain access. Analyze:', ARRAY['Crew members operating chainsaws and harvesters supply labour.', 'Supervision is labour only and never entrepreneurship in extraction.', 'Trees grow naturally, so logging uses land alone without other factors.', 'Harvesters are land because they operate on forest terrain.', 'Forests become capital once harvesters cut the first tree.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Workers deploying human effort in extraction supply labour.', 'FALSE — Coordinating haulage and crews is entrepreneurship.', 'FALSE — Logging still requires labour, capital, and coordination.', 'FALSE — Leased machinery is capital regardless of location.', 'FALSE — Standing forests remain land; harvesters are capital.'], '3/5', 13, 'full' ),
( '3.1', 'CASE 3.1.14', 'Financial resources as capital', 'Assess whether financial resources belong to capital:', ARRAY['Working capital financing payroll between invoice cycles is a financial capital input.', 'Funds borrowed to purchase diagnostic tools are capital applied to production.', 'Capital includes both physical equipment and financial resources used in production.', 'Share capital is the only form of capital a manufacturer may use.', 'Emergency cash is land because it is stored on business premises.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Financial resources supporting operations are part of capital.', 'TRUE — Finance used to acquire productive assets is part of capital.', 'TRUE — Capital covers machinery and finance applied to operations.', 'FALSE — Capital includes equipment and financial resources, not share capital alone.', 'FALSE — Cash held for operations is capital, not land.'], '3/5', 14, 'full' ),
( '3.1', 'CASE 3.1.15', 'Human skills in services', 'Evaluate labour in knowledge-intensive service work:', ARRAY['Only manufacturing floor workers count as labour; service staff are excluded.', 'Technical support staff troubleshooting home networks supply labour.', 'Freelance trainers delivering coaching sessions supply labour to the organising studio.', 'Human skills used to install software for a client count as labour.', 'Labour covers specialists and general staff alike when human resources are deployed.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Service employees are human resources and therefore part of labour.', 'TRUE — Support work is human resource deployment classified as labour.', 'TRUE — Trainers provide human resources classified as labour.', 'TRUE — Skilled technical work deploys human resources classified as labour.', 'TRUE — Labour includes all human resources used in production.'], '2/5', 15, 'full' ),
( '3.1', 'CASE 3.1.16', 'Graz tailor workshop', 'A Graz tailor orders sewing machines on hire-purchase and hires two apprentices for a growing workshop. Evaluate:', ARRAY['Fabric purchased for client orders is a material input combined with labour and machines.', 'The tailor selecting machines and scheduling orders supplies entrepreneurship.', 'Apprentices cutting patterns and stitching garments supply labour.', 'Tailoring needs only labour because designs exist in the tailor''s head.', 'Machines on hire-purchase are land because they occupy workshop space.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Production uses materials alongside labour and capital equipment.', 'TRUE — Organising inputs and production is an entrepreneurial function.', 'TRUE — Workers performing production tasks are human resources classified as labour.', 'FALSE — Tailoring also uses capital, materials, and coordination.', 'FALSE — Production equipment is capital regardless of hire-purchase.'], '3/5', 16, 'full' ),
( '3.1', 'CASE 3.1.17', 'PCB manufacturing inputs', 'Assess factors used in printed circuit board manufacturing:', ARRAY['Substrate clean-room tools and testing rigs are capital in secondary production.', 'Engineering teams monitoring laminate batches supply skilled labour.', 'PCB fabrication requires labour and materials as well as capital equipment.', 'AT&S combines workforce, materials, equipment, and entrepreneurial direction.', 'Knowledge of plating specifications applied on the line is a production factor.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Manufacturing equipment is part of the capital factor.', 'TRUE — Inspection and engineering work is skilled human resource use.', 'TRUE — Manufacturing blends human resources, materials, and machinery.', 'TRUE — Large manufacturers integrate all major factors in production.', 'TRUE — Technical knowledge used in manufacturing counts among production factors.'], '4/5', 17, 'full' ),
( '3.1', 'CASE 3.1.18', 'Technology in repair services', 'Analyze technology as a factor in IT repair work:', ARRAY['Replacing a screen combines labour with capital parts and may use technology tools.', 'A refurbished-laptop workshop uses tools, spare parts, and working capital together.', 'Tools make repairs capital-only with no labour or technology involved.', 'Intangible services exclude technology as a factor.', 'Licences are consumer subscriptions, not production technology.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Repair work integrates labour, capital inventories, and technology.', 'TRUE — Service production combines capital, technology, and labour.', 'FALSE — Repairs combine labour with technology and capital parts.', 'FALSE — Technology applies to services through tools and software used in delivery.', 'FALSE — Software tools used to perform services are technology factors.'], '3/5', 18, 'full' ),
( '3.1', 'CASE 3.1.19', 'Factor dominance patterns', 'Evaluate how dominant factors differ across industries:', ARRAY['Knowledge-intensive startups may lean on skills and technology more than heavy land use.', 'Manufacturing weighting capital heavily still leaves entrepreneurship coordinating production.', 'Land-heavy farming still combines labour, equipment, and management.', 'A firm''s dominant factor mix can differ by industry while still combining several inputs.', 'Automation removes all labour and entrepreneurship from capital-intensive plants.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Different businesses weight factors differently depending on activity.', 'TRUE — Entrepreneurship coordinates production even in capital-intensive plants.', 'TRUE — Agriculture integrates multiple factors beyond land alone.', 'TRUE — Industries emphasise different factors yet still combine multiple resources.', 'FALSE — Capital-intensive plants still use labour and coordination.'], '3/5', 19, 'full' ),
( '3.1', 'CASE 3.1.20', 'Vienna insurance claims office', 'A Vienna insurance branch trains new claims handlers on updated case software. Evaluate:', ARRAY['Claims handlers learning the new system supply labour in the branch.', 'Scheduling training is labour performed by calendars, not people.', 'Premises are land only, so computers there are land as well.', 'Insurance software is the tertiary sector itself, not a factor input.', 'Insurance requires only labour because policies are intangible.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Training and processing work deploys human resources as labour.', 'FALSE — Managers scheduling staff deploy labour and entrepreneurship.', 'FALSE — Premises may involve land; operational computers are capital.', 'FALSE — Software used to deliver services is a technology factor.', 'FALSE — Intangible services still use capital, technology, and coordination.'], '2/5', 20, 'full' ),
( '3.1', 'CASE 3.1.21', 'Carinthian dairy co-op upgrade', 'A Carinthian dairy co-op upgrades cooling tanks to handle higher daily milk volumes. Analyze:', ARRAY['The co-op board deciding on tank upgrades supplies entrepreneurship.', 'Milk from member farms links upstream to agricultural land and primary production.', 'Dairy processing at the co-op combines labour, capital, and coordination with upstream land inputs.', 'Cooling tanks and pasteurisers installed at the co-op are capital equipment.', 'Operators monitoring pasteurisation and tank levels supply labour at the co-op.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Strategic coordination of capital investment is entrepreneurial activity.', 'TRUE — Farm output draws on natural resources and primary activity.', 'TRUE — Processing integrates multiple factors beyond land alone.', 'TRUE — Processing machinery is part of the capital factor.', 'TRUE — Processing staff are human resources classified as labour.'], '3/5', 21, 'full' ),
( '3.1', 'CASE 3.1.22', 'Design know-how in software services', 'Assess knowledge as a factor in software-related services:', ARRAY['Training customers on new releases combines labour with knowledge and technology.', 'They use entrepreneurship alone without knowledge or tools.', 'Design stored on servers is capital, not knowledge.', 'Knowledge counts only after formal patent registration.', 'Coding skill is entrepreneurship because programmers take initiative.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Training deploys human resources plus knowledge and technology.', 'FALSE — Their model combines multiple production factors.', 'FALSE — Know-how applied to production is knowledge regardless of storage medium.', 'FALSE — Applied know-how is a factor without patents.', 'FALSE — Initiative on tasks is still labour; coordinating the firm is entrepreneurship.'], '4/5', 22, 'full' ),
( '3.1', 'CASE 3.1.23', 'Seasonal vineyard labour', 'Evaluate labour use in seasonal agricultural production:', ARRAY['A full-time cellar master and seasonal pickers both count as labour for a winery.', 'Seasonal pickers are volunteers outside the labour factor because pay is temporary.', 'Bottling during harvest adds labour alongside land and capital inputs.', 'Labour in harvest includes both pickers and supervisors coordinating field work.', 'Seasonal contracts exclude pickers from the labour factor.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — All human resources in production are classified as labour.', 'TRUE — Paid seasonal workers still supply human resources as labour.', 'TRUE — Processing tasks performed by workers are labour.', 'TRUE — Supervisors and pickers both deploy human resources as labour.', 'FALSE — Short-term paid workers still supply labour.'], '2/5', 23, 'full' ),
( '3.1', 'CASE 3.1.24', 'Vehicle fleet in logistics', 'Analyze capital and labour in delivery logistics:', ARRAY['Delivery vans used to ship circuit boards to customers are capital in manufacturing logistics.', 'Logistics combines capital equipment with labour and coordination.', 'Leased trucks stop being capital because the firm does not own them.', 'Drivers become capital because they operate vehicles.', 'Fuel is land because it comes from natural resources.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Vehicles used for production-related delivery are capital.', 'TRUE — Distribution integrates vehicles, drivers, and management.', 'FALSE — Leased vehicles used in operations are capital.', 'FALSE — Human operators are labour; vehicles remain capital.', 'FALSE — Fuel consumed in operations is an operating cost tied to capital use.'], '3/5', 24, 'full' ),
( '3.1', 'CASE 3.1.25', 'Innsbruck coaching studio', 'An Innsbruck coaching studio rents studio space and pays freelance trainers each month. Evaluate:', ARRAY['Rented studio space and booking systems are capital and technology supporting services.', 'Coaching combines labour with premises, systems, and owner coordination.', 'Freelance trainers delivering sessions supply labour to the studio.', 'Marketing courses is labour performed by customers, not the owner.', 'Freelance trainers replace entrepreneurship entirely in the studio.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Facilities and tools used to deliver services are capital and technology.', 'TRUE — Service delivery integrates multiple factors.', 'TRUE — Trainers provide human resources classified as labour.', 'FALSE — Organising offerings and bookings is entrepreneurship.', 'FALSE — Organisers still provide entrepreneurship alongside contractor labour.'], '3/5', 25, 'full' ),
( '3.1', 'CASE 3.1.26', 'Working capital and inventories', 'Assess working capital and inventories as capital:', ARRAY['Cash held to pay suppliers before customer invoices arrive is financial capital.', 'Financial and physical resources used in operations together form capital inputs.', 'Only long-term loans count as capital; day-to-day cash is excluded.', 'Farm-linked equipment is land because milk is agricultural.', 'Inventory is land when it contains metals from mining.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Financial resources supporting operations are part of capital.', 'TRUE — Capital includes both equipment and operating finance.', 'FALSE — Operating finance is included in capital.', 'FALSE — Processing machinery is capital even with agricultural inputs.', 'FALSE — Parts held for service production are capital inventories.'], '3/5', 26, 'full' ),
( '3.1', 'CASE 3.1.27', 'Burgenland vineyard barrels', 'A Burgenland vineyard buys oak barrels and contracts seasonal pickers before harvest. Analyze:', ARRAY['Oak barrels and bottling equipment held for ageing are capital inputs.', 'Barrel ageing combines land, labour, capital, knowledge, and coordination.', 'Contracted pickers and cellar staff supply labour during harvest and ageing.', 'Grapes are wants, so vineyards are not land.', 'Negotiating contracts is labour done by lawyers only, not entrepreneurs.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Equipment and inventories used in wine production are capital.', 'TRUE — Winemaking integrates multiple factors beyond land alone.', 'TRUE — Workers in production supply human resources as labour.', 'FALSE — Vineyards are natural resources within land.', 'FALSE — Organising contracts and inputs is entrepreneurship.'], '4/5', 27, 'full' ),
( '3.1', 'CASE 3.1.28', 'Production machinery roles', 'Evaluate capital equipment and labour on production lines:', ARRAY['Tooling consumed during extraction, such as drill bits in mining, is capital input.', 'Rental converts machinery into operating expense with no capital role.', 'Automated lines eliminate labour entirely from production.', 'Maintenance is capital because staff repair machines.', 'Automated lines are labour because engineers designed them.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Tools used up in production are capital inputs.', 'FALSE — Leased equipment used in production remains capital.', 'FALSE — Most lines still require labour for operation and maintenance.', 'FALSE — Maintenance workers are labour; machines remain capital.', 'FALSE — Designed machinery is capital; design work is knowledge and labour.'], '2/5', 28, 'full' ),
( '3.1', 'CASE 3.1.29', 'Local IT service factor mix', 'Assess combined factors in a local computer repair business:', ARRAY['Diagnostic tools and software licences represent technology in the service model.', 'Technicians replacing screens supply labour while spare parts inventory is capital.', 'Customer training on backups combines knowledge and labour in service delivery.', 'Repair shops combine labour, capital, technology, and coordination.', 'Owners coordinating bookings, parts, and repairs supply entrepreneurship.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Tools and software used to perform services are technology factors.', 'TRUE — Repair work is labour; parts held for service are capital.', 'TRUE — Training applies know-how through human resource work.', 'TRUE — Service firms integrate multiple factors in delivery.', 'TRUE — Organising the venture and bearing risk is entrepreneurship.'], '3/5', 29, 'full' ),
( '3.1', 'CASE 3.1.30', 'Integrated factor use', 'Review integrated use of production factors in business:', ARRAY['Smartphone makers may need PCBs from suppliers such as AT&S to keep production running.', 'Businesses provide goods and services by combining labour, land, capital, entrepreneurship, and often knowledge.', 'AT&S combines all major factors when manufacturing PCBs and IC substrates.', 'Tina and Steve illustrate combining knowledge, labour, technology, capital, and entrepreneurship.', 'Dominant factors replace all others in sector analysis.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Component suppliers combine factors to produce inputs other firms need.', 'TRUE — Production draws on multiple listed factors together.', 'TRUE — Large manufacturers integrate labour, materials, equipment, and coordination.', 'TRUE — Their venture uses skills, tools, finance, and coordination together.', 'FALSE — Dominance does not eliminate combined use of other factors.'], '3/5', 30, 'full' ),
( '3.1', 'CASE 3.1.31', 'Factor classification traps', 'Evaluate subtle misclassification of production factors:', ARRAY['Natural vineyards are land even when wine is a discretionary product.', 'Optional software makes installation a want, not labour.', 'Approved spending becomes entrepreneurship, not capital.', 'Vision is capital because it can attract money.', 'Machinery on farmland is land because the site is agricultural.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Vineyards are natural resources classified under land.', 'FALSE — Paid technical service work is labour.', 'FALSE — Money for equipment is capital; approval is entrepreneurial decision-making.', 'FALSE — Vision and coordination are entrepreneurship; attracted finance is capital.', 'FALSE — Processing equipment is capital even on agricultural land.'], '4/5', 31, 'full' ),
( '3.1', 'CASE 3.1.32', 'Mining supplier shutdown window', 'A mining supplier must deliver drill bits before a pit shutdown window closes. Evaluate:', ARRAY['Ore in the pit awaiting extraction represents land as natural resources.', 'Fulfilling the order still requires labour, materials, and coordination beyond capital alone.', 'Drill bits and transport crates held for the shipment are capital inputs.', 'Warehouse staff preparing the drill-bit shipment supply labour.', 'Deadlines convert coordination into labour with no entrepreneurship.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Mineral deposits are natural resources within the land factor.', 'TRUE — Delivery integrates multiple factors, not capital by itself.', 'TRUE — Tools and inventories used in extraction support are capital.', 'TRUE — Workers preparing and dispatching goods supply human resources as labour.', 'FALSE — Coordinating timed delivery is entrepreneurship.'], '5/5', 32, 'full' ),
( '3.1', 'CASE 3.1.33', 'Software support knowledge', 'Analyze knowledge and labour in software support services:', ARRAY['Installing updates for a client is skilled labour deploying human resources.', 'Coordinating the support business is entrepreneurship; performing support is labour.', 'Using computers converts support staff into capital.', 'Knowledge applies only inside factories that fabricate hardware.', 'Troubleshooting is capital because it uses routers and cables.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Paid technical service work is labour.', 'TRUE — Running the venture differs from performing tasks.', 'FALSE — Human operators remain labour; machines are capital.', 'FALSE — Knowledge also matters in service businesses.', 'FALSE — Support work is labour using capital tools.'], '1/5', 33, 'full' ),
( '3.1', 'CASE 3.1.34', 'Dominant factor identification', 'Assess identifying dominant factors without ignoring others:', ARRAY['Naming one dominant factor means other factors are irrelevant to production.', 'Capital-intensive plating lines still require labour, materials, and entrepreneurship.', 'A knowledge-intensive startup may weight skills and technology heavily while still using capital.', 'Service-heavy firms still rely on premises, tools, and finance as capital.', 'Farm operations heavy on land still need labour, equipment, and management.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Businesses combine factors even when one is most prominent.', 'TRUE — Heavy capital use does not eliminate other factors.', 'TRUE — Dominant factors differ by model without removing others.', 'TRUE — Service firms use capital alongside labour.', 'TRUE — Agriculture integrates multiple factors beyond land alone.'], '4/5', 34, 'full' ),
( '3.1', 'CASE 3.1.35', 'Distribution hub robots', 'A distribution hub adds warehouse robots while keeping manual pick teams for odd-shaped orders. Analyze:', ARRAY['Warehouse robots installed beside pick teams are capital equipment.', 'Storage racks and conveyors supporting the hub are capital.', 'Hub management integrating robots and manual teams supplies entrepreneurship.', 'Manual picking is capital because teams use gloves and carts.', 'Automation eliminates labour entirely in every distribution hub.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Automated machinery used in operations is capital.', 'TRUE — Facilities and machinery used in logistics are capital.', 'TRUE — Coordinating mixed systems and staffing is entrepreneurship.', 'FALSE — Pickers are labour; equipment they use is capital.', 'FALSE — Many hubs retain labour alongside capital equipment.'], '3/5', 35, 'full' ),
( '3.1', 'CASE 3.1.36', 'Matching resources to factors', 'Evaluate matching resource types to factor definitions:', ARRAY['Topsoil fertility on a vineyard slope is part of the land factor.', 'Mineral rights to an ore body represent land as a natural resource input.', 'Containers become land when they travel during haulage.', 'Farm-linked machines are land because milk is agricultural.', 'Containers are land because they cross regional borders.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Soil quality is a natural resource within land.', 'TRUE — Subsurface minerals are natural resources within land.', 'TRUE — Transport equipment remains capital during haulage.', 'FALSE — Processing machinery is capital.', 'FALSE — Transport equipment is capital, not land.'], '2/5', 36, 'full' ),
( '3.1', 'CASE 3.1.37', 'Mixed-factor service firms', 'Assess factor combination in tertiary service businesses:', ARRAY['Coaching studios combine rented premises, trainers'' labour, and owner coordination.', 'Tertiary firms exclude capital because services are intangible.', 'Insurance uses labour only because policies are intangible.', 'Repairs are labour-only because customers bring devices.', 'Training converts all inputs into tertiary output with no factors.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Services use capital, labour, and entrepreneurship together.', 'TRUE — Service firms still use premises, tools, and finance as capital.', 'FALSE — Insurance also uses technology, capital, and coordination.', 'FALSE — Workshops still use parts, tools, and technology.', 'FALSE — Training uses knowledge through labour.'], '5/5', 37, 'full' ),
( '3.1', 'CASE 3.1.38', 'Entrepreneurial coordination examples', 'Analyze entrepreneurship in coordinating other factors:', ARRAY['Coordinating a repair shop''s parts orders and bookings supplies entrepreneurship.', 'Scheduling PCB shifts while sourcing laminate reflects entrepreneurship at a manufacturer.', 'Integrating robots with manual pick teams reflects entrepreneurship in logistics.', 'Any purchase decision is entrepreneurship because it spends money.', 'Selecting barrel suppliers and picker contracts reflects entrepreneurship at a winery.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Organising resources and operations is entrepreneurship.', 'TRUE — Coordinating production inputs and timing is entrepreneurship.', 'TRUE — Designing how factors combine operationally is entrepreneurial work.', 'TRUE — Spending on capital is capital use; entrepreneurship organises factors.', 'TRUE — Organising inputs and contracts is entrepreneurial coordination.'], '2/5', 38, 'full' ),
( '3.1', 'CASE 3.1.39', 'Repair shop capital inputs', 'Assess capital and labour in a computer repair workshop:', ARRAY['The workshop combines labour, capital, technology, and coordination to deliver repairs.', 'Answering phones converts all activity into entrepreneurship with no labour.', 'Screen replacement is capital-only because parts are tangible goods.', 'Spare parts are wants sold to customers, not capital inputs.', 'Software licences are tertiary output and cannot be factor inputs.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Service firms integrate multiple factors in delivery.', 'FALSE — Performing repairs is labour; coordinating the firm is entrepreneurship.', 'FALSE — Installation work is labour; parts are capital.', 'FALSE — Parts held for service production are capital inventories.', 'FALSE — Tools used to deliver services are technology factors.'], '3/5', 39, 'full' ),
( '3.1', 'CASE 3.1.40', 'AT&S workforce and materials', 'Assess whether manufacturing can run on capital alone:', ARRAY['Plant managers coordinating shifts and suppliers supply entrepreneurship.', 'Quality inspectors monitoring batches supply skilled labour on the line.', 'PCB manufacturing requires engineers, operators, and materials alongside equipment.', 'Copper-clad laminate stored for production is a material input combined with capital.', 'Component plants run on capital alone once equipment is installed.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Coordinating production factors is entrepreneurship.', 'TRUE — Inspection work is skilled human resource use.', 'TRUE — Manufacturing still requires labour, materials, and coordination.', 'TRUE — Manufacturing uses materials alongside capital and labour.', 'FALSE — Manufacturing integrates labour, materials, equipment, and coordination.'], '4/5', 40, 'full' ),
( '3.1', 'CASE 3.1.41', 'Vineyard land versus barrels', 'Evaluate land and capital distinctions in winemaking:', ARRAY['Machinery on vineyard land is capital even though the site is agricultural.', 'Vineyard parcels and grape production draw on land as natural resources.', 'Fermentation knowledge applied to blending is a knowledge production factor.', 'River water rights used for irrigation represent natural-resource land inputs.', 'Barrels are land because oak originates from forests.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Equipment used in processing is capital, not land.', 'TRUE — Vineyards and agricultural output relate to the land factor.', 'TRUE — Production knowledge and experience are important factors.', 'TRUE — Water sources used in production are natural resources within land.', 'FALSE — Processed barrels used in production are capital.'], '2/5', 41, 'full' ),
( '3.1', 'CASE 3.1.42', 'Tina and Steve factor bundle', 'Analyze the factor bundle in a laptop repair and software venture:', ARRAY['Technical troubleshooting supplies labour as human resources.', 'Licensed diagnostic software and repair tools represent technology in the service model.', 'Refurbishing laptops uses spare parts inventory as capital.', 'The venture relies on entrepreneurship alone with no other factors.', 'Customer contact replaces all other factors in the venture.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Support and repair work deploys skilled human resources.', 'TRUE — Technology used to perform services is a production factor.', 'TRUE — Inventories used to deliver services are capital.', 'FALSE — Their repair and software work combines multiple production factors.', 'FALSE — Coordination and risk-bearing are entrepreneurship.'], '5/5', 42, 'full' ),
( '3.1', 'CASE 3.1.43', 'Entrepreneurship versus capital trap', 'Evaluate traps confusing entrepreneurship with capital:', ARRAY['Founder vision coordinating suppliers is entrepreneurship rather than capital.', 'Cash reserves are entrepreneurship because founders control spending.', 'Entrepreneurship and capital are interchangeable labels for spending.', 'Purchasing machinery converts spending entirely into entrepreneurship.', 'Borrowed finance is entrepreneurship because borrowing shows initiative.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Vision and coordination belong to entrepreneurship, not capital.', 'FALSE — Operating cash is capital; spending decisions may reflect entrepreneurship.', 'FALSE — Capital is resources used; entrepreneurship organises those resources.', 'FALSE — Purchasing equipment is capital use; organising purchases is entrepreneurship.', 'FALSE — Borrowed finance used for equipment is financial capital.'], '1/5', 43, 'full' ),
( '3.1', 'CASE 3.1.44', 'Knowledge in service firms', 'Assess knowledge as a factor outside manufacturing plants:', ARRAY['Design know-how for customer software counts as knowledge in service production.', 'Coding skill deployed on client projects is skilled labour using knowledge.', 'Technology and knowledge both matter in repair and software services.', 'Training customers on backups applies knowledge through skilled labour.', 'Experience with fermentation contributes knowledge to winemaking output.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Know-how applied to deliver services is part of knowledge as a factor.', 'TRUE — Programming work is labour applying know-how.', 'TRUE — Service firms apply know-how and tools alongside labour.', 'TRUE — Training deploys know-how via human resource work.', 'TRUE — Production knowledge and experience are important factors.'], '4/5', 44, 'full' ),
( '3.1', 'CASE 3.1.45', 'Seasonal and permanent labour', 'Evaluate labour classification for seasonal and permanent workers:', ARRAY['Insurance handlers trained on new software supply labour in a service branch.', 'Seasonal grape pickers supply labour even when contracts last only weeks.', 'Only permanent employees can supply labour in production.', 'Freelancers replace entrepreneurship entirely in a coaching studio.', 'Specialists supply entrepreneurship only, not labour.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Office and service staff are human resources classified as labour.', 'TRUE — Short-term workers are human resources within the labour factor.', 'FALSE — Permanent and seasonal workers both supply labour.', 'FALSE — Contractors supply labour; the organiser provides entrepreneurship.', 'FALSE — Specialists deploying human effort are labour.'], '2/5', 45, 'full' ),
( '3.1', 'CASE 3.1.46', 'Factor combination requirement', 'Assess whether businesses can rely on a single factor:', ARRAY['PCB production blends labour, capital, materials, knowledge, and coordination.', 'Dominant factor emphasis in an industry removes other factors from production.', 'A firm can deliver goods using one dominant factor without combining others.', 'Services need only labour because output is intangible.', 'Winemaking needs only land because grapes ripen naturally.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Manufacturing integrates multiple factors rather than one alone.', 'TRUE — Businesses combine factors even when one appears dominant.', 'FALSE — Businesses combine multiple factors rather than one alone.', 'FALSE — Services still rely on capital, technology, and coordination.', 'FALSE — Winemaking also requires labour, capital, and management.'], '3/5', 46, 'full' ),
( '3.1', 'CASE 3.1.47', 'Financial and physical capital', 'Evaluate financial resources alongside physical capital:', ARRAY['Equipment, plant, vehicles, and operating finance applied in production count as capital.', 'Entrepreneurship replaces capital once founders approve equipment purchases.', 'Leased bottling lines and hired harvesters still function as capital.', 'Working capital financing payroll between invoice cycles is financial capital.', 'Spare parts inventory for repairs is capital supporting service delivery.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Capital includes equipment and financial resources.', 'TRUE — Purchasing equipment is capital; organising purchases is entrepreneurship.', 'TRUE — Leased productive equipment still counts as capital.', 'TRUE — Financial resources supporting operations are part of capital.', 'TRUE — Inventories used in operations belong to capital.'], '3/5', 47, 'full' ),
( '3.1', 'CASE 3.1.48', 'Integrated production examples', 'Review integrated factor use in chapter examples:', ARRAY['Identifying one example factor in a firm eliminates the need to consider others.', 'Tina and Steve show how knowledge, labour, technology, capital, and entrepreneurship work together.', 'Smartphone makers needing PCBs from suppliers such as AT&S rely on combined factors upstream.', 'A winemaker illustrates combining land, labour, capital, entrepreneurship, and experience.', 'AT&S illustrates capital-only production without workforce.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Businesses combine factors even when examples emphasise one.', 'TRUE — Their venture uses skills, tools, finance, and coordination.', 'TRUE — Component suppliers combine factors to produce inputs.', 'TRUE — Winemaking blends multiple listed factors.', 'FALSE — Manufacturing integrates labour, materials, equipment, and coordination.'], '2/5', 48, 'full' ),
( '3.1', 'CASE 3.1.49', 'Land versus capital on one site', 'Evaluate land and capital distinctions on the same production site:', ARRAY['Bottling machinery installed beside the vines is capital.', 'Harvest coordination is labour performed by grapes, not entrepreneurs.', 'Vines are wants, so vineyards are excluded from the land factor.', 'Agricultural sites use land alone without labour or equipment.', 'Pickers are land inputs because they work among vines.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Equipment used in processing is capital.', 'FALSE — Coordinating harvest and equipment is entrepreneurship.', 'FALSE — Vineyards are natural resources classified under land.', 'FALSE — Farming and processing combine multiple factors.', 'FALSE — Seasonal workers are human resources classified as labour.'], '3/5', 49, 'full' ),
( '3.1', 'CASE 3.1.50', 'Chapter 3.1 synthesis', 'Assess integrated claims about factors of production:', ARRAY['Businesses combine labour, land, capital, entrepreneurship, and often knowledge to create offerings.', 'AT&S illustrates combining all major factors in PCB and substrate manufacturing.', 'Their refurbished-laptop venture combines knowledge, labour, technology, capital, and entrepreneurship.', 'Winemaking illustrates land-only production in agriculture.', 'Dominant factors make other factors irrelevant in analysis.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Production typically integrates multiple listed factors.', 'TRUE — Large manufacturers integrate workforce, materials, equipment, and coordination.', 'TRUE — Their venture uses skills, tools, finance, and coordination together.', 'FALSE — Winemaking combines multiple factors beyond land.', 'FALSE — Dominance does not remove combined use of other factors.'], '4/5', 50, 'full' ),
( '3.2', 'CASE 3.2.01', 'Three-sector model basics', 'Evaluate claims about the primary, secondary, and tertiary sectors:', ARRAY['Mining ore is primary-sector activity while smelting metal ingots is secondary.', 'The tertiary sector comprises services such as banking, insurance, and coaching.', 'The primary sector covers farming, fishing, mining, and forestry extracting raw materials.', 'Banking and insurance belong to the primary sector because they are basic needs.', 'The secondary sector delivers banking and insurance services to households.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Mining is primary; smelting and manufacturing are secondary.', 'TRUE — Tertiary activity delivers services rather than extracting or manufacturing goods.', 'TRUE — Primary activity extracts raw materials from the earth.', 'FALSE — Banking and insurance are tertiary services, not primary extraction.', 'FALSE — Banking and insurance are tertiary services, not secondary manufacturing.'], '3/5', 1, 'full' ),
( '3.2', 'CASE 3.2.02', 'Tyrolean ski resort services', 'A Tyrolean ski resort hires instructors and sells lift passes to local visitors. Evaluate:', ARRAY['Selling lift passes and ski instruction are tertiary services.', 'Instructors supply capital because they teach on mountain slopes.', 'Manufacturing skis on site would remain tertiary because guests consume the experience.', 'Guest services at a ski resort are primary extraction because snow is natural.', 'The resort belongs to the primary sector because it operates on a mountainside.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Recreation services and instruction are tertiary activity.', 'FALSE — Human resources delivering services are classified as labour.', 'FALSE — Producing physical goods from materials is secondary manufacturing.', 'FALSE — Natural setting does not reclassify service delivery as primary extraction.', 'FALSE — Location does not make a service business primary; activity type determines sector.'], '2/5', 2, 'full' ),
( '3.2', 'CASE 3.2.03', 'Primary sector activities', 'Analyze classification of primary-sector activity:', ARRAY['A coal mine extracting ore belongs to the primary sector.', 'An olive farm harvesting and pressing oil performs primary agricultural activity.', 'Forestry concessions supplying logs to mills belong to the primary sector.', 'Milling logs into export boards at a timber mill is secondary manufacturing.', 'Commercial fishing that lands herring for sale is primary-sector extraction.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Mining extracts raw materials and is primary-sector activity.', 'TRUE — Growing and harvesting crops is primary-sector activity.', 'TRUE — Forestry extracts natural resources and is primary activity.', 'TRUE — Milling into boards is secondary manufacturing.', 'TRUE — Commercial fishing extracts natural resources and is primary activity.'], '3/5', 3, 'full' ),
( '3.2', 'CASE 3.2.04', 'Secondary manufacturing', 'Assess what counts as secondary-sector manufacturing:', ARRAY['Retail sale of finished jackets is tertiary distribution or trade.', 'Warehousing steel before welding is a tertiary logistics service.', 'A car plant assembling vehicles operates in the tertiary sector because it serves customers.', 'A fashion label sewing jackets performs tertiary retail because jackets are sold later.', 'Smelters shaping metal remain primary because ore originates underground.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Selling to consumers is tertiary distribution/trade.', 'TRUE — Warehousing and logistics are tertiary services.', 'FALSE — Vehicle assembly from processed materials is secondary manufacturing.', 'FALSE — Garment production from materials is secondary even if products are later retailed.', 'FALSE — Processing ore or metal into usable forms is secondary transformation.'], '2/5', 4, 'full' ),
( '3.2', 'CASE 3.2.05', 'Flood rebuild and GDP', 'After floods a municipality rebuilds bridges and the spending enters national accounts. Analyze:', ARRAY['Measured GDP can rise after ecological disasters that require infrastructure repair.', 'Construction spending on bridge rebuilds is included in GDP measurement.', 'Rebuild spending can raise measured GDP while citizen wellbeing falls.', 'GDP reflects monetary value of final goods and services produced within national borders.', 'Rebuild activity proves GDP always equals citizen wellbeing after disasters.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Disaster recovery spending increases GDP even when welfare falls.', 'TRUE — Rebuild spending adds to measured GDP.', 'TRUE — GDP can increase from rebuilds even when underlying welfare declined.', 'TRUE — GDP sums final domestic production over a defined period.', 'FALSE — GDP can rise from rebuilds even when underlying welfare declined.'], '4/5', 5, 'full' ),
( '3.2', 'CASE 3.2.06', 'Tertiary services scope', 'Evaluate the scope of tertiary-sector services:', ARRAY['Banking branches providing loans perform tertiary financial services.', 'Remote coaching sessions sold to foreign clients are tertiary services.', 'Smelting metal ingots from ore on site is secondary manufacturing.', 'Software helpdesks troubleshooting home networks provide tertiary services.', 'Insurance cooperatives processing claims provide primary extraction services.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Banking is classified within the tertiary sector.', 'TRUE — Coaching is a service regardless of client location.', 'TRUE — Smelting and manufacturing belong to the secondary sector.', 'TRUE — Technical support is a tertiary service.', 'FALSE — Insurance is a financial service, not resource extraction.'], '4/5', 6, 'full' ),
( '3.2', 'CASE 3.2.07', 'Emerging economy sector mix', 'Analyze sector patterns in emerging economies:', ARRAY['Heavy farming employment in less developed countries signals primary-sector dominance.', 'Primary-sector share typically shrinks as economic development advances.', 'Emerging economies show smaller primary shares than advanced EU states.', 'Emerging economies typically report tertiary output above seventy percent of GDP.', 'Advanced services above seventy percent of output characterises most emerging economies.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Emerging countries often rely heavily on primary-sector output.', 'TRUE — Development shifts activity toward secondary and tertiary sectors.', 'FALSE — Emerging countries often rely heavily on primary-sector output.', 'FALSE — Emerging economies depend more on primary activity, not dominant tertiary shares.', 'FALSE — Emerging economies depend more on primary activity rather than dominant tertiary shares.'], '2/5', 7, 'full' ),
( '3.2', 'CASE 3.2.08', 'Olive farm and PCB order', 'A Croatian farm sells olive oil while a Linz factory fills a PCB production order. Evaluate:', ARRAY['PCB fabrication transforms materials and therefore belongs to secondary manufacturing.', 'The farm is secondary because bottled oil is a processed product.', 'Both activities belong to the tertiary sector because each sells to customers.', 'Fabricating PCBs from laminate is tertiary because components go to other businesses.', 'Harvesting and pressing olives on the farm is tertiary because oil is sold to customers.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Component production transforms materials into manufactured goods.', 'FALSE — Agricultural production and harvesting remain primary even if some processing occurs on farm.', 'FALSE — Selling does not reclassify farming or manufacturing into services.', 'FALSE — Manufacturing for business customers remains secondary activity.', 'FALSE — Agricultural production remains primary even when products are sold.'], '1/5', 8, 'full' ),
( '3.2', 'CASE 3.2.09', 'Developed EU tertiary share', 'Assess tertiary dominance in advanced European economies:', ARRAY['Advanced EU economies are service-dominated despite the importance of food production.', 'In highly developed EU economies the tertiary sector often exceeds seventy percent of output.', 'Higher GDP per capita in EU member states links to high living standards in the model.', 'A seventy percent-plus service share reflects primary dominance in advanced economies.', 'Developed EU states keep primary output above seventy percent because food is essential.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Developed EU economies are service-dominated despite food importance.', 'TRUE — Advanced EU countries typically see services dominate total output.', 'TRUE — GDP per capita is used as a living-standard indicator.', 'FALSE — High tertiary shares typify advanced, not primary-dominated, economies.', 'FALSE — In developed EU countries the tertiary sector usually exceeds seventy percent.'], '3/5', 9, 'full' ),
( '3.2', 'CASE 3.2.10', 'GDP definition', 'Evaluate how gross domestic product is defined:', ARRAY['GDP counts final goods and services rather than intermediate goods sold between factories.', 'GDP is usually calculated for final production within one year inside national borders.', 'GDP totals the monetary value of final goods and services produced within a country''s borders.', 'GDP measures production within borders regardless of firm nationality.', 'Final services such as insurance produced domestically enter GDP totals.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — GDP avoids double counting by focusing on final output.', 'TRUE — GDP typically refers to annual domestic final production.', 'TRUE — GDP measures final domestic production over a defined period.', 'TRUE — GDP is based on geography of production.', 'TRUE — GDP includes final services produced within borders.'], '5/5', 10, 'full' ),
( '3.2', 'CASE 3.2.11', 'EU services at seventy-four percent', 'A GDP report for an EU member state shows services at seventy-four percent of total output. Analyze:', ARRAY['Service share alone does not prove every component of GDP is environmentally sustainable.', 'Seventy-four percent services indicates tertiary dominance rather than primary leadership.', 'Such a share is typical for economically advanced EU countries.', 'Seventy-four percent service share fits a highly developed EU economy pattern.', 'That pattern reflects rising relative importance of tertiary activity with development.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — GDP share does not by itself show sustainability of growth.', 'TRUE — The reported figure shows services dominating total output.', 'TRUE — High tertiary shares characterise advanced EU states.', 'TRUE — Advanced EU economies often exceed seventy percent tertiary output.', 'TRUE — More developed economies shift toward services in the three-sector model.'], '5/5', 11, 'full' ),
( '3.2', 'CASE 3.2.12', 'GDP growth measure', 'Analyze how GDP growth is assessed over time:', ARRAY['GDP growth compares inflation-adjusted GDP across years.', 'Real GDP per capita can rise after stripping out inflation from nominal figures.', 'Real GDP strips price changes to compare volume of production over time.', 'Nominal GDP increases always equal real economic growth.', 'Ignoring inflation never affects growth comparisons between years.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Real growth uses GDP adjusted for inflation.', 'TRUE — Inflation-adjusted per capita figures support growth comparisons.', 'TRUE — Inflation adjustment isolates real output changes.', 'FALSE — Price rises can inflate nominal GDP without real output gains.', 'FALSE — Real comparisons generally require inflation adjustment.'], '3/5', 12, 'full' ),
( '3.2', 'CASE 3.2.13', 'Remote coaching abroad', 'An Estonian coach delivers remote training sessions to clients in other countries. Evaluate:', ARRAY['Remote delivery to foreign clients keeps the activity tertiary.', 'Exporting advice does not convert coaching into secondary manufacturing.', 'Remote coaching is primary because trainers work from home offices.', 'Because no goods cross borders, the activity cannot be counted in GDP.', 'Human coaching skills are classified as land, so remote training is primary extraction.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Coaching remains a service regardless of client location.', 'TRUE — Coaching stays a service even when clients are abroad.', 'FALSE — Delivery location does not turn a service into primary activity.', 'FALSE — Services produced domestically can count in home-country GDP.', 'FALSE — Coaching is a tertiary service, not extraction of raw materials.'], '2/5', 13, 'full' ),
( '3.2', 'CASE 3.2.14', 'Coal mine and car plant quarter', 'A Romanian coal mine and a Graz car plant report output in the same quarter. Analyze:', ARRAY['Coal extraction at the mine is primary-sector activity.', 'Vehicle assembly at the car plant is secondary manufacturing.', 'Steel inputs from mining do not make vehicle assembly primary activity.', 'Office staff at a mine or plant do not reclassify core production into tertiary services.', 'Both plants belong to the tertiary sector because they employ office staff.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Mining extracts raw materials and is primary activity.', 'TRUE — Assembling cars from materials is secondary activity.', 'TRUE — Assembly of vehicles is secondary even if inputs came from mining.', 'TRUE — Core extraction and manufacturing sectors remain primary and secondary.', 'FALSE — Office staff do not reclassify extraction or manufacturing into services.'], '4/5', 14, 'full' ),
( '3.2', 'CASE 3.2.15', 'GDP income coverage critique', 'Assess criticisms that GDP misses some income:', ARRAY['GDP omission of some income sources is one reason its use is debated.', 'Every barter transaction is always fully recorded in official GDP.', 'Unpaid home maintenance done by owners is always included in GDP.', 'GDP fully captures household volunteering and unpaid care in its totals.', 'Barter exchanges between neighbours are always fully counted in official GDP totals.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Incomplete income coverage contributes to GDP criticism.', 'FALSE — Informal and non-market activity is often missed by GDP.', 'FALSE — Non-market unpaid work is typically outside GDP scope.', 'FALSE — GDP is criticised for omitting unpaid and informal activity.', 'FALSE — Informal barter and non-market activity is often missed by GDP.'], '1/5', 15, 'full' ),
( '3.2', 'CASE 3.2.16', 'Insurance branch and wheat farm', 'An insurance cooperative processes claims while a nearby farm harvests wheat. Evaluate:', ARRAY['Farm output and insurance services can coexist as primary and tertiary activity.', 'Both operations are tertiary because each serves customers.', 'Claims handling at the insurance branch is primary because policies cover basic risks.', 'Harvesting wheat is secondary manufacturing because flour milling follows.', 'Paying insurance claims classifies the cooperative as primary because policies cover crops.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Different sectors operate side by side in the same economy.', 'FALSE — Customer service does not make farming tertiary.', 'FALSE — Insurance is a financial service, not resource extraction.', 'FALSE — Harvesting crops is primary even if downstream milling is secondary.', 'FALSE — Paying claims is a financial service, not crop extraction.'], '3/5', 16, 'full' ),
( '3.2', 'CASE 3.2.17', 'Sustainability and GDP quality', 'Evaluate GDP as an indicator of sustainable or high-quality growth:', ARRAY['GDP does not tell whether growth damages resources or wellbeing.', 'GDP alone reveals little about the quality or sustainability of economic growth.', 'Rebuilds after disasters can raise GDP without improving quality of life.', 'Rising GDP may coincide with pollution or resource depletion.', 'Quality concerns are unrelated to debates about GDP as a welfare measure.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — GDP misses quality and sustainability dimensions critics highlight.', 'TRUE — GDP does not by itself show sustainability or quality of growth.', 'TRUE — Measured output can rise while welfare remains impaired.', 'TRUE — Output can grow without environmental improvement.', 'FALSE — Quality and sustainability are standard GDP criticisms.'], '5/5', 17, 'full' ),
( '3.2', 'CASE 3.2.18', 'Port warehouse and shipyard', 'A port warehouse stores imported steel before a shipyard welds hull sections. Analyze:', ARRAY['Mining origins of steel do not make warehousing or shipbuilding primary.', 'The chain shows tertiary logistics feeding secondary production.', 'Welding hull sections at the shipyard is secondary manufacturing.', 'Converting steel plate into finished hulls transforms raw materials into goods.', 'Warehousing imported steel before fabrication is a tertiary logistics service.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Downstream storage and shipbuilding are not primary extraction.', 'TRUE — Services can support manufacturing downstream.', 'TRUE — Building ships from materials is secondary activity.', 'TRUE — Shipbuilding transforms raw materials into manufactured goods.', 'TRUE — Storage and logistics are tertiary services.'], '3/5', 18, 'full' ),
( '3.2', 'CASE 3.2.19', 'Clinic expansion and real GDP', 'A Prague clinic expands while real GDP per capita rises after inflation adjustment. Evaluate:', ARRAY['Real GDP per capita rising after inflation adjustment indicates real growth.', 'Basic need status does not reclassify healthcare delivery as primary activity.', 'Nominal GDP increases alone do not prove real growth without price adjustment.', 'Clinic growth is primary because health is a basic need.', 'Healthcare expansion cannot occur while real GDP per capita rises.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Inflation-adjusted GDP supports real growth comparisons.', 'TRUE — Healthcare provision is tertiary service activity.', 'TRUE — Real growth requires adjusting for inflation.', 'FALSE — Healthcare provision is tertiary service activity.', 'FALSE — Sector activity contributes to overall measured GDP growth.'], '4/5', 19, 'full' ),
( '3.2', 'CASE 3.2.20', 'Disaster rebuild GDP effect', 'Assess how disaster recovery affects measured GDP:', ARRAY['Rebuilding infrastructure after ecological damage can raise measured GDP.', 'Construction wages paid during disaster recovery count toward measured GDP.', 'GDP rising after disasters proves living standards improved.', 'Cleanup spending automatically reduces GDP because it repairs harm.', 'Disaster rebuilds exclude construction wages from GDP to avoid counting damage twice.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Disaster recovery spending adds to GDP even when welfare falls.', 'TRUE — Recovery spending on construction adds to GDP totals.', 'FALSE — GDP may rise from rebuilds without restoring lost welfare.', 'FALSE — Recovery and rebuild spending adds to measured output.', 'FALSE — Rebuild spending is included and can raise GDP.'], '1/5', 20, 'full' ),
( '3.2', 'CASE 3.2.21', 'Fishing fleet and fashion label', 'A fishing fleet lands herring while a fashion label sews jackets from imported fabric. Analyze:', ARRAY['Garment manufacturing from imported fabric is secondary activity.', 'Landing herring for sale is primary-sector fishing activity.', 'Onboard filleting converts commercial fishing into secondary processing.', 'Both firms are primary because they use natural or imported inputs.', 'Fashion sewing is tertiary because designs are creative services.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Garment production from materials is secondary activity.', 'TRUE — Commercial fishing extracts resources and is primary activity.', 'FALSE — Extracting fish remains primary-sector activity.', 'FALSE — Garment manufacturing is secondary, not primary.', 'FALSE — Sewing garments is manufacturing in the secondary sector.'], '2/5', 21, 'full' ),
( '3.2', 'CASE 3.2.22', 'Tina and Steve sector classification', 'Classify Tina and Steve''s trading, software, and support activities:', ARRAY['Developing software for customers is tertiary service activity.', 'Refurbishing laptops and providing support are tertiary service activities.', 'Tina and Steve trade goods, develop software, and provide technical support in the tertiary sector.', 'Minerals inside devices do not reclassify their support activity as primary extraction.', 'Handling physical laptops does not move their support work into secondary manufacturing.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Software services are tertiary, not manufacturing, in this context.', 'TRUE — Repair and support are tertiary service activities.', 'TRUE — Their activities are classified as services in the tertiary sector.', 'TRUE — Using devices does not make their support activity primary.', 'TRUE — Repair and support are services even when goods are involved.'], '5/5', 22, 'full' ),
( '3.2', 'CASE 3.2.23', 'Mining pit and smelters chain', 'A mining firm extracts ore; other firms smelt metal and manufacture machinery. Evaluate:', ARRAY['Smelters that transform raw ore into metal operate in the secondary sector.', 'Smelting ore into metal is still primary extraction rather than manufacturing.', 'Mining, smelting and making machinery are all primary because they start from natural resources.', 'Manufacturing machinery from smelted metal remains primary because the metal originally came from mining.', 'Extracting ore from the earth (mining) belongs to the secondary sector, not the primary sector.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — The secondary sector transforms raw materials into goods (manufacturing).', 'FALSE — Transforming raw materials into goods is secondary; primary is extraction (e.g. mining).', 'FALSE — Only extraction of raw materials from the earth is primary; later manufacturing stages are secondary.', 'FALSE — Making machinery is manufacturing in the secondary sector.', 'FALSE — Mining is primary: extraction of raw materials from the earth.'], '2/5', 23, 'full' ),
( '3.2', 'CASE 3.2.24', 'Inflation-adjusted growth', 'Analyze the role of inflation adjustment in GDP growth:', ARRAY['Comparing GDP across years requires adjusting for inflation to measure real growth.', 'Inflation adjustment is generally required for meaningful real growth comparisons.', 'Nominal and real growth align closely when prices are stable.', 'Ignoring inflation can overstate growth when prices rise faster than output.', 'Real GDP includes all price changes when comparing production over time.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Real growth uses inflation-adjusted GDP.', 'TRUE — Real comparisons generally require inflation adjustment.', 'TRUE — With stable prices nominal and real growth align closely.', 'TRUE — Nominal figures can inflate apparent growth without real gains.', 'FALSE — Real growth uses GDP adjusted for inflation.'], '1/5', 24, 'full' ),
( '3.2', 'CASE 3.2.25', 'Bookstore distribution branch', 'A bookstore branch distributes publishers'' titles to local readers. Analyze:', ARRAY['Printing the titles at a publisher''s plant is secondary manufacturing.', 'Retail trade of printed titles is tertiary activity.', 'Distributing publishers'' titles to readers is tertiary distribution activity.', 'Book sales are secondary because books are physical products.', 'Reading promotion events turn bookstores into primary agriculture.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Printing books is manufacturing in the secondary sector.', 'TRUE — Retail trade of goods is tertiary activity.', 'TRUE — Distribution to customers is tertiary-sector activity.', 'FALSE — Retail and distribution of goods are tertiary even for physical products.', 'FALSE — Book-related services remain tertiary.'], '4/5', 25, 'full' ),
( '3.2', 'CASE 3.2.26', 'Well-being correlation', 'Evaluate GDP correlation with health and happiness indicators:', ARRAY['GDP is often correlated with indicators such as health status and happiness.', 'Cross-country data often link higher GDP with better health and happiness scores.', 'GDP critics still note correlation with some wellbeing measures.', 'Correlation implies GDP captures every aspect of wellbeing perfectly.', 'Cross-country data show no link between GDP and health outcomes.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Higher GDP frequently aligns with better health and happiness scores.', 'TRUE — GDP correlates with health and happiness though it does not measure all welfare.', 'TRUE — The text acknowledges correlation despite GDP limits.', 'FALSE — Correlation does not mean GDP fully measures welfare.', 'FALSE — GDP is usually correlated with wellbeing indicators.'], '3/5', 26, 'full' ),
( '3.2', 'CASE 3.2.27', 'Forestry and furniture plant', 'A forestry concession supplies logs to a furniture plant finishing dining tables. Evaluate:', ARRAY['The link illustrates primary output feeding secondary production.', 'Finishing tables for dining rooms is tertiary because buyers are households.', 'Selling dining tables to households converts furniture production into tertiary distribution.', 'Both stages are secondary because furniture is sold to households.', 'Harvesting logs in forestry is secondary because timber is processed into furniture.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Primary extraction commonly supplies secondary manufacturers.', 'FALSE — Manufacturing furniture is secondary, not tertiary.', 'FALSE — Manufacturing furniture is secondary even when sold to households.', 'FALSE — Logging remains primary even if output later becomes furniture.', 'FALSE — Forestry extracts raw materials and is primary activity.'], '3/5', 27, 'full' ),
( '3.2', 'CASE 3.2.28', 'AT&S secondary role', 'Assess AT&S manufacturing PCBs and IC substrates:', ARRAY['Client technical advice alongside fabrication does not remove secondary classification.', 'Manufactured components are secondary-sector output regardless of input origins.', 'Selling components to smartphone makers keeps fabrication in secondary manufacturing.', 'Transforming laminate into PCBs is secondary manufacturing.', 'AT&S is tertiary because it sells to smartphone makers, not consumers.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Fabricating boards remains secondary even if advice accompanies sales.', 'TRUE — Manufactured components are secondary-sector output.', 'TRUE — Manufacturing for business customers remains secondary activity.', 'TRUE — Manufacturing components from materials is secondary activity.', 'FALSE — Selling to firms does not reclassify manufacturing as services.'], '1/5', 28, 'full' ),
( '3.2', 'CASE 3.2.29', 'Sector assignment traps', 'Evaluate subtle sector misclassification traps:', ARRAY['Retail distribution of finished goods belongs to the tertiary sector.', 'A software helpdesk is tertiary even when supporting manufactured devices.', 'Manufacturing and after-sales service mean the entire firm is tertiary.', 'Printing books and bookstore distribution are both secondary.', 'A firm offering both manufacturing and repair must be classified entirely as secondary.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Distribution is a service activity within the tertiary sector.', 'TRUE — Technical support is a tertiary service.', 'FALSE — Manufacturing stays secondary; services can be tertiary alongside it.', 'FALSE — Manufacturing and distribution occupy different sectors.', 'FALSE — After-sales repair is tertiary even when the firm also manufactures.'], '4/5', 29, 'full' ),
( '3.2', 'CASE 3.2.30', 'GDP border rule', 'Analyze the geographic rule for GDP measurement:', ARRAY['GDP measures production within a country''s borders regardless of firm nationality.', 'Final goods produced domestically within a year enter GDP totals.', 'Output from a domestic plant of a foreign-owned firm counts in that country''s GDP.', 'Foreign production by domestic firms is counted where it occurs, not in home GDP.', 'Production inside national borders determines whether output enters GDP totals.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — GDP is based on geography of production.', 'TRUE — Domestic final production in the period is counted.', 'TRUE — Location of production determines GDP inclusion.', 'TRUE — Foreign production is counted where it occurs, not in home GDP.', 'TRUE — GDP measures territorial output regardless of firm ownership.'], '2/5', 30, 'full' ),
( '3.2', 'CASE 3.2.31', 'Quality of growth critique', 'Assess limits of GDP regarding growth quality:', ARRAY['Disaster rebuild spending can lift GDP without restoring lost wellbeing.', 'Quality concerns are part of why GDP use is debated.', 'GDP totals value produced without automatically distinguishing harmful from beneficial output.', 'GDP does not show whether growth improves environmental conditions.', 'Rising GDP necessarily proves growth is environmentally sustainable.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Measured output can rise while welfare remains impaired.', 'TRUE — Quality and sustainability are standard GDP criticisms.', 'TRUE — GDP totals value produced, not whether output is beneficial.', 'TRUE — GDP does not by itself show sustainability or quality.', 'FALSE — GDP does not by itself show sustainability or quality.'], '5/5', 31, 'full' ),
( '3.2', 'CASE 3.2.32', 'Banking as tertiary', 'Evaluate banking within the three-sector model:', ARRAY['Banking branches providing loans are tertiary financial services.', 'Money used in banking is not classified as a natural resource making banking primary.', 'A national bank serving only home customers becomes secondary.', 'Insurance and banking both belong to the secondary sector.', 'Banking is secondary because it funds manufacturing clients.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Banking is classified within the tertiary sector.', 'TRUE — Banking is a financial service, not resource extraction.', 'FALSE — Financial services stay tertiary regardless of customer location.', 'FALSE — Financial services are tertiary activity.', 'FALSE — Financing manufacturers does not turn banking into manufacturing.'], '3/5', 32, 'full' ),
( '3.2', 'CASE 3.2.33', 'Shipbuilding sector type', 'Classify shipyard activity in the three-sector model:', ARRAY['Steel import storage and hull welding occupy different sectors.', 'Later cargo transport at sea does not reclassify shipbuilding as tertiary.', 'Port warehousing before welding is tertiary logistics.', 'Painting finished hulls for delivery remains secondary manufacturing support.', 'Welding hull sections from steel plate is secondary manufacturing.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Warehousing is tertiary; welding is secondary.', 'TRUE — Building ships is manufacturing, not service delivery.', 'TRUE — Storage before manufacturing is a tertiary service.', 'TRUE — Finishing manufactured vessels remains secondary activity.', 'TRUE — Building ships from materials is secondary activity.'], '2/5', 33, 'full' ),
( '3.2', 'CASE 3.2.34', 'Service share measurement', 'Analyze measuring tertiary share in total output:', ARRAY['Advanced economies often see services dominate total output shares.', 'Tertiary share is measured separately from GDP totals.', 'Primary share above seventy percent typifies rich EU economies.', 'Service share alone identifies every firm''s sector classification.', 'Less developed economies typically show smaller primary shares than advanced EU states.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — High service shares show tertiary dominance in advanced economies.', 'FALSE — Sector shares are derived from GDP output breakdowns.', 'FALSE — High tertiary, not primary, shares typify advanced EU states.', 'FALSE — Aggregate shares differ from individual firm sector labels.', 'FALSE — Less developed countries depend more on primary activity.'], '4/5', 34, 'full' ),
( '3.2', 'CASE 3.2.35', 'Economic activity indicator', 'Evaluate GDP as an overall activity indicator:', ARRAY['GDP per capita indicates standard of living in the chapter''s framing.', 'GDP does not replace all other indicators because it misses some income sources.', 'GDP counts final goods and services produced in a defined period.', 'GDP excludes final services such as insurance from its totals.', 'Banking services are excluded from GDP because they produce no physical goods.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — GDP per capita is linked to living standards.', 'TRUE — GDP misses some informal and unpaid activity.', 'TRUE — GDP covers final domestic production over time.', 'FALSE — GDP includes final services produced within borders.', 'FALSE — Final banking and insurance services are included in GDP totals.'], '1/5', 35, 'full' ),
( '3.2', 'CASE 3.2.36', 'Retail sector trap', 'Evaluate traps when classifying retail activity:', ARRAY['A bookstore selling printed titles performs tertiary retail distribution.', 'Online order fulfilment by a warehouse is tertiary logistics.', 'Mixed manufacturing and retail in one firm can span secondary and tertiary activity.', 'Physical goods sold in shops do not automatically make retail secondary.', 'Printing the titles is secondary while selling them is tertiary.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Retail trade of goods is tertiary activity.', 'TRUE — Fulfilment services are tertiary activity.', 'TRUE — Mixed firms can span secondary production and tertiary retail.', 'TRUE — Distribution and retail are tertiary even for physical products.', 'TRUE — Manufacturing and retail occupy different sectors.'], '3/5', 36, 'full' ),
( '3.2', 'CASE 3.2.37', 'Software support sector trap', 'Assess sector traps around software support services:', ARRAY['Tina and Steve''s technical support is tertiary even when tied to refurbished goods.', 'Remote support abroad remains tertiary when produced domestically.', 'Software helpdesks troubleshooting networks provide tertiary services.', 'Writing code for clients is secondary manufacturing.', 'Support is secondary because computers are manufactured products.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Support services remain tertiary when linked to goods.', 'TRUE — Client location does not reclassify domestic tertiary services.', 'TRUE — Technical support is a tertiary service.', 'FALSE — Software services are tertiary in this context.', 'FALSE — Supporting devices is tertiary, not manufacturing.'], '5/5', 37, 'full' ),
( '3.2', 'CASE 3.2.38', 'Multi-sector firms', 'Analyze firms operating across more than one sector:', ARRAY['The three-sector model classifies activities rather than assigning one label per economy.', 'A farm selling produce can only be classified as primary.', 'AT&S manufacturing with client advice is tertiary only.', 'A farm that also runs a roadside shop can only report primary activity.', 'Once labelled primary, a firm cannot perform tertiary services in the same economy.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — The model classifies activities, not single labels per economy.', 'FALSE — Firms can operate across multiple sectors.', 'FALSE — Manufacturing can coexist with service offerings.', 'FALSE — The same firm can carry out primary farming and tertiary retail.', 'FALSE — Activities are classified by sector, not one label for all operations.'], '3/5', 38, 'full' ),
( '3.2', 'CASE 3.2.39', 'Output share shifts', 'Evaluate how sector output shares shift with development:', ARRAY['Emerging countries typically depend heavily on primary activity before tertiary dominance emerges.', 'Tertiary dominance in EU states coexists with some primary and secondary output.', 'Primary share often falls as countries become more developed.', 'Economic development advancing tends to raise relative tertiary output.', 'Secondary and tertiary shares must both fall as primary share falls.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Emerging economies typically depend heavily on primary activity first.', 'TRUE — Advanced economies still contain all sectors, with tertiary largest.', 'TRUE — Advanced economies rely less on primary output shares.', 'TRUE — More developed economies shift toward services.', 'FALSE — Development reallocates activity among sectors over time.'], '2/5', 39, 'full' ),
( '3.2', 'CASE 3.2.40', 'Standard of living link', 'Assess linking GDP per capita to living standards:', ARRAY['Living standards correlate with GDP though GDP misses some welfare dimensions.', 'Per capita averages miss distribution of income within a country.', 'GDP per capita fully captures inequality within a country.', 'Higher GDP per capita in EU members is unrelated to living standards.', 'Low GDP per capita alone defines an emerging economy''s entire sector mix.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Correlation exists despite GDP limits.', 'TRUE — Per capita averages miss distribution of income.', 'FALSE — Per capita averages miss distribution of income.', 'FALSE — GDP per capita is linked to living standards.', 'FALSE — Sector mix patterns are tendencies, not single indicators.'], '4/5', 40, 'full' ),
( '3.2', 'CASE 3.2.41', 'Printed circuit boards sector', 'Classify PCB fabrication in the sector model:', ARRAY['Client advice alongside fabrication does not remove secondary classification.', 'PCB advice to clients converts fabrication into tertiary services only.', 'Copper mining for laminate reclassifies PCB plants as primary extraction.', 'Testing substrates in clean rooms becomes tertiary inspection service only.', 'Natural copper in laminate inputs reclassifies PCB fabrication as primary mining.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Manufacturing remains secondary even if services accompany sales.', 'FALSE — Manufacturing remains secondary even if services accompany sales.', 'FALSE — Manufacturing components is secondary regardless of input origin.', 'FALSE — Quality steps in manufacturing stay secondary activity.', 'FALSE — Transforming materials into PCBs is secondary manufacturing.'], '2/5', 41, 'full' ),
( '3.2', 'CASE 3.2.42', 'Insurance sector type', 'Evaluate insurance within tertiary services:', ARRAY['Insurance cooperatives processing claims provide tertiary services.', 'Underwriting and claims payment are tertiary financial services.', 'Claims handling is tertiary whether the client is a farm or a factory.', 'Insurance is primary because policies cover basic risks.', 'Insurance tied to manufactured goods becomes secondary.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Insurance is a financial service in the tertiary sector.', 'TRUE — Core insurance operations are tertiary activity.', 'TRUE — Insurance services are tertiary for all customer types.', 'FALSE — Risk coverage is a financial service, not resource extraction.', 'FALSE — Insurance remains tertiary regardless of what policies cover.'], '5/5', 42, 'full' ),
( '3.2', 'CASE 3.2.43', 'Clothing production sector', 'Classify garment production and sales:', ARRAY['Fashion retail selling finished jackets is tertiary trade.', 'Designing jackets can be tertiary while sewing them is secondary.', 'Imported fabric entering a sewing floor supports secondary manufacturing.', 'Sewing garments is secondary even when fashion is sold as a consumer experience.', 'Sewing jackets from imported fabric is secondary manufacturing.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Retail distribution is tertiary activity.', 'TRUE — Design services can be tertiary; sewing is manufacturing.', 'TRUE — Manufacturing uses imported materials in secondary production.', 'TRUE — Sewing garments is secondary manufacturing.', 'TRUE — Garment production from materials is secondary activity.'], '4/5', 43, 'full' ),
( '3.2', 'CASE 3.2.44', 'Coaching as tertiary', 'Evaluate coaching within the tertiary sector:', ARRAY['Remote coaching sessions sold to clients are tertiary services.', 'Exporting coaching abroad keeps the activity tertiary.', 'Coaching combined with merchandise sales can still be tertiary service delivery.', 'Coaching studios renting space and paying trainers deliver tertiary services.', 'Designing training programmes is secondary manufacturing.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Coaching is a service classified in the tertiary sector.', 'TRUE — Client location does not reclassify domestic tertiary services.', 'TRUE — Core coaching remains tertiary even if goods are sold.', 'TRUE — Personal coaching is tertiary-sector activity.', 'FALSE — Design services are tertiary; book printing is secondary.'], '3/5', 44, 'full' ),
( '3.2', 'CASE 3.2.45', 'Distribution services', 'Assess distribution and logistics as tertiary activity:', ARRAY['Online order fulfilment from a warehouse is tertiary logistics.', 'Retail distribution of finished goods to shops is tertiary trade.', 'Warehousing is secondary because steel will be manufactured.', 'Bookstores are secondary because books are printed products.', 'Physical goods make distribution secondary manufacturing.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Fulfilment services are tertiary activity.', 'TRUE — Distribution to customers is tertiary-sector activity.', 'FALSE — Warehousing before manufacturing is tertiary logistics.', 'FALSE — Distribution to readers is tertiary activity.', 'FALSE — Distribution is tertiary even when goods are physical.'], '2/5', 45, 'full' ),
( '3.2', 'CASE 3.2.46', 'Raw material extraction', 'Analyze primary-sector extraction activities:', ARRAY['Forestry supplying logs to mills is primary extraction.', 'Olive farms harvesting crops perform primary agricultural activity.', 'Farming, fishing, mining, and forestry extract raw materials in the primary sector.', 'Coal mining extracting ore is primary-sector activity.', 'Fishing becomes secondary once fish are filleted onboard.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Forestry extracts timber as a natural resource.', 'TRUE — Crop production is primary-sector activity.', 'TRUE — Primary activity extracts raw materials from the earth.', 'TRUE — Mining extracts raw materials and is primary activity.', 'FALSE — Extracting fish remains primary-sector activity.'], '4/5', 46, 'full' ),
( '3.2', 'CASE 3.2.47', 'Transforming raw materials', 'Assess secondary-sector transformation:', ARRAY['Timber mills exporting boards perform secondary processing of logs.', 'PCB fabrication is tertiary because components support services.', 'Sewing is tertiary because fashion is a consumer service.', 'Smelting remains primary because ore comes from mines.', 'Shipbuilding is tertiary because ships later carry cargo.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Milling logs into boards is secondary manufacturing.', 'FALSE — Manufacturing components is secondary activity.', 'FALSE — Sewing garments is secondary manufacturing.', 'FALSE — Processing ore or metal is secondary transformation.', 'FALSE — Building ships from materials is secondary manufacturing.'], '2/5', 47, 'full' ),
( '3.2', 'CASE 3.2.48', 'EU tertiary dominance', 'Evaluate tertiary dominance in advanced EU economies:', ARRAY['As economies develop, relative tertiary output tends to increase.', 'Higher GDP per capita in EU members links to high living standards in the model.', 'Primary food production dominates output in rich EU states.', 'High tertiary shares typify emerging economies with low GDP per capita.', 'Developed EU states keep primary output above seventy percent.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — More developed economies shift toward services in the three-sector model.', 'TRUE — GDP per capita is used as a living-standard indicator.', 'FALSE — Developed EU economies show tertiary dominance, not primary dominance.', 'FALSE — High tertiary shares characterise advanced, not emerging, economies.', 'FALSE — In developed EU countries the tertiary sector usually exceeds seventy percent.'], '5/5', 48, 'full' ),
( '3.2', 'CASE 3.2.49', 'Sector trap software support', 'Evaluate sector traps around software support:', ARRAY['Refurbished-goods support from Tina and Steve remains tertiary service activity.', 'Remote support to foreign clients remains tertiary.', 'Network troubleshooting by software helpdesks counts as tertiary service activity.', 'Manufacturing devices and supporting them can span secondary and tertiary activity.', 'Writing client software is tertiary service activity.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Support services remain tertiary when linked to goods.', 'TRUE — Client location does not reclassify domestic tertiary services.', 'TRUE — Technical support is a tertiary service.', 'TRUE — Manufacturing is secondary; support is tertiary alongside it.', 'TRUE — Software services are tertiary in this context.'], '1/5', 49, 'full' ),
( '3.2', 'CASE 3.2.50', 'Chapter 3.2 synthesis', 'Assess integrated sector and GDP claims:', ARRAY['Emerging economies depend largely on primary activity while advanced EU states show tertiary dominance.', 'GDP measures final domestic production and supports growth comparisons when inflation-adjusted.', 'GDP critics cite missing income, quality limits, and disaster rebuild effects.', 'GDP correlates perfectly with health and happiness in every case.', 'Manufacturing PCBs and offering after-sales support collapse into a single tertiary label.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Development shifts sector shares toward services in rich economies.', 'TRUE — GDP totals final output; real growth uses adjusted figures.', 'TRUE — Standard criticisms include coverage, quality, and rebuild distortions.', 'FALSE — Correlation does not mean GDP fully measures welfare.', 'FALSE — Manufacturing stays secondary; support can be tertiary alongside it.'], '3/5', 50, 'full' ),
( '3.3', 'CASE 3.3.01', 'Profit-oriented basics', 'Evaluate claims about profit-oriented business aims:', ARRAY['Strong customer demand alone guarantees profit regardless of expenses.', 'Break-even performance is the primary long-run goal of most profit-oriented manufacturers.', 'Recording revenue without controlling costs satisfies the profit objective.', 'Profit means matching expenses exactly while ignoring any surplus.', 'Covering costs alone is the usual long-run goal of profit-oriented manufacturers.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Rising costs can erase profit despite revenue.', 'FALSE — Profit-oriented firms seek surplus above break-even.', 'FALSE — Profit requires revenues to exceed costs, not revenue alone.', 'FALSE — Profit requires revenues to exceed costs and expenses.', 'FALSE — Profit-oriented firms aim for revenue above costs to grow and reward risk.'], '2/5', 1, 'full' ),
( '3.3', 'CASE 3.3.02', 'Bakery oven reinvestment', 'A bakery chain targets revenue above costs to fund new ovens in a growing shop. Analyze:', ARRAY['Seeking revenue above costs to buy new ovens reflects profit-oriented reinvestment logic.', 'Retained surplus from profitable sales can finance equipment upgrades.', 'The shop treats higher revenue than expenses as the basis for buying new ovens.', 'Durability requires distributing all earnings immediately to owners.', 'Oven purchases must come from donations rather than business surplus.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Profit funds capital renewal in commercial firms.', 'TRUE — Profit enables reinvestment in commercial businesses.', 'TRUE — Profit orientation links surplus to reinvestment.', 'FALSE — Reinvestment also supports long-run business sustainability.', 'FALSE — Commercial firms reinvest profit into equipment.'], '2/5', 2, 'full' ),
( '3.3', 'CASE 3.3.03', 'Revenue versus costs', 'Analyze the revenue-versus-cost relationship in profit orientation:', ARRAY['Cost control matters because profit compares revenue with total expenses.', 'Commercial expansion often relies on profit rather than persistent losses.', 'Margin above break-even allows commercial firms to expand operations.', 'Profit emerges when revenue exceeds total costs in a period.', 'Profit orientation requires revenues to exceed costs and expenses.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Both revenue and costs determine profit outcomes.', 'TRUE — Commercial expansion relies on profit, not persistent losses.', 'TRUE — Surplus above costs supports growth in profit-oriented firms.', 'TRUE — Margin appears only when revenue exceeds costs.', 'TRUE — Profit means higher revenues than total costs.'], '4/5', 3, 'full' ),
( '3.3', 'CASE 3.3.04', 'Red Cross flood-relief kits', 'A Red Cross branch collects donations before dispatching flood-relief kits to affected towns. Evaluate:', ARRAY['Charging for some relief supplies converts Red Cross into a profit-maximiser.', 'Any surplus from donations can be reinvested into further relief work.', 'Not-for-profit status means the branch may ignore funding entirely.', 'Dispatching kits without prior inflows is typical NPO practice.', 'Relief organisations need no inflows because volunteers supply everything.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Cost recovery does not redefine a humanitarian NPO as profit-oriented.', 'TRUE — NPO surpluses are typically reinvested into the mission.', 'FALSE — NPOs must still secure and manage revenues or donations.', 'FALSE — Relief delivery requires funding for materials and logistics.', 'FALSE — Humanitarian delivery requires funded materials and logistics.'], '3/5', 4, 'full' ),
( '3.3', 'CASE 3.3.05', 'Profit reinvestment', 'Assess reinvestment of profit in commercial firms:', ARRAY['Profits can fund new equipment that improves future service capacity.', 'Retained profit can be reinvested to improve durability and sustainability of a business.', 'Reinvestment supports long-run survival alongside owner returns.', 'Repair shops reinvesting profit into diagnostic tools show commercial reinvestment.', 'Profit cannot fund equipment because it must be distributed immediately.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Reinvested profit supports capital renewal.', 'TRUE — Reinvested profit strengthens long-run business capacity.', 'TRUE — Reinvestment supports durability and future returns.', 'TRUE — Retained profit funds capital renewal in profit-oriented firms.', 'FALSE — Profits can be reinvested in the business.'], '5/5', 5, 'full' ),
( '3.3', 'CASE 3.3.06', 'WWF merchandise and habitat work', 'A WWF project sells branded merchandise and ploughs surplus into habitat protection. Analyze:', ARRAY['Selling merchandise can raise funds for habitat work within an NPO model.', 'Merchandise income helps cover operating costs while funding conservation work.', 'Habitat work funded from surplus proves WWF maximises owner wealth.', 'WWF seeks maximum private owner wealth like a listed corporation.', 'WWF must distribute merchandise surplus as private shareholder dividends.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Trading can fund mission activities within an NPO.', 'TRUE — Trading can supplement donations to cover mission costs.', 'FALSE — Merchandising surpluses can fund mission work.', 'FALSE — WWF is a mission-driven non-profit organisation.', 'FALSE — NPO surpluses support mission reinvestment, not owner payouts.'], '2/5', 6, 'full' ),
( '3.3', 'CASE 3.3.07', 'Owner and investor reward', 'Evaluate profit as reward for owners and investors:', ARRAY['Investors treat retained profit as reward for capital placed at risk.', 'Owner return logic treats profit as payoff for committing capital to uncertain ventures.', 'Profit orientation excludes any return to owners because customers pay prices.', 'Profits reward owners and investors for the risk they have taken.', 'Owners deserve no return when revenues exceed expenses.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Profit compensates owners and investors for risk taken.', 'TRUE — Profit compensates owners for capital risk.', 'TRUE — Owners and investors expect reward when revenues exceed costs.', 'TRUE — Returns compensate capital providers for bearing business risk.', 'FALSE — Owners and investors expect profit as reward for risk.'], '4/5', 7, 'full' ),
( '3.3', 'CASE 3.3.08', 'Startup founder risk', 'Startup founders expect profit as compensation for invested risk. Evaluate:', ARRAY['Investors bear no risk in startups because lenders absorb all uncertainty.', 'Startups are NPOs because early years may show low margins.', 'Covering costs fully removes any need to reward risk-bearing owners.', 'Profit has no connection to capital placed at risk.', 'Risk-bearing founders should expect no return when revenues exceed expenses.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Owners and investors bear risk rewarded by profit.', 'FALSE — Profit orientation depends on aims, not temporary margin levels.', 'FALSE — Founders seek surplus beyond break-even to reward risk.', 'FALSE — Profit compensates capital exposed to business risk.', 'FALSE — Founders and investors expect profit as reward for risk.'], '1/5', 8, 'full' ),
( '3.3', 'CASE 3.3.09', 'Not-for-profit aim', 'Analyze the main aim of not-for-profit organisations:', ARRAY['Mission delivery still requires enough inflows to finance operations.', 'Not-for-profit organisations mainly aim to cover costs while pursuing a mission.', 'NPOs seek to cover costs rather than maximise owner profit.', 'Greenpeace, WWF, and Red Cross illustrate recognised not-for-profit examples.', 'Charity clinics billing insurers enough to cover running costs fit not-for-profit aims.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Even NPOs require income streams to operate.', 'TRUE — NPOs focus on covering costs rather than maximising owner profit.', 'TRUE — Mission focus replaces profit-maximisation for owners.', 'TRUE — These appear as NPO examples in the chapter.', 'TRUE — NPO healthcare seeks to cover costs while serving patients.'], '5/5', 9, 'full' ),
( '3.3', 'CASE 3.3.10', 'Charity clinic cost coverage', 'A charity clinic bills insurers enough to cover running costs while treating patients. Analyze:', ARRAY['Surplus from billing can improve patient services rather than owner payouts.', 'Treating patients while covering costs shows mission delivery with financial discipline.', 'Billing insurers to cover running costs aligns with not-for-profit cost coverage.', 'Billing insurers converts the clinic into a listed corporation.', 'Community clinics prove NPOs never need to cover staff or supply costs.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — NPO surpluses reinvest in mission delivery.', 'TRUE — NPOs combine service delivery with cost coverage.', 'TRUE — NPOs seek to cover costs while delivering mission services.', 'FALSE — NPOs can bill for cost coverage without profit-maximising aims.', 'FALSE — NPO healthcare must cover operating costs.'], '3/5', 10, 'full' ),
( '3.3', 'CASE 3.3.11', 'Covering costs in NPOs', 'Evaluate cost coverage for not-for-profit organisations:', ARRAY['NPOs ignore revenue because mission work is voluntary in nature.', 'Food banks track whether donations cover warehouse rent for ongoing operation.', 'Not-for-profit status does not prevent earning surplus reinvested for the mission.', 'Mission delivery requires no financial inflows once an NPO is registered.', 'Donor income frees an NPO from covering operating costs responsibly.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — NPOs still need inflows to operate.', 'TRUE — NPOs must ensure operating costs are covered.', 'TRUE — NPOs may earn surplus reinvested into mission activities.', 'FALSE — NPOs need revenues or donations to operate.', 'FALSE — NPOs still need enough revenue to cover costs.'], '3/5', 11, 'full' ),
( '3.3', 'CASE 3.3.12', 'NGO theatre ticket surplus', 'An NGO theatre sells tickets nightly and reinvests any surplus in outreach programmes. Evaluate:', ARRAY['Ticket income covering nightly running costs lets performances continue.', 'Outreach funded from surplus shows mission reinvestment of NPO gains.', 'NPOs must cover operating costs from ticket income, donations, or grants.', 'Reinvesting ticket surplus in outreach uses NPO gains for mission expansion.', 'The theatre combines earned ticket income with mission reinvestment aims.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — NPOs need revenues to cover operating costs.', 'TRUE — Reinvested surplus can broaden mission reach.', 'TRUE — Cultural NPOs still need inflows that cover nightly running costs.', 'TRUE — NPO surpluses fund expanded mission activities.', 'TRUE — NPOs may combine fees and mission surplus use.'], '3/5', 12, 'full' ),
( '3.3', 'CASE 3.3.13', 'Donations as revenue', 'Assess donations as revenue for non-profit organisations:', ARRAY['Donor income supports campaigns when earned revenue is limited.', 'Mixed donations and fees cannot sustain an NPO because only one revenue source is allowed.', 'Prior surplus cannot fund later aid shipments for humanitarian organisations.', 'Humanitarian NGOs dispatch kits before any funding because urgency overrides finance.', 'Donor gifts remove any need for NPOs to cover operating costs responsibly.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Donations finance mission operations.', 'FALSE — NPOs may combine multiple inflow types.', 'FALSE — Surpluses and donations enable ongoing services.', 'FALSE — Even urgent relief requires funded materials and logistics.', 'FALSE — NPOs still need enough revenue to cover costs.'], '5/5', 13, 'full' ),
( '3.3', 'CASE 3.3.14', 'Investors and retained profit', 'Investors treat retained profit as reward for capital placed at risk. Analyze:', ARRAY['Retained profit can reward investors for capital exposed to business risk.', 'Investors expect profit as compensation for capital committed to the firm.', 'Capital providers expect returns when revenues exceed costs because they bear business risk.', 'Fixed wages to investors replace profit regardless of business performance.', 'Capital at risk deserves no return when revenues exceed expenses.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Profit compensates capital providers for risk taken.', 'TRUE — Investors receive profit as reward for risk taken.', 'TRUE — Risk-bearing investors receive profit when the firm succeeds.', 'TRUE — Profit rewards vary with business performance and risk.', 'FALSE — Owners and investors expect profit as reward for risk.'], '1/5', 14, 'full' ),
( '3.3', 'CASE 3.3.15', 'Surplus reinvestment mission', 'Evaluate reinvesting NPO surplus for mission delivery:', ARRAY['WWF habitat projects funded by merchandising surplus show mission reinvestment.', 'Surplus at Greenpeace can support more campaigns rather than shareholder dividends.', 'Mission reinvestment means surplus is paid to private shareholders as annual bonuses.', 'NPO surplus must be paid out as shareholder dividends like a corporation.', 'Service upgrades prove an NPO failed because it spent less than donors gave.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — NPO merchandising surpluses can fund mission work.', 'TRUE — NPO surplus supports mission, not owner payouts.', 'FALSE — Surplus is reinvested into mission activities.', 'FALSE — NPO surpluses are reinvested, not distributed as owner dividends.', 'FALSE — Improving services aligns with NPO aims.'], '4/5', 15, 'full' ),
( '3.3', 'CASE 3.3.16', 'Red Cross example', 'Assess the Red Cross as a not-for-profit example:', ARRAY['Red Cross kit dispatch requires prior inflows to fund materials and logistics.', 'Humanitarian relief funded by donations fits the not-for-profit model.', 'The Red Cross is cited as an example of a non-profit organisation.', 'Red Cross operates without covering staff or warehouse costs.', 'Prior-year donation surplus cannot fund current aid parcel packing.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Relief delivery requires funding to cover operations.', 'TRUE — Donations are a key revenue source for many NPOs.', 'TRUE — Red Cross operates as a well-known NPO example.', 'TRUE — NPOs must finance ongoing operating expenses.', 'FALSE — Prior surpluses and donations enable ongoing operations.'], '4/5', 16, 'full' ),
( '3.3', 'CASE 3.3.17', 'Food bank rent tracking', 'A food bank tracks whether donations cover warehouse rent for its depot. Evaluate:', ARRAY['Donations can cover rent while the food bank pursues its mission.', 'Food banks need not track costs because storage is goodwill.', 'Volunteer labour alone removes all premises cost requirements.', 'Rent coverage is irrelevant to not-for-profit organisations.', 'Warehouse rent must be funded by shareholder dividends.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Donor income helps NPOs finance operating expenses.', 'FALSE — NPOs must ensure operating costs are covered.', 'FALSE — Premises and logistics still require funding.', 'FALSE — Covering costs is central to NPO operation.', 'FALSE — NPO costs are covered by donations and mission revenues.'], '1/5', 17, 'full' ),
( '3.3', 'CASE 3.3.18', 'WWF example', 'Evaluate the World Wildlife Fund as a non-profit example:', ARRAY['Trading merchandise converts WWF into a commercial retailer maximising owner profit.', 'Wildlife programmes funded by prior fundraising surpluses show mission reinvestment.', 'WWF merchandising can fund habitat work without making WWF profit-oriented.', 'Environmental campaigns require no financing because advocacy is costless.', 'WWF behaves like a listed corporation maximising private owner wealth.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Merchandise can fund an NPO without profit-maximising aims.', 'TRUE — Prior surpluses and donations can fund later projects.', 'TRUE — Merchandise can fund mission activities within an NPO model.', 'FALSE — Campaigns require staff, logistics, and covered costs.', 'FALSE — WWF is a mission-driven non-profit organisation.'], '3/5', 18, 'full' ),
( '3.3', 'CASE 3.3.19', 'Greenpeace mission spending', 'Greenpeace raises international funds while limiting spending to mission delivery. Analyze:', ARRAY['Greenpeace limiting spending to mission delivery fits NPO behaviour.', 'Mission delivery requires budgeting even for advocacy organisations.', 'Campaign surplus can support more campaigns rather than shareholder dividends.', 'Greenpeace is an example of a non-profit organisation.', 'International fundraising still requires covering staff and logistics costs.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — NPOs raise funds to cover mission operations.', 'TRUE — NPOs must manage revenues to cover mission delivery.', 'TRUE — NPO surplus supports mission, not owner payouts.', 'TRUE — Greenpeace appears as a representative NPO in the chapter.', 'TRUE — Even advocacy NPOs must cover operating costs.'], '5/5', 19, 'full' ),
( '3.3', 'CASE 3.3.20', 'Risk and profit link', 'Analyze the link between business risk and profit:', ARRAY['Profit rewards owners and investors for risk they have taken.', 'Investors view profit as compensation for capital exposed to market risk.', 'Covering costs alone satisfies owner expectations for risk taken.', 'Founders bear no risk in startups because lenders absorb all uncertainty.', 'Customer payments mean owners should expect no return when revenues exceed costs.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Returns compensate capital providers for bearing business risk.', 'TRUE — Investors receive profit as reward for risk taken.', 'FALSE — Commercial firms target profit above costs to reward risk.', 'FALSE — Owners and investors bear risk rewarded by profit.', 'FALSE — Owners expect reward when revenues exceed costs.'], '2/5', 20, 'full' ),
( '3.3', 'CASE 3.3.21', 'Durability through reinvest', 'Evaluate profit reinvestment and business durability:', ARRAY['Immediate distribution of all profit is required for commercial durability.', 'Reinvested profit supports durability and sustainability of a business.', 'Long-run survival for most firms depends on achieving profitable operations over time.', 'Commercial operators reinvesting surplus improve long-run survival prospects.', 'Profit enhances sustainability when reinvested in equipment improving future capacity.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Reinvestment also supports durability.', 'TRUE — Reinvested profit strengthens the firm''s long-run capacity.', 'TRUE — Most businesses aim to make profit to thrive over time.', 'TRUE — Profit supports reinvestment and long-run survival.', 'TRUE — Reinvested profit strengthens durability.'], '5/5', 21, 'full' ),
( '3.3', 'CASE 3.3.22', 'NPO revenue need', 'Assess why not-for-profit organisations still need revenue:', ARRAY['Relief NGOs must secure inflows before dispatching kits to disaster zones.', 'Greenpeace campaigns depend on covering staff and logistics costs.', 'Mission status eliminates the need to track operating expenses.', 'Grants are symbolic recognition requiring no cost coverage.', 'Volunteer labour alone removes all NPO revenue requirements.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — NPOs need resources to deliver goods and services.', 'TRUE — Campaigns require financed staff and operations.', 'FALSE — NPOs must manage costs to remain viable.', 'FALSE — Grants must cover real project and staff costs.', 'FALSE — Operations still require funded inflows.'], '2/5', 22, 'full' ),
( '3.3', 'CASE 3.3.23', 'Profit motive contrast', 'Contrast profit orientation with not-for-profit aims:', ARRAY['NPOs may reinvest surplus into mission projects rather than owner payouts.', 'Commercial profit aims include rewarding owner risk and funding reinvestment.', 'Charging fees does not automatically make an organisation profit-oriented.', 'Profit-maximisation for owners is the primary NPO financial goal.', 'Both profit firms and NPOs ignore revenue because missions differ.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — NPO surpluses support mission reinvestment.', 'TRUE — Profit orientation includes surplus, reinvestment, and risk reward.', 'TRUE — Fee income can support NPO cost coverage without profit-maximisation.', 'FALSE — NPOs prioritise mission over owner profit-maximisation.', 'FALSE — Both need inflows to operate.'], '3/5', 23, 'full' ),
( '3.3', 'CASE 3.3.24', 'Surplus versus profit wording', 'Evaluate surplus in NPOs compared with profit in firms:', ARRAY['NPO surplus reinvested for mission resembles retained gain but not owner profit.', 'Owner dividends are typical for NPO surplus distribution.', 'Ticket surplus at an NGO theatre funds outreach instead of shareholder dividends.', 'Commercial profit and NPO surplus both involve inflows exceeding expenses when surplus arises.', 'Using surplus to improve services proves an NPO abandoned its mission.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — NPO surpluses fund mission activities rather than owner returns.', 'TRUE — NPO surpluses are reinvested, not owner dividends.', 'TRUE — NPO surplus supports mission reinvestment.', 'TRUE — Both involve revenues above costs when surplus arises.', 'FALSE — Improving services aligns with NPO aims.'], '4/5', 24, 'full' ),
( '3.3', 'CASE 3.3.25', 'Long-run survival', 'Assess long-run survival aims in businesses:', ARRAY['Commercial firms typically aim for long-run operation by earning profit rather than merely breaking even.', 'Commercial durability excludes any retention of earnings.', 'Break-even alone is sufficient for most profit-oriented firms seeking to thrive.', 'Operating for longevity motivates seeking profit rather than only break-even.', 'Both firm types can ignore finance after the first successful year.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Profit supports long-run survival and growth.', 'FALSE — Retained profit supports long-run capacity.', 'FALSE — Profit-oriented businesses target revenue above costs.', 'FALSE — Profit supports long-run survival and reinvestment.', 'FALSE — Ongoing inflows remain necessary.'], '1/5', 25, 'full' ),
( '3.3', 'CASE 3.3.26', 'Investor return logic', 'Analyze investor expectations about profit returns:', ARRAY['Investors in expanding firms view profit as compensation for capital exposed to market risk.', 'Retained profit must be unrelated to investor risk because it stays in the firm.', 'Commercial investors view break-even as the ideal long-run outcome.', 'Investors treat profit as a salary unrelated to capital committed to the firm.', 'Owner return logic rejects any link between profit and capital at risk.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Investors receive profit as reward for risk taken.', 'FALSE — Retained profit reflects returns on capital at risk.', 'FALSE — Investors typically expect profit above costs.', 'FALSE — Profit rewards capital providers for risk taken.', 'FALSE — Profit compensates owners for capital placed at risk.'], '3/5', 26, 'full' ),
