( '3.3', 'CASE 3.3.28', 'Cost coverage threshold', 'Assess covering costs as the NPO threshold:', ARRAY['Covering costs allows NPOs to reinvest any surplus into mission activities.', 'Cost coverage allows NPOs to operate without donations or fees.', 'NPOs and commercial firms share identical primary goals for owner profit.', 'Clinics need no revenue because treatment is a mission service.', 'Maximising owner profit is the primary financial goal of not-for-profit organisations.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Surplus can be reinvested to enhance mission delivery.', 'TRUE — Inflows are still required to meet costs.', 'FALSE — Commercial firms target owner profit; NPOs focus on mission cost coverage.', 'FALSE — NPO healthcare must cover operating costs.', 'FALSE — NPOs prioritise mission cost coverage over owner profit.'], '2/5', 28, 'full' ),
( '3.3', 'CASE 3.3.29', 'Social enterprise cafe margin', 'A social enterprise cafe seeks a margin to open a second training kitchen. Evaluate:', ARRAY['Achieving revenue above costs can finance additional mission capacity.', 'Seeking margin to fund a training kitchen targets surplus for mission-related expansion.', 'Mission-related expansion can be financed from earned margin above costs.', 'Seeking margin proves the cafe abandoned its social mission entirely.', 'The cafe treats surplus as fuel for a second training kitchen rather than owner dividends.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Margin above costs enables reinvestment.', 'TRUE — Surplus can fund expanded mission-related projects.', 'TRUE — Surplus above costs enables reinvestment.', 'TRUE — Margin can fund mission expansion within a social enterprise.', 'TRUE — Surplus can fund mission-related expansion.'], '3/5', 29, 'full' ),
