( '3.3', 'CASE 3.3.31', 'Repair shop diagnostic reinvest', 'Founders of a repair shop reinvest last year''s profit into diagnostic tools. Evaluate:', ARRAY['Founders treat retained profit as funding for long-run service capacity.', 'Diagnostic tool purchases from profit illustrate durability through reinvest.', 'Tool purchases must come from donations rather than business profit.', 'Reinvesting profit adopts not-for-profit dividend rules.', 'Repair shops must distribute all profit immediately to owners.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Retained profit strengthens durability.', 'TRUE — Reinvested profit strengthens long-run capacity.', 'FALSE — Commercial firms reinvest profit into equipment.', 'FALSE — Commercial reinvestment differs from NPO mission surplus use.', 'FALSE — Profits can be reinvested in the business.'], '5/5', 31, 'full' ),
( '3.3', 'CASE 3.3.32', 'Profit trap: revenue alone', 'Evaluate the trap that revenue alone equals profit:', ARRAY['Profit compares total revenue with total costs and expenses.', 'Profit-oriented firms compare inflows with total expenses rather than counting revenue alone.', 'Margin exists when total revenue exceeds total costs and expenses.', 'Strong sales do not guarantee profit when expenses rise faster than revenue.', 'Cost control remains essential to achieving profit.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Both sides of the account determine profit.', 'TRUE — Profit requires revenues above costs.', 'TRUE — Profit arises only when revenues surpass total costs.', 'TRUE — Rising costs can erase profit despite revenue.', 'TRUE — Both revenue and costs determine profit outcomes.'], '2/5', 32, 'full' ),
