( '3.3', 'CASE 3.3.46', 'Commercial durability logic', 'Evaluate commercial durability through profit:', ARRAY['Long-run survival for most firms depends on profitable operations.', 'Retained profit supports renewal of tools, premises, or systems over time.', 'Profit enables reinvestment that supports commercial durability.', 'Commercial firms thrive long term by merely matching costs with no margin.', 'Bakeries funding new ovens from surplus illustrate commercial durability logic.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Most businesses aim to make profit to thrive over time.', 'TRUE — Retained profit funds capital renewal.', 'TRUE — Reinvested profit strengthens long-run capacity.', 'TRUE — Profit-oriented firms target revenue above costs.', 'TRUE — Profit funds capital renewal in commercial firms.'], '4/5', 46, 'full' ),
