( '3.3', 'CASE 3.3.50', 'Chapter 3.3 synthesis', 'Assess integrated profit-oriented and NPO claims:', ARRAY['Profit-oriented firms aim for revenue above costs, reinvest profit, and reward owner risk.', 'NPOs aim to cover costs, accept donations, and reinvest surplus for mission delivery.', 'These organisations are profit-oriented because they raise revenues.', 'Both require paying surplus to private shareholders.', 'Revenue alone satisfies profit aims without regard to expenses.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Commercial aims include surplus, reinvestment, and risk reward.', 'TRUE — NPOs combine cost coverage, donations, and mission reinvestment.', 'FALSE — These appear as NPO examples in the chapter.', 'FALSE — NPO surpluses reinvest in mission; commercial profit may reward owners.', 'FALSE — Profit requires revenues to exceed costs.'], '5/5', 50, 'full' ),
( '3.4', 'CASE 3.4.01', 'EU micro staff ceiling', 'A workshop employs nine people with €1.8m turnover; assess EU SME classification claims:', ARRAY['Because staff are below ten, a firm remains a micro enterprise despite turnover above €2m.', 'Forty-five staff alone guarantees small classification even if turnover exceeds €10m.', 'Meeting the staff ceiling alone is sufficient for micro status regardless of turnover or balance sheet totals.', 'Under the EU definition, a micro enterprise may employ fewer than ten people.', 'A firm qualifies as micro because its balance sheet is below €2m, regardless of turnover above €2m.'], ARRAY[false, false, false, true, false], ARRAY['FALSE — Both staff and financial thresholds must be met; high turnover can exclude micro status.', 'FALSE — Both staff and turnover thresholds must be satisfied for small status.', 'FALSE — Micro status requires both the staff ceiling and a turnover or balance sheet cap.', 'TRUE — EU micro classification requires fewer than ten employees.', 'FALSE — Turnover above €2m can disqualify micro status despite a qualifying balance sheet.'], '4/5', 1, 'full' ),
( '3.4', 'CASE 3.4.02', 'Micro turnover edge case', 'Tina and Steve''s bakery has six staff and €2.1m turnover; evaluate size category statements:', ARRAY['Turnover above €10m can push a firm out of the small category even when staff remain below fifty.', 'Micro status allows either turnover up to €2m or a balance sheet total up to €2m alongside the staff limit.', 'Exceeding the €2m turnover cap can disqualify a firm from micro status even when staff are below ten.', 'Small status also requires turnover not exceeding €10m.', 'A small enterprise may employ fewer than fifty people under EU definitions.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — The €10m turnover cap is binding alongside the staff threshold.', 'TRUE — Micro firms must meet the staff cap and either the turnover or balance sheet financial ceiling.', 'TRUE — Turnover above €2m breaks the micro financial cap even with a small workforce.', 'TRUE — Small classification additionally requires turnover at or below €10m.', 'TRUE — The EU small category sets an upper staff limit below fifty employees.'], '5/5', 2, 'full' ),
( '3.4', 'CASE 3.4.03', 'Micro balance sheet OR test', 'A design studio reports eight staff, €2.4m turnover, and a €1.7m balance sheet; assess micro status:', ARRAY['A firm fails the medium test because both financial figures must be below their respective caps.', 'Medium enterprises employ fewer than two hundred and fifty people under EU definitions.', 'Because turnover is within €50m, balance sheet size is irrelevant for medium classification.', 'Two hundred and forty employees exceed the medium staff ceiling.', 'Thirty-eight staff alone keeps a firm in the small category despite turnover above €10m.'], ARRAY[false, true, false, false, false], ARRAY['FALSE — Only one financial threshold needs to be met alongside staff; both need not pass.', 'TRUE — EU medium enterprises must employ fewer than 250 people.', 'FALSE — Exceeding the balance sheet cap disqualifies medium status even if turnover qualifies.', 'FALSE — 240 is below 250 and therefore within the medium staff limit.', 'FALSE — Small status requires both staff and turnover limits; breaching turnover removes small classification.'], '5/5', 3, 'full' ),
( '3.4', 'CASE 3.4.04', 'Small dual thresholds', 'Evaluate EU small-enterprise criteria for a firm with forty-five staff and €9.5m turnover:', ARRAY['MSME excludes micro firms and covers only small and medium categories.', 'SMEs represent a narrow minority of EU firms because large corporations dominate registration statistics.', 'SME labels are purely descriptive and have no effect on access to finance or reporting rules.', 'AT&S counts as a medium enterprise because it operates internationally.', 'Medium status permits turnover up to €50m or a balance sheet total up to €43m together with the staff cap.'], ARRAY[false, false, false, false, true], ARRAY['FALSE — Micro firms are explicitly included in MSME/SME groupings.', 'FALSE — SMEs form the vast majority, not a minority, of EU businesses.', 'FALSE — Definitions actively shape finance access and regulatory treatment.', 'FALSE — Medium status depends on thresholds, not on geographic scope alone.', 'TRUE — Medium classification uses staff plus either turnover or balance sheet financial ceilings.'], '3/5', 4, 'full' ),
( '3.4', 'CASE 3.4.05', 'Small turnover breach', 'A wholesaler has thirty-eight staff but €10.4m turnover; assess SME classification claims:', ARRAY['A workforce of about ten thousand places AT&S outside EU medium enterprise limits.', 'Approximately ninety-nine percent of businesses in the EU are SMEs.', 'Accounting requirements are identical for micro firms and large multinationals under EU practice.', 'Two hundred employees fall within the medium staff threshold.', 'Seven staff and a €1.9m balance sheet guarantee micro status despite turnover above €2m.'], ARRAY[true, true, false, true, false], ARRAY['TRUE — Ten thousand staff far exceeds the 250-employee medium ceiling.', 'TRUE — Fuhrmann Ch3 cites that about 99% of EU businesses are SMEs.', 'FALSE — Size affects accounting rules, implying differences by category.', 'TRUE — 200 is below the 250-person medium limit.', 'FALSE — Exceeding the turnover cap disqualifies micro status even with qualifying staff and balance sheet.'], '4/5', 5, 'full' ),
( '3.4', 'CASE 3.4.06', 'Medium staff limit', 'Assess medium-enterprise criteria for a manufacturer with two hundred and forty employees:', ARRAY['Official SME classification can determine eligibility for EU support programmes and finance schemes.', 'Size definitions matter because accounting rules may differ for smaller and larger firms.', 'Ten employees still count as micro because the threshold says fewer than ten.', 'Two hundred and fifty employees satisfies the medium requirement of fewer than two hundred and fifty.', 'Fifty employees meets the small enterprise staff requirement of fewer than fifty.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — EU support and finance often hinge on meeting SME criteria.', 'TRUE — Fuhrmann Ch3 notes that size affects applicable accounting rules.', 'FALSE — Ten employees is not fewer than ten, so the staff test fails.', 'FALSE — 250 is not fewer than 250; the staff test fails.', 'FALSE — Small requires fewer than fifty staff; fifty is not eligible.'], '4/5', 6, 'full' ),
( '3.4', 'CASE 3.4.07', 'Medium financial OR logic', 'A firm has one hundred eighty staff, €48m turnover, and a €44m balance sheet; evaluate medium status:', ARRAY['Any firm with more than ten employees is classified as large under EU rules.', 'MSME commonly groups micro, small, and medium enterprises under one umbrella term.', 'Crossing size thresholds can change which accounting rules apply to a business.', 'Any local shop qualifies as micro without reference to staff or turnover data.', 'Exactly ten staff exceeds the micro employee ceiling of fewer than ten.'], ARRAY[false, true, true, false, true], ARRAY['FALSE — Small and medium tiers cover firms well above ten employees.', 'TRUE — MSME refers to micro, small, and medium enterprises collectively.', 'TRUE — Growing beyond thresholds can shift reporting requirements.', 'FALSE — Official staff and financial tests determine micro status.', 'TRUE — The micro limit is strictly below ten employees; ten does not qualify.'], '5/5', 7, 'full' ),
( '3.4', 'CASE 3.4.08', 'Medium turnover within cap', 'An engineering firm has two hundred staff, €49m turnover, and a €42m balance sheet; assess medium claims:', ARRAY['Exceeding medium staff or financial thresholds generally moves a firm out of SME status.', 'Grant schemes often require proof that the applicant meets official micro enterprise criteria.', 'Exactly fifty staff exceeds the small category employee limit.', 'Micro firms must meet the staff cap and either the turnover or balance sheet financial limit.', 'Exactly 250 staff exceeds the medium employee ceiling.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Surpassing medium criteria places a firm in the large category.', 'TRUE — Support programmes use the standard EU micro thresholds for eligibility.', 'TRUE — The small staff cap is strictly below fifty employees.', 'TRUE — EU micro rules pair staff with one of two financial caps.', 'TRUE — The medium cap excludes firms with 250 or more employees.'], '3/5', 8, 'full' ),
( '3.4', 'CASE 3.4.09', 'AT&S large scale', 'AT&S employs roughly ten thousand staff worldwide; evaluate EU size classification statements:', ARRAY['A balance sheet above €43m can disqualify medium status even with low turnover.', 'Crossing micro limits while staying within small thresholds reclassifies the firm as small.', 'Policies supporting SMEs affect the vast majority of EU businesses by number.', 'Size differences can mean different accounting rule sets for a micro supplier and AT&S.', 'Small enterprises must record turnover not exceeding €10m.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — The €43m balance sheet limit is binding for medium classification.', 'TRUE — Qualifying within small limits replaces micro status.', 'TRUE — With ~99% SME share, SME-focused policy reaches most businesses.', 'TRUE — Fuhrmann Ch3 links size to differing accounting rules.', 'TRUE — €10m is the small turnover ceiling in the EU table.'], '2/5', 9, 'full' ),
( '3.4', 'CASE 3.4.10', 'SME share in the EU', 'Assess statements about the prevalence of SMEs in the European Union:', ARRAY['Medium enterprises may report turnover up to €50m under EU definitions.', 'Micro classification requires both turnover and balance sheet to stay below €2m simultaneously.', 'Micro requires fewer than ten staff plus financial caps, stricter than small staff limits.', 'Small firms may report turnover up to €50m provided staff are below fifty.', 'Medium status is confirmed because staff and turnover both qualify despite balance sheet breach.'], ARRAY[true, false, true, false, false], ARRAY['TRUE — €50m is the medium turnover ceiling in the EU table.', 'FALSE — Only one financial measure must qualify, not both at once.', 'TRUE — Micro staff cap is below ten, much tighter than small''s below fifty.', 'FALSE — €50m is the medium turnover cap, not the small cap.', 'FALSE — Exceeding the balance sheet cap blocks medium status despite qualifying staff and turnover.'], '2/5', 10, 'full' ),
( '3.4', 'CASE 3.4.11', 'Why definitions matter', 'A startup seeks EU-backed finance tied to official size categories; evaluate why definitions matter:', ARRAY['Two people employed falls well within the micro staff ceiling.', 'Because SMEs are numerous, individual SME failures have no community impact.', 'Lenders may verify SME status using official headcount and turnover thresholds.', 'SME tiers require joint satisfaction of staff and relevant financial thresholds.', 'Most EU businesses by count are classified within SME size bands.'], ARRAY[true, false, true, true, true], ARRAY['TRUE — Two employees is below the ten-person micro limit.', 'FALSE — SME failures can still affect employees, suppliers, and local communities.', 'TRUE — Finance programmes rely on standard SME criteria.', 'TRUE — EU definitions combine staff with financial caps for each tier.', 'TRUE — ~99% of EU businesses are SMEs by count.'], '3/5', 11, 'full' ),
( '3.4', 'CASE 3.4.12', 'MSME terminology', 'Evaluate terminology linking micro, small, and medium enterprises in EU policy:', ARRAY['Turnover above €50m disqualifies medium status even if balance sheet qualifies.', 'Medium turnover cap is €10m, identical to the small limit.', 'Any firm with forty staff is micro because it employs fewer than fifty people.', 'Adding staff and sales can leave a firm classified as micro even after crossing small thresholds.', 'All EU firms file identical full public accounts regardless of size category.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — €52m turnover exceeds the €50m medium ceiling.', 'FALSE — €10m is the small cap; medium allows up to €50m.', 'FALSE — Forty staff exceeds micro limits and aligns with small staff range instead.', 'FALSE — Exceeding micro thresholds moves classification upward if small criteria are met.', 'FALSE — SME and large firms face different reporting expectations.'], '2/5', 12, 'full' ),
( '3.4', 'CASE 3.4.13', 'Accounting rules by size', 'A growing firm approaches medium thresholds; assess accounting implications of size classification:', ARRAY['Tina and Steve illustrate micro-scale operations compared with AT&S''s large workforce.', 'Complete staff and financial data are needed to verify micro or other SME tiers.', 'SME definitions are irrelevant once a firm exports outside the home country.', 'One hundred and eighty employees fits the medium staff band if financial tests also pass.', 'Micro pairs sub-ten staff with €2m turnover or balance sheet limits.'], ARRAY[true, true, false, true, true], ARRAY['TRUE — Fuhrmann Ch3 contrasts local micro examples with AT&S''s scale.', 'TRUE — Both staff and financial caps must be checked.', 'FALSE — Export activity does not override SME threshold tests.', 'TRUE — 180 is within medium''s below-250 staff range.', 'TRUE — This matches the EU micro row in Fuhrmann Ch3.'], '3/5', 13, 'full' ),
( '3.4', 'CASE 3.4.14', 'Micro balance within cap', 'A consultancy has seven staff, €2.3m turnover, and a €1.9m balance sheet; assess micro eligibility:', ARRAY['Operating alone prevents micro classification because micro requires at least five staff.', 'Large firms like AT&S can employ thousands despite being few in number.', 'Three thousand staff can still fall within medium limits if turnover is managed.', 'Turnover within €10m alone makes a firm small even with three hundred employees.', 'Turnover above €50m prevents medium classification when that cap is breached.'], ARRAY[false, true, false, false, true], ARRAY['FALSE — There is no minimum staff count for micro beyond the upper cap.', 'TRUE — AT&S illustrates large-scale employment in a rare large firm.', 'FALSE — 3,000 far exceeds the 250-employee medium cap.', 'FALSE — Three hundred staff exceeds medium limits regardless of turnover.', 'TRUE — €55m exceeds the €50m medium turnover limit.'], '5/5', 14, 'full' ),
( '3.4', 'CASE 3.4.15', 'Ten employees boundary', 'A family firm employs exactly ten people with €1.5m turnover; evaluate micro classification claims:', ARRAY['Micro enterprises form a large part of the SME group that dominates EU business counts.', '€43m is the medium balance sheet ceiling paired with sub-250 staff.', 'Nine staff and a €1.6m balance sheet confirm micro status despite €2.05m turnover.', 'Eight staff is compatible with micro but financial figures must still be verified.', 'The ninety-nine percent statistic proves SMEs generate ninety-nine percent of EU GDP.'], ARRAY[true, true, false, true, false], ARRAY['TRUE — Micro firms are part of the ~99% SME majority.', 'TRUE — €43m balance sheet is the medium cap in the EU table.', 'FALSE — Turnover above €2m disqualifies micro status even with qualifying balance sheet.', 'TRUE — Eight staff fits micro range pending financial tests.', 'FALSE — The figure refers to business numbers, not GDP share.'], '5/5', 15, 'full' ),
( '3.4', 'CASE 3.4.16', 'Fifty staff boundary', 'A logistics company employs exactly fifty people with €8m turnover; assess small enterprise claims:', ARRAY['Leaving SME status can end eligibility for certain EU SME finance programmes.', 'Medium status holds because balance sheet is within €43m despite turnover above €50m.', 'Medium pairs sub-250 staff with a €10m turnover cap.', 'Thirty staff is within the small enterprise employee limit.', 'One hundred and eighty staff keeps a firm in the small category because turnover is below €50m.'], ARRAY[true, false, false, true, false], ARRAY['TRUE — SME-tied support typically excludes large firms.', 'FALSE — Exceeding turnover cap blocks medium status despite balance sheet within limits.', 'FALSE — €10m is the small turnover cap, not medium.', 'TRUE — 30 is below the fifty-employee small cap.', 'FALSE — 180 staff exceeds small''s below-fifty limit.'], '5/5', 16, 'full' ),
( '3.4', 'CASE 3.4.17', 'Two hundred fifty staff cap', 'A textile plant employs exactly two hundred fifty workers with €40m turnover; evaluate medium claims:', ARRAY['EU SME tiers combine employee ceilings with turnover and/or balance sheet caps.', 'Nine staff alone proves micro status without financial documentation.', 'AT&S counts as a micro enterprise because it supplies components to phone makers.', 'One hundred and twenty-five staff satisfies the medium employee threshold.', 'Staff headcount must be verified alongside turnover for medium classification.'], ARRAY[true, false, false, true, true], ARRAY['TRUE — Combined criteria define each tier in the EU table.', 'FALSE — Financial thresholds are mandatory for micro confirmation.', 'FALSE — Supplier role does not determine size; headcount and financials do.', 'TRUE — 125 is below 250 staff limit.', 'TRUE — Staff verification is mandatory alongside turnover.'], '5/5', 17, 'full' ),
( '3.4', 'CASE 3.4.18', 'Large versus SME cut-off', 'Assess when a firm is treated as large rather than SME under EU thresholds:', ARRAY['Four employees fall within the micro staff ceiling.', '€2m turnover cap applies to small enterprises rather than micro.', '€55m turnover confirms medium status because balance sheet is below €43m.', 'Because SMEs are ninety-nine percent of firms, large firms employ fewer than one percent of workers.', 'A firm can progress from micro to small to medium as metrics cross successive thresholds.'], ARRAY[true, false, false, false, true], ARRAY['TRUE — Four staff is below ten-employee micro limit.', 'FALSE — €2m turnover cap applies to micro, not small.', 'FALSE — Turnover breach blocks medium status despite balance sheet within cap.', 'FALSE — Few large firms can still account for substantial employment shares.', 'TRUE — Growth can move a firm through SME tiers sequentially.'], '3/5', 18, 'full' ),
( '3.4', 'CASE 3.4.19', 'EU micro grant logic', 'Tina and Steve consider an EU micro-enterprise grant; assess eligibility logic:', ARRAY['Forty-five staff and €9.5m turnover together meet EU small enterprise thresholds.', 'Thirty-eight staff fits the small employee ceiling below fifty.', '€1.8m turnover stays within the micro turnover cap of €2m.', 'Six employees fit the micro staff ceiling even when turnover exceeds €2m.', 'Nine employees satisfy the micro staff ceiling of fewer than ten people.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Both staff below fifty and turnover below €10m satisfy small criteria.', 'TRUE — Thirty-eight is within the small staff limit.', 'TRUE — €1.8m meets the micro turnover threshold.', 'TRUE — Six staff meets the micro headcount test though turnover may fail.', 'TRUE — Nine is below the ten-person micro limit.'], '4/5', 19, 'full' ),
( '3.4', 'CASE 3.4.20', 'Micro OR financial logic', 'Evaluate how EU micro financial tests combine turnover and balance sheet figures:', ARRAY['Micro firms are excluded from SME statistics because they are too small to register.', 'Eight staff proves a firm is micro without checking turnover or balance sheet.', 'Two hundred and forty employees fits the medium staff ceiling below two hundred and fifty.', '€48m turnover is within the €50m medium turnover cap.', 'Large classification removes all legal duties to publish any financial information.'], ARRAY[false, false, true, true, false], ARRAY['FALSE — Micro firms are included in SME counts and definitions.', 'FALSE — Financial caps must also be satisfied for micro status.', 'TRUE — 240 is below the 250-person medium limit.', 'TRUE — €48m meets the medium turnover threshold.', 'FALSE — Large firms face reporting duties rather than exemption.'], '4/5', 20, 'full' ),
( '3.4', 'CASE 3.4.21', 'Small €10m cap recall', 'Assess EU small-enterprise financial limits alongside staff criteria:', ARRAY['€180k turnover is well below the €2m micro turnover cap.', 'A retailer is micro because turnover is under €10m despite thirty staff.', 'Four staff with €600k turnover can qualify as micro when financial caps are met.', 'Two hundred staff with €49m turnover and a €42m balance sheet can satisfy medium thresholds.', 'One hundred and twenty-five staff with €25m turnover and €30m balance sheet can satisfy medium thresholds.'], ARRAY[true, false, true, true, true], ARRAY['TRUE — €180k meets the micro turnover threshold.', 'FALSE — Staff above ten and turnover above €2m exclude micro; small may apply.', 'TRUE — Low headcount and turnover can satisfy micro criteria.', 'TRUE — All three metrics can meet medium caps together.', 'TRUE — Staff and both financial figures can meet medium caps.'], '2/5', 21, 'full' ),
( '3.4', 'CASE 3.4.22', 'Medium balance sheet breach', 'A company has one hundred staff, €30m turnover, and a €43.5m balance sheet; assess medium status:', ARRAY['Thirty staff with €9.9m turnover satisfies EU small enterprise thresholds.', 'A firm is small because turnover is only €25m despite one hundred twenty-five staff.', 'One hundred staff with €30m turnover fits the medium staff and turnover bands.', '€2m is the micro turnover ceiling in the EU SME table.', 'Nine staff fits the micro employee ceiling pending turnover verification.'], ARRAY[true, false, true, true, true], ARRAY['TRUE — Both metrics meet small staff and turnover caps.', 'FALSE — 125 staff exceeds small staff limit despite moderate turnover.', 'TRUE — 100 staff and €30m turnover can meet medium thresholds pending balance sheet.', 'TRUE — €2m turnover cap applies to micro enterprises.', 'TRUE — Nine is below the ten-person micro limit.'], '5/5', 22, 'full' ),
( '3.4', 'CASE 3.4.23', 'SME policy prevalence', 'Policy makers note SMEs make up about ninety-nine percent of EU businesses; assess implications:', ARRAY['Micro, small, and medium are identical categories with the same staff ceilings.', '€43m is the medium balance sheet ceiling in the EU SME table.', '€10m is the small turnover ceiling in the EU SME table.', '€2m is the micro balance sheet ceiling in the EU SME table.', '€50m is the medium turnover ceiling in the EU SME table.'], ARRAY[false, true, true, true, true], ARRAY['FALSE — Each tier has distinct staff and financial thresholds.', 'TRUE — €43m balance sheet cap applies to medium enterprises.', 'TRUE — €10m turnover cap applies to small enterprises.', 'TRUE — €2m balance sheet cap applies to micro enterprises.', 'TRUE — €50m turnover cap applies to medium enterprises.'], '2/5', 23, 'full' ),
( '3.4', 'CASE 3.4.24', 'Growth micro to small', 'Tina and Steve plan to hire staff and expand turnover; assess how classification may change:', ARRAY['Village location prevents micro classification regardless of size metrics.', '€40m turnover alone is sufficient proof of medium enterprise status.', 'SME status depends on official headcount and financial thresholds, not on industry sector.', 'Medium status applies when staff are below two hundred fifty and turnover or balance sheet meets medium financial limits.', 'Micro status applies when staff are below ten and turnover or balance sheet meets micro financial limits.'], ARRAY[false, false, true, true, true], ARRAY['FALSE — Location does not override EU size thresholds.', 'FALSE — Medium requires sub-250 staff plus financial tests.', 'TRUE — Sector does not override EU size threshold tests.', 'TRUE — Only one financial measure must qualify for medium status.', 'TRUE — Only one financial measure must qualify for micro status.'], '3/5', 24, 'full' ),
( '3.4', 'CASE 3.4.25', 'AT&S accounting contrast', 'Compare reporting expectations for AT&S and a micro village supplier:', ARRAY['Crossing medium staff and turnover thresholds moves a growing firm out of the small tier.', 'Three thousand staff far exceeds the two hundred and fifty employee medium ceiling.', 'A firm meeting small staff and financial limits is reclassified from micro to small.', 'Export activity does not override EU SME threshold tests for classification.', '€200m turnover far exceeds the €50m medium turnover ceiling.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Growth into medium limits replaces small classification when thresholds are met.', 'TRUE — 3,000 staff places a firm outside medium limits.', 'TRUE — Progression to small replaces micro when small limits are satisfied.', 'TRUE — Cross-border sales do not replace official size criteria.', 'TRUE — €200m turnover places a firm outside medium limits.'], '3/5', 25, 'full' ),
( '3.4', 'CASE 3.4.26', 'Medium €50m turnover cap', 'Assess the EU medium enterprise turnover limit alongside other criteria:', ARRAY['€10.4m turnover exceeds the €10m small turnover cap.', '€55m turnover exceeds the €50m medium turnover cap.', 'Fifty staff alone qualifies a firm for medium status without turnover data.', 'Firms skip the small tier whenever they hire a tenth employee.', '€2.1m turnover exceeds the €2m micro turnover cap.'], ARRAY[true, true, false, false, true], ARRAY['TRUE — €10.4m breaks the small turnover threshold.', 'TRUE — €55m breaks the medium turnover threshold.', 'FALSE — Medium status requires joint staff and financial tests, not headcount alone.', 'FALSE — Ten employees fail micro but small requires further staff and turnover tests.', 'TRUE — €2.1m breaks the micro turnover threshold.'], '2/5', 26, 'full' ),
( '3.4', 'CASE 3.4.27', 'Micro versus small confusion', 'An examiner checks claims mixing micro and small staff ceilings; evaluate:', ARRAY['€2.4m turnover exceeds the €2m micro turnover cap.', 'Turnover above the €2m micro limit removes micro status even when staff are below ten.', 'Exactly ten staff satisfies the micro requirement of fewer than ten employees.', 'Exactly two hundred fifty staff satisfies the medium requirement of fewer than two hundred and fifty.', 'Exactly fifty staff satisfies the small enterprise requirement of fewer than fifty.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — €2.4m breaks the micro turnover threshold.', 'TRUE — Turnover above the €2m micro limit ends micro status even with low headcount.', 'FALSE — Ten is not fewer than ten; the micro staff test fails.', 'FALSE — 250 is not fewer than 250; the medium staff test fails.', 'FALSE — Fifty is not fewer than fifty; the small staff test fails.'], '4/5', 27, 'full' ),
( '3.4', 'CASE 3.4.28', 'SME finance verification', 'A medium-sized exporter seeks a bank loan with EU guarantee backing; assess verification logic:', ARRAY['€2.05m turnover exceeds the €2m micro turnover cap.', 'A €43.5m balance sheet exceeds the €43m medium balance sheet cap.', '€2.2m turnover still meets the micro turnover cap of €2m.', 'Exactly ten staff meets the micro requirement of fewer than ten employees.', 'Turnover above €50m breaches the medium turnover threshold.'], ARRAY[true, true, false, false, true], ARRAY['TRUE — €2.05m breaks the micro turnover threshold.', 'TRUE — €43.5m breaks the medium balance sheet threshold.', 'FALSE — €2.2m exceeds the €2m micro turnover threshold.', 'FALSE — Ten is not fewer than ten; the micro staff test fails.', 'TRUE — Turnover above €50m breaks the medium turnover threshold.'], '3/5', 28, 'full' ),
