( '3.4', 'CASE 3.4.30', 'Combined criteria requirement', 'Assess whether meeting one SME criterion alone guarantees overall SME status:', ARRAY['Eight staff fits the micro employee ceiling below ten.', 'A €44m balance sheet still meets the medium balance sheet cap of €43m.', 'Balance sheet above €43m always qualifies a firm for medium status regardless of staff.', 'Meeting the micro staff test alone guarantees micro status without financial verification.', 'Fifteen staff exceeds the micro employee ceiling of fewer than ten.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Eight is below the ten-person micro limit.', 'FALSE — €44m exceeds the €43m medium balance sheet threshold.', 'FALSE — Medium status requires joint staff and financial tests.', 'FALSE — Micro status also requires turnover or balance sheet verification.', 'FALSE — Fifteen exceeds the ten-person micro limit.'], '4/5', 30, 'full' ),
