( '3.4', 'CASE 3.4.33', 'SME count statistic meaning', 'Evaluate what the ninety-nine percent SME figure implies about EU business structure:', ARRAY['Turnover of €9.5m exceeds the small turnover cap of €10m.', 'SME failures can still affect employees, suppliers, and local communities.', 'Few large firms can still account for substantial employment despite being rare by count.', 'Micro firms are included in SME counts and MSME groupings.', 'Because SMEs are numerous by count, SME-focused policy reaches most EU businesses.'], ARRAY[false, true, true, true, true], ARRAY['FALSE — €9.5m is within the €10m small turnover ceiling.', 'TRUE — SME insolvency has stakeholder effects beyond firm count statistics.', 'TRUE — Large employers can be few in number yet significant in jobs.', 'TRUE — Micro enterprises form part of the SME category.', 'TRUE — High SME share by number shapes EU business policy.'], '2/5', 33, 'full' ),
( '3.4', 'CASE 3.4.34', 'Medium turnover breach path', 'A firm has one hundred twenty staff, €52m turnover, and a €40m balance sheet; assess medium status:', ARRAY['Turnover of €9.9m exceeds the small turnover cap of €10m.', 'A firm with nine staff still needs turnover or balance sheet data to confirm micro status.', 'EU support programmes use standard SME thresholds to verify applicant eligibility.', 'Headcount below ten alone cannot confirm micro status without turnover or balance sheet figures.', 'Large firms face reporting duties rather than exemption from financial disclosure.'], ARRAY[false, true, true, true, true], ARRAY['FALSE — €9.9m is within the €10m small turnover ceiling.', 'TRUE — Financial caps must be verified alongside headcount.', 'TRUE — Finance schemes rely on official size criteria.', 'TRUE — Micro classification requires financial data alongside headcount.', 'TRUE — Large classification brings reporting obligations.'], '5/5', 34, 'full' ),
( '3.4', 'CASE 3.4.35', 'Small to medium transition', 'A family manufacturer grows to one hundred eighty staff and €45m turnover; assess classification:', ARRAY['Small status requires fewer than fifty staff plus turnover at or below €10m.', 'Turnover of €49m exceeds the medium turnover cap of €50m.', 'Medium status requires fewer than two hundred and fifty staff plus a qualifying financial test.', 'Micro status requires fewer than ten staff plus turnover at or below €2m or balance sheet at or below €2m.', 'Turnover of €1.8m exceeds the micro turnover cap of €2m.'], ARRAY[true, false, true, true, false], ARRAY['TRUE — Small combines staff ceiling with the €10m turnover cap.', 'FALSE — €49m is within the €50m medium turnover ceiling.', 'TRUE — Medium combines staff ceiling with turnover or balance sheet caps.', 'TRUE — Micro combines staff ceiling with one financial cap.', 'FALSE — €1.8m is within the €2m micro turnover ceiling.'], '4/5', 35, 'full' ),
( '3.4', 'CASE 3.4.36', 'EU table tier pairing', 'Match each enterprise tier with its paired EU threshold logic:', ARRAY['AT&S is classified as large under EU thresholds because headcount far exceeds medium limits.', 'A retailer with thirty staff meets the small headcount test.', 'Steve''s repair shop with two staff meets the micro headcount test.', 'Tina and Steve''s bakery with six staff meets the micro headcount test.', 'A village craft business with four staff meets the micro headcount test.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — AT&S''s ~10,000 staff exceeds the 250-person medium ceiling.', 'TRUE — Thirty employees is below the fifty-person small limit.', 'TRUE — Two employees is below the ten-person micro limit.', 'TRUE — Six employees is below the ten-person micro limit.', 'TRUE — Four employees is below the ten-person micro limit.'], '3/5', 36, 'full' ),
( '3.4', 'CASE 3.4.37', 'Tina Steve versus AT&S', 'Contrast Tina and Steve''s bakery with AT&S when discussing business size:', ARRAY['A family firm with exactly ten staff fails the micro headcount test.', 'A logistics company with exactly fifty staff fails the small headcount test.', 'A wholesaler with thirty-eight staff meets the small headcount test.', 'An architect practice with nine staff meets the micro headcount test.', 'A textile plant with exactly two hundred fifty staff fails the medium headcount test.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Ten is not fewer than ten, so micro staff test fails.', 'TRUE — Fifty is not fewer than fifty, so small staff test fails.', 'TRUE — Thirty-eight employees is below the fifty-person small limit.', 'TRUE — Nine employees is below the ten-person micro limit.', 'TRUE — 250 is not fewer than 250, so medium staff test fails.'], '2/5', 37, 'full' ),
( '3.4', 'CASE 3.4.38', 'Incomplete application data', 'An agency reviews an applicant with nine staff but incomplete turnover data; assess:', ARRAY['Turnover of €600k exceeds the micro turnover cap of €2m.', 'A firm with thirty-eight staff is micro because it employs fewer than fifty people.', 'Turnover at or below €2m can satisfy the micro financial test.', 'A firm with forty-five staff is micro because it employs fewer than fifty people.', 'Turnover of €180k exceeds the micro turnover cap of €2m.'], ARRAY[false, false, true, false, false], ARRAY['FALSE — €600k is within the €2m micro turnover ceiling.', 'FALSE — Thirty-eight staff exceeds the micro ceiling of fewer than ten.', 'TRUE — €2m is the micro turnover ceiling.', 'FALSE — Forty-five staff exceeds the micro ceiling of fewer than ten.', 'FALSE — €180k is within the €2m micro turnover ceiling.'], '4/5', 38, 'full' ),
( '3.4', 'CASE 3.4.39', 'Medium turnover-only breach', 'A firm has two hundred staff, €55m turnover, and a €42m balance sheet; assess medium status:', ARRAY['Medium status follows from international operations regardless of headcount.', 'Crossing the micro staff ceiling immediately classifies a firm as large.', 'SME classification is optional for firms seeking EU support programmes.', 'Micro status follows from supplying larger manufacturers regardless of headcount.', 'Turnover at or below €10m can satisfy the small financial test.'], ARRAY[false, false, false, false, true], ARRAY['FALSE — Medium status depends on EU thresholds, not geographic scope.', 'FALSE — Ten staff fails micro but small and medium tiers still exist.', 'FALSE — Official SME criteria gate access to many support schemes.', 'FALSE — Supplier relationships do not determine EU size classification.', 'TRUE — €10m is the small turnover ceiling.'], '5/5', 39, 'full' ),
( '3.4', 'CASE 3.4.40', 'SME employment nuance', 'Assess claims linking SME business counts with employment patterns:', ARRAY['Turnover at or below €50m can satisfy the medium financial test.', 'Balance sheet at or below €43m can satisfy the medium financial test.', 'Crossing the small staff ceiling immediately classifies a firm as large.', 'Fewer than ten employees can satisfy the micro headcount test.', 'Balance sheet figures are ignored for medium status when turnover qualifies.'], ARRAY[true, true, false, true, false], ARRAY['TRUE — €50m is the medium turnover ceiling.', 'TRUE — €43m is the medium balance sheet ceiling.', 'FALSE — Fifty staff fails small but medium tier may still apply.', 'TRUE — €2m is the micro balance sheet ceiling.', 'FALSE — Either financial cap can disqualify medium status when breached.'], '3/5', 40, 'full' ),
( '3.4', 'CASE 3.4.41', 'Financial cap literacy', 'Students must recall EU financial caps; evaluate mixed threshold statements:', ARRAY['Definitions actively shape finance access and regulatory treatment of firms.', 'Meeting one SME criterion alone does not guarantee overall SME status in a tier.', 'Micro enterprises dominate EU business counts as part of the broader SME group.', 'The ninety-nine percent SME statistic refers to business numbers, not GDP share.', 'Progression through SME tiers follows successive threshold crossings as firms grow.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — SME labels affect support and reporting, not just description.', 'TRUE — Each tier requires joint staff and financial tests.', 'TRUE — Micro firms contribute to the ~99% SME majority by number.', 'TRUE — Fuhrmann Ch3 cites SME prevalence by count.', 'TRUE — Firms can move from micro to small to medium with growth.'], '3/5', 41, 'full' ),
( '3.4', 'CASE 3.4.42', 'Micro local economy role', 'Assess the economic role of micro firms such as local shops and workshops:', ARRAY['Medium enterprises must satisfy staff limits and at least one financial cap.', 'Small enterprises must satisfy staff limits and the €10m turnover cap.', 'Both turnover and balance sheet must pass for micro status to be granted.', 'Both turnover and balance sheet must fail for medium status to be denied.', 'Turnover figures are ignored for medium status when balance sheet qualifies.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Medium uses combined staff and financial criteria.', 'TRUE — Small uses combined staff and turnover criteria.', 'FALSE — Only one financial measure must qualify for micro status.', 'FALSE — Breaching either financial cap can block medium classification.', 'FALSE — Either financial cap can disqualify medium status when breached.'], '2/5', 42, 'full' ),
( '3.4', 'CASE 3.4.43', 'Staff-only exam trap', 'A case lists eight staff and asks whether SME status is certain; evaluate reasoning:', ARRAY['Eight staff alone cannot confirm micro status without turnover or balance sheet verification.', 'Classification review requires both headcount and financial figures for EU SME tiers.', 'Grant schemes ignore official micro thresholds when the applicant is a local shop.', 'Grant officers may ignore turnover data when a shop has nine staff.', 'A tech group with three thousand staff is treated as large under EU size rules.'], ARRAY[false, true, false, false, true], ARRAY['FALSE — EU micro rules require financial thresholds alongside headcount.', 'TRUE — Incomplete data prevents reliable SME verification.', 'FALSE — Support programmes use standard EU micro criteria.', 'FALSE — Support programmes use standard EU micro criteria including financial tests.', 'TRUE — 3,000 employees exceeds all SME staff ceilings.'], '5/5', 43, 'full' ),
( '3.4', 'CASE 3.4.44', 'Leaving SME status effects', 'A firm crosses medium limits and becomes large; assess practical effects:', ARRAY['EU SME tables pair each tier with distinct staff and financial ceilings.', 'One hundred and twenty staff with €52m turnover fails the medium turnover test.', 'Two hundred staff with €55m turnover fails the medium turnover test.', 'Accounting rule sets can differ between micro firms and large groups such as AT&S.', 'A firm crossing medium limits becomes ineligible for certain EU SME finance programmes.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Micro, small, and medium each have separate threshold rows.', 'TRUE — €52m exceeds the €50m medium turnover cap.', 'TRUE — €55m exceeds the €50m medium turnover cap.', 'TRUE — Size classification affects applicable accounting rules.', 'TRUE — SME-tied support excludes firms above medium thresholds.'], '3/5', 44, 'full' ),
( '3.4', 'CASE 3.4.45', 'Small retailer headroom', 'A retailer has thirty staff and €9.9m turnover; assess small enterprise claims:', ARRAY['A manufacturer with two hundred forty staff can meet the medium staff test.', 'Micro enterprises may use a €10m turnover cap instead of the €2m micro limit.', 'An engineering firm with two hundred staff can meet the medium staff test.', 'One hundred and eighty staff with €45m turnover can meet medium staff and turnover tests.', 'Small enterprises are capped at €2m turnover rather than the €10m small limit.'], ARRAY[true, false, true, true, false], ARRAY['TRUE — 240 is below the 250-person medium limit.', 'FALSE — €10m is the small turnover cap, not the micro cap.', 'TRUE — 200 is below the 250-person medium limit.', 'TRUE — 180 staff and €45m turnover fit medium ceilings.', 'FALSE — €2m is the micro turnover cap, not the small cap.'], '2/5', 45, 'full' ),
( '3.4', 'CASE 3.4.46', 'Medium mid-range profile', 'Assess medium classification for a firm with one hundred twenty-five staff, €25m turnover, and €30m balance sheet:', ARRAY['Grant eligibility for micro enterprises requires meeting official micro thresholds.', 'The EU medium cap for turnover is €10m rather than €50m.', 'SME verification for bank loans may require proof of headcount and turnover bands.', 'Fuhrmann Ch3 states that large firms publish no financial information.', 'The EU medium cap for balance sheet is €50m rather than €43m.'], ARRAY[true, false, true, false, false], ARRAY['TRUE — Micro grants use standard EU micro criteria.', 'FALSE — €10m is the small turnover cap, not the medium cap.', 'TRUE — Lenders check official SME thresholds for guarantee schemes.', 'FALSE — Large firms face reporting duties rather than exemption.', 'FALSE — €43m is the medium balance sheet cap in the EU table.'], '2/5', 46, 'full' ),
( '3.4', 'CASE 3.4.47', 'SME synthesis review', 'Synthesise EU SME classification principles for exam review:', ARRAY['Fuhrmann Ch3 treats AT&S as a medium enterprise by headcount.', 'About ninety-nine percent of EU employees work in SMEs because ninety-nine percent of firms are SMEs.', 'A firm at eight staff is not confirmed as micro without financial verification.', 'Micro enterprises are omitted from the ninety-nine percent SME business count.', 'Fuhrmann Ch3 treats Tina and Steve as a large enterprise example.'], ARRAY[false, false, true, false, false], ARRAY['FALSE — AT&S''s ~10,000 staff exceeds medium limits.', 'FALSE — The statistic refers to business numbers, not employment share.', 'TRUE — Headcount alone does not confirm micro status.', 'FALSE — Micro firms are included in SME counts.', 'FALSE — Tina and Steve illustrate micro-scale operations in the chapter.'], '1/5', 47, 'full' ),
( '3.4', 'CASE 3.4.48', 'Turnover-only student error', 'A student argues a firm is medium because turnover is €40m; assess the reasoning error:', ARRAY['A firm at nine staff is not confirmed as micro without financial verification.', 'Small turnover of €9.5m stays within the €10m small cap.', 'Medium turnover of €40m stays within the €50m medium cap.', 'Micro turnover at or below €2m can satisfy the micro financial test.', 'Small status requires fewer than fifty staff plus turnover at or below €10m.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Headcount alone does not confirm micro status.', 'TRUE — €9.5m meets the small turnover threshold.', 'TRUE — €40m meets the medium turnover threshold.', 'TRUE — €2m is the micro turnover ceiling.', 'TRUE — Small combines staff ceiling with the €10m turnover cap.'], '4/5', 48, 'full' ),
( '3.4', 'CASE 3.4.49', 'Village craft micro profile', 'A village craft business has four staff and €600k turnover; assess classification:', ARRAY['Micro turnover of €1.6m balance sheet context still allows €1.6m balance sheet under €2m cap.', 'Micro turnover of €1.7m balance sheet total stays within the €2m micro balance sheet cap.', 'Micro turnover of €1.5m stays within the €2m micro cap.', 'A firm becomes large immediately upon employing a tenth worker.', 'Small turnover of €8m stays within the €10m small cap.'], ARRAY[true, true, true, false, true], ARRAY['TRUE — €1.6m meets the micro balance sheet threshold.', 'TRUE — €1.7m meets the micro balance sheet threshold.', 'TRUE — €1.5m meets the micro turnover threshold.', 'FALSE — Ten staff fails micro but further tiers depend on additional tests.', 'TRUE — €8m meets the small turnover threshold.'], '1/5', 49, 'full' ),
( '3.4', 'CASE 3.4.50', 'SME ladder progression', 'Place a growing firm on the SME ladder as it adds staff and sales:', ARRAY['Medium balance sheet of €40m stays within the €43m medium cap.', 'Micro balance sheet of €1.8m stays within the €2m micro cap.', 'Small turnover at or below €10m can satisfy the small financial test.', 'A firm becomes large immediately upon reaching €2.1m turnover.', 'One criterion alone is enough for medium status when turnover is €40m.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — €40m meets the medium balance sheet threshold.', 'TRUE — €1.8m meets the micro balance sheet threshold.', 'TRUE — €10m is the small turnover ceiling.', 'FALSE — Turnover above €2m removes micro status but small or medium may apply.', 'FALSE — Medium requires sub-250 staff plus financial tests.'], '3/5', 50, 'full' ),
( '3.5', 'CASE 3.5.01', 'Local bakery scope', 'A neighbourhood bakery serves walk-in customers within one district; assess geographic scope claims:', ARRAY['A firm is local only if it employs fewer than ten people regardless of customer location.', 'National businesses sell in every country on the same continent by definition.', 'Local and regional firms often face challenges raising funds and finding enough customers.', 'Local and regional businesses typically operate in a limited geographic area with customers nearby.', 'Regional businesses operate worldwide but with smaller marketing budgets than multinationals.'], ARRAY[false, false, true, true, false], ARRAY['FALSE — Local scope is defined by operating area and customer proximity, not SME headcount.', 'FALSE — National scope is confined to the home country, not continental reach.', 'TRUE — Funding access and customer reach are cited challenges for geographically focused firms.', 'TRUE — Local/regional scope is defined by a restricted operating area and proximate customers.', 'FALSE — Regional firms remain within a limited territory, not worldwide.'], '2/5', 1, 'full' ),
( '3.5', 'CASE 3.5.02', 'Regional supplier reach', 'A regional dairy delivers to shops across one province; evaluate local, regional, and national labels:', ARRAY['Undercapitalisation is unknown among local firms once they register for VAT.', 'A national business operates within its home country rather than across foreign markets.', 'Undercapitalisation is a risk particularly associated with smaller geographically focused firms.', 'A website visible abroad makes a firm multinational even without cross-border sales.', 'National operations typically involve a longer supply chain than a very local producer.'], ARRAY[false, true, true, false, true], ARRAY['FALSE — Registration does not remove capital constraints noted for local/regional firms.', 'TRUE — National scope confines activity to the home country.', 'TRUE — Limited capital is linked to local/regional business constraints in Fuhrmann Ch3.', 'FALSE — Online presence alone does not equal cross-border production or sales.', 'TRUE — National activity lengthens supply chains compared with very local operations.'], '3/5', 2, 'full' ),
( '3.5', 'CASE 3.5.03', 'National retailer chain', 'A home-country supermarket chain sources nationally but sells only domestically; assess scope statements:', ARRAY['Globalisation means every small shop becomes a multinational overnight.', 'International or multinational firms make and/or sell in more than one country.', 'International business uses one legal system worldwide so compliance is uniform.', 'National supply chains are shorter than local ones because transport is faster domestically.', 'Local businesses face no difficulty finding customers because proximity guarantees demand.'], ARRAY[false, true, false, false, false], ARRAY['FALSE — Globalisation refers to rising multinational enterprise activity, not all shops.', 'TRUE — Cross-border production or sales define international/multinational scope.', 'FALSE — Multiple legal systems apply across countries.', 'FALSE — Fuhrmann Ch3 states national chains are longer than local ones.', 'FALSE — Local/regional firms can struggle to find enough customers despite nearby catchments.'], '3/5', 3, 'full' ),
( '3.5', 'CASE 3.5.04', 'AT&S multinational scope', 'AT&S manufactures and sells across several countries; evaluate multinational classification claims:', ARRAY['Regional scope allows unlimited customers anywhere on the globe.', 'Globalisation is described as the rise of multinational enterprises operating across borders.', 'Selling nationwide while owners stay in one town makes the business local by residence.', 'International business must cope with different cultures, languages, and currencies.', 'Operating internationally lengthens the supply chain and crosses legal and economic systems.'], ARRAY[false, true, false, true, true], ARRAY['FALSE — Regional businesses serve a limited area, not global markets.', 'TRUE — Globalisation is tied to spreading multinational enterprise activity.', 'FALSE — Nationwide sales indicate national scope despite owner location.', 'TRUE — Cultures, languages, and currencies are named complications of international business.', 'TRUE — International scope brings longer chains plus differing legal and economic frameworks.'], '2/5', 4, 'full' ),
( '3.5', 'CASE 3.5.05', 'Local customer proximity', 'Assess what defines a local or regional business by customer and operating area:', ARRAY['Manufacturing in one country and selling in another indicates international/multinational scope.', 'Customer proximity and a limited service area characterise local business scope.', 'Regional businesses still operate within a defined territory rather than worldwide.', 'Selling only within the home country fits national rather than international scope.', 'A multinational must produce in every country where it sells by definition in Fuhrmann Ch3.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Cross-border production combined with foreign sales exceeds national boundaries.', 'TRUE — Local firms chiefly serve nearby customers within a restricted area.', 'TRUE — Regional scope remains geographically bounded though broader than a single neighbourhood.', 'TRUE — Home-country-only sales align with national classification.', 'FALSE — Making and/or selling in more than one country suffices; both everywhere is not required.'], '2/5', 5, 'full' ),
( '3.5', 'CASE 3.5.06', 'Regional funding challenge', 'A regional craft firm struggles to raise funds and find customers; evaluate characteristic claims:', ARRAY['AT&S operating across countries illustrates a multinational enterprise reinventing its model.', 'Limited capital can constrain a local firm''s ability to expand beyond its immediate market.', 'Currency differences disappear once a firm opens a foreign bank account.', 'Undercapitalisation affects only multinational firms building foreign factories.', 'Culture and language differences matter only to tourist shops, not to manufacturers.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — AT&S exemplifies large-scale multinational scope in Fuhrmann Ch3.', 'TRUE — Undercapitalisation limits growth for geographically focused firms.', 'FALSE — Operating across borders still involves multiple currencies.', 'FALSE — Fuhrmann Ch3 links undercapitalisation chiefly to local/regional business challenges.', 'FALSE — Cultures and languages apply to international business generally.'], '4/5', 6, 'full' ),
( '3.5', 'CASE 3.5.07', 'Undercapitalisation risk', 'Assess undercapitalisation as a challenge linked to smaller geographic scope:', ARRAY['Importing finished goods for domestic resale makes a firm a manufacturer in two countries.', 'Multiple legal systems apply when a firm conducts business in several countries.', 'Language differences matter for customer contact in international markets.', 'Globalisation excludes service firms and applies only to factories.', 'A longer supply chain is typical when sourcing and selling nationally rather than locally.'], ARRAY[false, true, true, false, true], ARRAY['FALSE — Domestic resale of imports is not the same as producing abroad.', 'TRUE — International operations cross differing legal frameworks.', 'TRUE — Languages are among international business complications.', 'FALSE — Globalisation concerns multinational enterprise broadly, not factories alone.', 'TRUE — National scope implies greater supply chain length than local operations.'], '4/5', 7, 'full' ),
( '3.5', 'CASE 3.5.08', 'National supply chain length', 'Compare supply chain length for a national manufacturer versus a local workshop:', ARRAY['Proximity to customers removes any need to seek sales for local firms.', 'National businesses operate in more than one country as long as they use domestic currency.', 'Currency differences arise when trading across international borders.', 'AT&S is a local enterprise because its first plant was in one town.', 'Globalisation reflects more firms producing and selling beyond a single country.'], ARRAY[false, false, true, false, true], ARRAY['FALSE — Finding customers remains a cited challenge for local/regional firms.', 'FALSE — National firms stay within the home country.', 'TRUE — Multiple currencies are part of international business conditions.', 'FALSE — AT&S exemplifies large multinational scope with cross-border activity.', 'TRUE — Rising multinationals underpin the Fuhrmann Ch3 view of globalisation.'], '3/5', 8, 'full' ),
( '3.5', 'CASE 3.5.09', 'International legal complexity', 'A firm sells in three countries with differing contract laws; assess international business claims:', ARRAY['Regional hauliers moving goods within a territory still face geographic limits compared with national networks.', 'Regional firms can ignore capital needs because banks lend equally in every village.', 'Domestic-only sales and production within one country describe national scope.', 'Cross-border manufacturing is still national if headquarters stays at home.', 'A plumber serving one town operates locally with nearby customers.'], ARRAY[true, false, true, false, true], ARRAY['TRUE — Regional scope is broader than local but remains below national/international reach.', 'FALSE — Raising funds is a stated challenge for local/regional businesses.', 'TRUE — Confining activity to the home country is national classification.', 'FALSE — Production abroad contributes to international/multinational scope.', 'TRUE — Single-town service fits local scope with proximate customers.'], '4/5', 9, 'full' ),
( '3.5', 'CASE 3.5.10', 'Globalisation definition', 'Evaluate globalisation as described through the rise of multinational enterprises:', ARRAY['Cross-border production partnerships indicate international rather than purely national scope.', 'International firms use identical economic systems in every market they enter.', 'A domestic-only rail network is multinational because cargo may originate from imports.', 'Local scope is determined solely by whether the firm is an SME under EU rules.', 'Exporting forty percent of output while producing at home cannot coexist with any national label.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Foreign production links exceed national boundaries.', 'FALSE — Economic systems differ internationally.', 'FALSE — Domestic routing fits national scope unless operating across countries.', 'FALSE — Geographic scope and SME size classification are separate concepts.', 'FALSE — Export sales cross national boundaries and affect scope labels.'], '2/5', 10, 'full' ),
( '3.5', 'CASE 3.5.11', 'Local versus national trap', 'A shop sells nationwide online but is described as local because owners live nearby; assess:', ARRAY['Regional branding across neighbouring counties remains below national or international scope.', 'National airlines operating domestic routes are local because planes land nearby.', 'Local businesses depend heavily on customers in the immediate area.', 'Multinational status requires ignoring local cultures to enforce one corporate language.', 'Regional seasonal hotels face no customer-finding challenge during off-season months.'], ARRAY[true, false, true, false, false], ARRAY['TRUE — Regional reach is limited compared with country-wide or cross-border operations.', 'FALSE — Country-wide networks reflect national rather than local scope.', 'TRUE — Proximate customers define local enterprise markets.', 'FALSE — Cultural differences remain relevant in international operations.', 'FALSE — Seasonal regional demand illustrates limited customer-base constraints.'], '5/5', 11, 'full' ),
( '3.5', 'CASE 3.5.12', 'Regional market limits', 'A regional tour operator serves holidaymakers across neighbouring counties only; assess scope:', ARRAY['Compliance costs increase when obeying rules in several countries simultaneously.', 'Local market saturation is impossible where population is growing.', 'Regional grants prove a firm is multinational because money crosses municipal borders.', 'Undercapitalisation can hinder fund raising for firms focused on a small market area.', 'Stakeholder geography is unrelated to whether a firm is multinational.'], ARRAY[true, false, false, true, false], ARRAY['TRUE — Multiple jurisdictions raise legal compliance burdens internationally.', 'FALSE — Saturation concerns nearby customers already served, not population trends alone.', 'FALSE — Regional support targets limited-area firms, not multinational classification.', 'TRUE — Limited capital is a stated challenge for local/regional firms.', 'FALSE — Multinational operations spread activities and stakeholders across countries.'], '3/5', 12, 'full' ),
( '3.5', 'CASE 3.5.13', 'National home country focus', 'A publisher prints and distributes exclusively within its home country; assess national scope:', ARRAY['Multinational operations spread stakeholders and activities across countries.', 'National scale eliminates supply chain length because everything is domestic.', 'International business avoids longer supply chains by using email orders.', 'Seasonal regional tourism income reflects a geographically limited customer base.', 'A domestic rail freight network operating nationally has a longer chain than a neighbourhood supplier.'], ARRAY[true, false, false, true, true], ARRAY['TRUE — Cross-border operations widen geographic stakeholder and activity reach.', 'FALSE — National scope still lengthens chains compared with very local producers.', 'FALSE — International operations lengthen supply chains in Fuhrmann Ch3.', 'TRUE — Regional seasonal demand fits limited-area customer dependence.', 'TRUE — National logistics extend supply chains beyond local reach.'], '2/5', 13, 'full' ),
( '3.5', 'CASE 3.5.14', 'Multinational production', 'A car parts firm produces in two countries and sells in five; assess multinational claims:', ARRAY['Home-country-only publishers are international if they translate books into another language.', 'A provincial dairy delivering within one province is a multinational because milk crosses county lines.', 'Local cafés face no undercapitalisation risk if they accept card payments.', 'Globalisation means national firms disappear entirely from the home economy.', 'Local market saturation occurs when most nearby customers are already served.'], ARRAY[false, false, false, false, true], ARRAY['FALSE — Translation alone without foreign sales or production does not establish international scope.', 'FALSE — Intraprovincial delivery remains regional, not international.', 'FALSE — Payment methods do not remove capital constraints on expansion.', 'FALSE — Globalisation highlights rising multinationals, not elimination of national firms.', 'TRUE — Limited local demand can saturate when proximate customers are exhausted.'], '3/5', 14, 'full' ),
( '3.5', 'CASE 3.5.15', 'Currency exposure abroad', 'An exporter invoices in euros and dollars across borders; assess international operation claims:', ARRAY['National scale operations extend supply chains across the home country.', 'Policy support for regional firms often targets limited-area operators.', 'Importing for domestic resale alone does not by itself make a firm a multinational manufacturer.', 'Local scope means both limited operating area and chiefly nearby customers.', 'Operating in two countries eliminates exposure to different currencies.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Country-wide activity lengthens domestic supply chains.', 'TRUE — Regional programmes align with geographically bounded businesses.', 'TRUE — Reselling imports domestically differs from producing across countries.', 'TRUE — Fuhrmann Ch3 pairs limited area with customer proximity for local/regional firms.', 'FALSE — Multiple currencies remain a factor across borders.'], '4/5', 15, 'full' ),
( '3.5', 'CASE 3.5.16', 'Cultural differences trade', 'Staff manage teams across cultures in multiple subsidiaries; assess international business features:', ARRAY['International firms encounter varied economic systems across markets.', 'A neighbourhood bakery with walk-in local buyers is not national merely because it is registered as a company.', 'Operating in more than one country increases coordination across languages and currencies.', 'Cultural awareness matters when managing staff and customers in foreign subsidiaries.', 'Exporting a minority share while producing domestically may still be national if foreign sales are absent.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Economic systems differ internationally alongside legal frameworks.', 'TRUE — Scope follows market reach, not registration formalities alone.', 'TRUE — Multinational activity multiplies language and currency management needs.', 'TRUE — Cultural differences are part of international business complexity.', 'TRUE — Scope labels depend on where firms make and sell, not a single metric alone.'], '4/5', 16, 'full' ),
( '3.5', 'CASE 3.5.17', 'Language barriers commerce', 'Customer support handles queries in four languages across markets; assess scope implications:', ARRAY['Globalisation in Fuhrmann Ch3 emphasises multinational enterprise growth.', 'National wholesalers have shorter supply chains than street vendors by Fuhrmann Ch3 definition.', 'Regional competitors are irrelevant because regional firms share identical customers.', 'Regional firms may struggle to fund growth because their customer base stays geographically bounded.', 'National retailers sourcing nationwide face longer supply chains than district shops.'], ARRAY[true, false, false, true, true], ARRAY['TRUE — Globalisation is tied to rising multinationals in the chapter framework.', 'FALSE — National networks typically lengthen supply chains versus very local vendors.', 'FALSE — Regional rivals operate within the same limited area competing for customers.', 'TRUE — Limited markets tie to funding and customer-finding challenges.', 'TRUE — National sourcing extends chains compared with local suppliers.'], '3/5', 17, 'full' ),
