( '3.6', 'CASE 3.6.03', 'Owner risk reward', 'Assess owner exposure to risk and reward in enterprise activity:', ARRAY['Reward for owners is unrelated to how well the business trades.', 'Owners bear financial risk when revenue falls short of costs and may lose invested capital.', 'Owners share gains with staff but face no downside when sales decline sharply.', 'Risk and reward apply only to employees, not to people who provide capital.', 'Owners receive profit without risk because limited liability guarantees positive returns.'], ARRAY[false, true, false, false, false], ARRAY['FALSE — Owner returns depend on business performance and profitability.', 'TRUE — Risk bearing is central to the owner stakeholder position.', 'FALSE — Owners can lose value and returns when trading performance is poor.', 'FALSE — Owners face risk and seek reward for capital invested.', 'FALSE — Limited liability limits personal loss but does not remove owner risk entirely.'], '3/5', 3, 'full' ),
( '3.6', 'CASE 3.6.04', 'Manager income security', 'Managers weigh income and security when judging business decisions; evaluate claims:', ARRAY['Restructuring decisions that threaten jobs show managers are affected as stakeholders.', 'Job security matters to managers because firm failure could end their employment.', 'Managers seek stable income from the employing firm as a core stakeholder interest.', 'Managers depend on continued firm success for promotion and salary prospects.', 'Managers are stakeholders because business outcomes affect their careers and pay.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Managers are stakeholders because firm outcomes affect their careers and income.', 'TRUE — Security of employment is part of manager stakeholder interests.', 'TRUE — Income is listed among manager stakeholder concerns.', 'TRUE — Manager livelihoods tie to firm performance.', 'TRUE — Managers are included among business stakeholders.'], '3/5', 4, 'full' ),
( '3.6', 'CASE 3.6.05', 'Employee identification', 'Bakery staff may identify with Tina and Steve''s business success; assess stakeholder claims:', ARRAY['Staff depend on the bakery''s continued operation for wages and job security.', 'Employees are not stakeholders because they do not invest capital in the bakery.', 'Job security is a legitimate employee stakeholder interest alongside monthly wages.', 'Employees may identify with the bakery and feel pride when it succeeds locally.', 'Employees lose stakeholder status once they receive their monthly wage payment.'], ARRAY[true, false, true, true, false], ARRAY['TRUE — Employees depend on firm success for livelihood.', 'FALSE — Employees are stakeholders even without share ownership.', 'TRUE — Security of employment sits alongside income for employees.', 'TRUE — Identification with firm success is an employee stakeholder theme.', 'FALSE — Job security and identification tie employees to ongoing firm outcomes.'], '3/5', 5, 'full' ),
( '3.6', 'CASE 3.6.06', 'Mutual dependence staff', 'Assess mutual dependence between managers, employees, and the employing firm:', ARRAY['Managers and employees are mutually dependent on the business with the owners'' venture.', 'The firm can operate indefinitely without managers or employees contributing labour.', 'Staff livelihoods are unaffected when the employing firm stops trading.', 'Mutual dependence applies only between customers and suppliers, not between staff and the firm.', 'Owners alone create output; staff dependence on the firm is a one-way relationship.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Mutual dependence links managers, employees, and the firm.', 'FALSE — The business depends on staff to operate and generate revenue.', 'FALSE — Closure harms staff jobs and income tied to the firm.', 'FALSE — Managers and employees are mutually dependent on the business.', 'FALSE — Both staff and the firm need each other for ongoing success.'], '4/5', 6, 'full' ),
( '3.6', 'CASE 3.6.07', 'Shared values culture', 'Evaluate shared values as a link between staff and organisational success:', ARRAY['When personal values align with company practices, staff engagement often improves.', 'Shared values guarantee identical opinions on every management decision.', 'Employment contracts alone make shared values irrelevant to stakeholder relations.', 'Shared values can strengthen cooperation between employees and management on firm goals.', 'Shared values between staff and the organisation can support business success.'], ARRAY[true, false, false, true, true], ARRAY['TRUE — Alignment of values supports cooperation on business goals.', 'FALSE — Shared values support alignment but conflicts can still arise among stakeholders.', 'FALSE — Shared values between staff and organisation matter in stakeholder analysis.', 'TRUE — Shared values support mutual dependence and identification themes.', 'TRUE — Shared values link employees with organisational performance.'], '3/5', 7, 'full' ),
( '3.6', 'CASE 3.6.08', 'Supplier payment expectations', 'Suppliers expect payment and future orders; assess their stakeholder interests:', ARRAY['Suppliers expect to be paid for goods delivered to the buying business.', 'Stakeholder analysis includes suppliers expecting both payment and continued commercial relationship.', 'Suppliers are stakeholders because firm decisions affect their cash flow and volumes.', 'Fair payment terms reflect supplier stakeholder interests, not only accounting detail.', 'Suppliers rely on future orders, not only payment for past deliveries.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Payment is a core supplier stakeholder interest.', 'TRUE — Supplier interests combine cash flow and order volume.', 'TRUE — Suppliers are stakeholders through payment and order dependency.', 'TRUE — Payment and order treatment reflect supplier stakeholder interests.', 'TRUE — Future orders matter to suppliers as ongoing stakeholders.'], '3/5', 8, 'full' ),
( '3.6', 'CASE 3.6.09', 'Supplier quality delivery', 'Suppliers depend on quality expectations and timely delivery from their own operations; assess:', ARRAY['Late or defective shipments are solely the buyer''s problem, not the supplier''s concern.', 'Suppliers need not worry about timeliness because buyers hold all delivery risk.', 'Timely delivery is part of the supplier''s stakeholder duty toward the buying firm.', 'Suppliers must deliver quality goods on time to satisfy the buying business.', 'Quality standards apply only to the buyer''s internal staff, not to external suppliers.'], ARRAY[false, false, true, true, false], ARRAY['FALSE — Supplier performance affects the buyer''s ability to serve customers.', 'FALSE — Timely delivery is a supplier responsibility in the mutual dependency chain.', 'TRUE — Suppliers must deliver quality and timeliness to fulfil their role.', 'TRUE — Quality and timely delivery are supplier responsibilities.', 'FALSE — Suppliers must meet quality and delivery expectations toward customers.'], '3/5', 9, 'full' ),
( '3.6', 'CASE 3.6.10', 'Customer mutual dependency', 'Tina and Steve''s bakery customers depend on the shop for fresh bread; assess mutual dependency claims:', ARRAY['Mutual dependency means both parties need each other for continued benefit.', 'Customers depend on firms but firms do not depend on customers for revenue.', 'Customers depend on the bakery for product quality and daily availability.', 'Tina and Steve depend on customers for revenue that keeps the bakery trading.', 'If the bakery closes, regular customers lose a relied-upon source of fresh bread.'], ARRAY[true, false, true, true, true], ARRAY['TRUE — Mutual dependency runs between customers and firms.', 'FALSE — Mutual dependency means firms rely on customers for revenue.', 'TRUE — Customers rely on firms for products and services.', 'TRUE — Firms depend on customers for sales and revenue.', 'TRUE — Customer welfare ties to firm performance through mutual dependency.'], '4/5', 10, 'full' ),
( '3.6', 'CASE 3.6.11', 'Community interest', 'Local communities can be affected by nearby business activity; evaluate stakeholder claims:', ARRAY['Residents may care about noise, pollution, and employment created by a nearby firm.', 'Communities near a plant can be stakeholders affected by jobs, traffic, and local spending.', 'Community opposition to expansion can signal conflicting stakeholder interests.', 'A town relying on one major employer shows community stake in that firm''s survival.', 'Communities cannot be stakeholders because they do not sign contracts with the firm.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Local amenities and jobs link communities to business outcomes.', 'TRUE — Communities are affected by business activity and count as stakeholders.', 'TRUE — Community and owner interests may conflict on expansion impacts.', 'TRUE — Local employment ties community interests to firm outcomes.', 'FALSE — Communities are affected by business activity and count as stakeholders.'], '3/5', 11, 'full' ),
( '3.6', 'CASE 3.6.12', 'Government interest', 'Governments take an interest in business activity within their jurisdiction; assess:', ARRAY['Government stakeholder interest disappears wherever markets operate without formal rules.', 'Government is a stakeholder only when it owns shares in nationalised industries.', 'Regulators represent broader public interest when setting business rules.', 'Government has no stake in local tax-paying businesses because it only collects fixed fees.', 'Government has an interest in business activity through tax, regulation, and public policy.'], ARRAY[false, false, true, false, true], ARRAY['FALSE — Tax and policy interests remain even where regulation is light.', 'FALSE — Government interest arises from regulation, tax, and public policy broadly.', 'TRUE — Government protects public interest through regulation.', 'FALSE — Tax collection links government interests to business trading performance.', 'TRUE — Government is a stakeholder via tax, regulation, and policy.'], '3/5', 12, 'full' ),
( '3.6', 'CASE 3.6.13', 'Environment real action', 'Assess environmental stakeholders'' expectation of genuine action rather than superficial claims:', ARRAY['Superficial eco-labels without operational change fully meet environmental stakeholder expectations.', 'Real environmental action is less important than using the word sustainable in advertising.', 'Environmental action requires only a logo change without process improvement.', 'Environmental stakeholders expect real action rather than superficial green marketing alone.', 'Environmental stakeholders are satisfied by marketing slogans without operational change.'], ARRAY[false, false, false, true, false], ARRAY['FALSE — Real action, not slogans, is required on environmental issues.', 'FALSE — Genuine action is prioritised over superficial claims.', 'FALSE — Real operational action is expected, not cosmetic logo changes alone.', 'TRUE — Genuine environmental action is expected, not slogans alone.', 'FALSE — Genuine action is required, not greenwash slogans alone.'], '4/5', 13, 'full' ),
( '3.6', 'CASE 3.6.14', 'Greenwash warning', 'Evaluate greenwash as a stakeholder relations risk:', ARRAY['Greenwash misleads stakeholders by exaggerating environmental performance.', 'Greenwash strengthens long-term stakeholder trust more than honest reporting.', 'Greenwash means exceeding environmental standards while understating achievements.', 'Advertising recyclable packaging while increasing pollution illustrates greenwash risk.', 'Empty eco-slogans without process change can erode stakeholder trust over time.'], ARRAY[true, false, false, true, true], ARRAY['TRUE — Greenwash means exaggerated claims without real action.', 'FALSE — Greenwash misleads stakeholders and undermines trust when uncovered.', 'FALSE — Greenwash exaggerates performance rather than understating genuine achievement.', 'TRUE — Misleading green claims without real action exemplify greenwash.', 'TRUE — Misleading claims undermine long-term stakeholder trust.'], '5/5', 14, 'full' ),
( '3.6', 'CASE 3.6.15', 'Environmental reporting', 'Environmental reporting is discussed as a business responsibility; assess:', ARRAY['Disclosing environmental impacts helps stakeholders assess whether firms take genuine action.', 'Environmental reporting communicates firm impacts to interested stakeholders.', 'Sustainability reports can inform communities and investors about environmental impacts.', 'Environmental reporting without operational improvement may still mislead stakeholders.', 'The natural environment is treated as a stakeholder expecting substantive corporate response.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Reporting supports stakeholder evaluation of real environmental performance.', 'TRUE — Reporting addresses environmental stakeholder information needs.', 'TRUE — Environmental reporting serves stakeholder information needs.', 'TRUE — Reporting must reflect real action to remain credible.', 'TRUE — Environment is a stakeholder expecting action and reporting.'], '4/5', 15, 'full' ),
( '3.6', 'CASE 3.6.16', 'Conflicting interests', 'Conflicting stakeholder interests arise in many decisions; evaluate:', ARRAY['Environmental spending may reduce short-term profit, creating owner-environment tension.', 'Profit maximisation plans may conflict with community noise or pollution concerns.', 'Different stakeholder groups can have conflicting interests in the same decision.', 'All stakeholder groups want the same outcome on every business decision.', 'Stakeholder conflict is rare and only occurs between owners and customers.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Owner profit aims can clash with environmental demands.', 'TRUE — Profit and community welfare can conflict.', 'TRUE — Conflicting stakeholder interests arise in many decisions.', 'FALSE — Conflicting interests among stakeholders are common.', 'FALSE — Conflicts can arise among many stakeholder groups.'], '4/5', 16, 'full' ),
( '3.6', 'CASE 3.6.17', 'Legal structure factor', 'Legal structure is listed among other success factors; assess its stakeholder context:', ARRAY['Legal and financial structure can influence how successfully a business meets stakeholder needs.', 'Choosing a partnership rather than a company can change how owner risk is shared.', 'Legal structure is listed among factors that can affect overall business success.', 'A company''s legal form can determine reporting duties toward different stakeholder groups.', 'Legal form can shape duties owed to different stakeholder groups.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Legal and financial structure are success factors affecting stakeholders.', 'TRUE — Legal form affects how risk and duties are distributed among stakeholders.', 'TRUE — Legal structure appears among contextual success factors.', 'TRUE — Legal structure shapes how firms communicate with stakeholders.', 'TRUE — Legal structure shapes duties to stakeholder groups.'], '3/5', 17, 'full' ),
( '3.6', 'CASE 3.6.18', 'Financial structure factor', 'Financial structure appears among factors affecting business success; evaluate:', ARRAY['Financial structure choices can affect how risk is shared among owner stakeholders.', 'Financial structure matters only to accountants, not to owner or creditor stakeholders.', 'Borrowing decisions have no effect on which stakeholder groups bear business risk.', 'Equity and debt mix is unrelated to how stakeholder returns are funded.', 'Financial structure matters to creditors and owners as well as to accountants.'], ARRAY[true, false, false, false, true], ARRAY['TRUE — Financial structure influences risk sharing among owners.', 'FALSE — Financial structure influences risk sharing and success for stakeholders.', 'FALSE — Financial structure choices affect how risk is shared among stakeholders.', 'FALSE — Financial structure shapes risk and returns for stakeholder groups.', 'TRUE — Financial structure influences outcomes for owners and creditors.'], '3/5', 18, 'full' ),
( '3.6', 'CASE 3.6.19', 'Market awareness factor', 'Tina and Steve assess how market awareness affects their bakery stakeholders:', ARRAY['Ignoring local taste trends could harm Tina and Steve''s customers and their own returns.', 'Tracking customer preferences helps the bakery retain mutual dependency with its buyers.', 'Market awareness helps a firm respond to customer and competitive stakeholder pressures.', 'Market awareness concerns only rivals and has no bearing on customer stakeholders.', 'Understanding rival bakeries helps Tina and Steve keep quality attractive to regular buyers.'], ARRAY[true, true, true, false, true], ARRAY['TRUE — Market awareness affects ability to serve customer and owner interests.', 'TRUE — Responding to customers strengthens mutual dependency.', 'TRUE — Market awareness supports meeting customer and competitive pressures.', 'FALSE — Market awareness helps meet customer and competitive pressures.', 'TRUE — Market awareness supports serving customer stakeholder needs.'], '3/5', 19, 'full' ),
( '3.6', 'CASE 3.6.20', 'Cost profitability factor', 'Costs and profitability influence stakeholder outcomes; evaluate:', ARRAY['Managing costs and profitability affects what returns owners and jobs employees can sustain.', 'Costs and profitability affect only owners and have no bearing on jobs or supplier orders.', 'Cutting costs on ingredients has no effect on customer stakeholder satisfaction.', 'Employee job security is unaffected by whether the firm remains profitable.', 'Profitability levels are irrelevant to whether suppliers receive future orders.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Costs and profitability connect to owner and employee outcomes.', 'FALSE — Profitability underpins wages, orders, and returns for multiple groups.', 'FALSE — Cost decisions can affect quality and therefore customer stakeholders.', 'FALSE — Profitability underpins employment sustainability for staff.', 'FALSE — Profitability affects ability to pay suppliers and place orders.'], '3/5', 20, 'full' ),
( '3.6', 'CASE 3.6.21', 'Owners share value', 'Owners may seek increases in share or business value; assess:', ARRAY['Reinvesting profit rather than paying it out may aim to build long-term business value.', 'Owners bear losses when trading performance is poor, linking risk to reward.', 'Rising business value can reward owners for successful risk bearing over time.', 'Owners may want the value of shares or the business to increase.', 'Building a stronger brand can contribute to higher business valuation for owners.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Reinvestment choices shape owner value interests.', 'TRUE — Risk bearing is central to the owner stakeholder position.', 'TRUE — Value growth links to owner risk and reward.', 'TRUE — Share or business value growth is a recognised owner interest.', 'TRUE — Brand strength supports owner interest in rising business value.'], '3/5', 21, 'full' ),
( '3.6', 'CASE 3.6.22', 'Managers not stakeholders trap', 'A student claims only shareholders are stakeholders; evaluate:', ARRAY['Managers are not stakeholders because they are paid to execute orders without personal interest.', 'Customers are stakeholders only when they sit on the board of directors.', 'Only shareholders count as stakeholders in a listed company.', 'Stakeholders are only people who own shares; customers and employees are excluded.', 'Stakeholders include anyone affected by or interested in the business, not shareholders alone.'], ARRAY[false, false, false, false, true], ARRAY['FALSE — Managers seek income and security and are listed as stakeholders.', 'FALSE — Customers are stakeholders through mutual dependency without board seats.', 'FALSE — Stakeholders include all affected or interested parties, not shareholders alone.', 'FALSE — Stakeholders include anyone affected or interested, not owners alone.', 'TRUE — The stakeholder definition is broader than share ownership.'], '5/5', 22, 'full' ),
( '3.6', 'CASE 3.6.23', 'Employees job security', 'Employees seek job security alongside income; assess stakeholder claims:', ARRAY['Job security concerns apply only to managers, not to ordinary employees.', 'Job security is a legitimate employee stakeholder interest alongside wages.', 'Staff depend on the firm''s continued operation for wages and job security.', 'Employees are stakeholders even if they do not own shares in the company.', 'Employees and managers share dependence on continued profitable operation for livelihoods.'], ARRAY[false, true, true, true, true], ARRAY['FALSE — Employees generally seek security alongside income.', 'TRUE — Security of employment sits alongside income for employees.', 'TRUE — Employees depend on firm success for livelihood.', 'TRUE — Stakeholder status does not require ownership.', 'TRUE — Staff livelihoods depend on firm performance.'], '3/5', 23, 'full' ),
( '3.6', 'CASE 3.6.24', 'Suppliers timely orders', 'Suppliers need predictable orders as well as payment; evaluate:', ARRAY['Suppliers rely on predictable orders, not only on being paid for past deliveries.', 'Predictable order volumes are irrelevant to suppliers who already received payment.', 'Delayed or cancelled orders can threaten a supplier''s ability to retain staff and pay bills.', 'A supplier''s stakeholder interest ends once a single invoice is settled.', 'Suppliers care about payment but not about future order volumes.'], ARRAY[true, false, true, false, false], ARRAY['TRUE — Future orders matter to suppliers as ongoing stakeholders.', 'FALSE — Future orders matter to suppliers as ongoing stakeholders.', 'TRUE — Order volumes affect supplier livelihoods as stakeholders.', 'FALSE — Suppliers remain stakeholders through ongoing orders and payment.', 'FALSE — Orders and payment together define supplier stakeholder interests.'], '3/5', 24, 'full' ),
( '3.6', 'CASE 3.6.25', 'Customers quality price', 'Tina and Steve''s regular buyers depend on consistent quality and fair pricing; assess:', ARRAY['Customers suffer if a relied-upon provider fails to supply quality products on time.', 'Fair pricing and reliable quality keep Tina and Steve''s regular buyers returning to the bakery.', 'Quality and price matter only to owners, not to customer stakeholders.', 'Customers depend on firms for product quality and availability.', 'Buyers at Tina and Steve''s bakery have no stake in whether the shop stays open.'], ARRAY[true, true, false, true, false], ARRAY['TRUE — Customer welfare ties to firm performance through mutual dependency.', 'TRUE — Customers depend on firms for product quality and fair pricing.', 'FALSE — Customers depend on firms for product quality and availability.', 'TRUE — Customers rely on firms for products and services.', 'FALSE — Customers depend on the bakery through mutual dependency.'], '3/5', 25, 'full' ),
( '3.6', 'CASE 3.6.26', 'Community local impact', 'Communities near a plant care about jobs, noise, and local spending; evaluate:', ARRAY['Local communities can be stakeholders affected by jobs, traffic, and spending from nearby firms.', 'Facility expansion cannot create stakeholder conflict because communities do not trade with the firm.', 'Community jobs concerns are not stakeholder issues because employment is private.', 'Residents near an industrial plant may care about noise, pollution, and local jobs created by the firm.', 'Communities near a plant have no interest in how the firm performs commercially.'], ARRAY[true, false, false, true, false], ARRAY['TRUE — Communities are affected by business activity and count as stakeholders.', 'FALSE — Communities are stakeholders even without direct commercial contracts.', 'FALSE — Communities are affected by local employment and are stakeholders.', 'TRUE — Local amenities and jobs link communities to business outcomes.', 'FALSE — Local spending and jobs link community interests to firm activity.'], '3/5', 26, 'full' ),
( '3.6', 'CASE 3.6.27', 'Government tax compliance', 'Governments collect tax and enforce rules affecting firms; assess stakeholder role:', ARRAY['Government stakeholder interest disappears in free markets with no regulation.', 'For tax compliance purposes, government has no stake in local firms because it only collects fixed fees.', 'Enforcement of business rules shows government acting as a stakeholder in firm conduct.', 'Compliance inspections link government oversight to how firms treat wider stakeholder interests.', 'Tax collection gives government a stake in the trading performance of local firms.'], ARRAY[false, false, true, true, true], ARRAY['FALSE — Tax and policy interests remain even where regulation is light.', 'FALSE — Tax collection links government interests to business trading performance.', 'TRUE — Government is a stakeholder via regulation and policy.', 'TRUE — Government protects public interest through regulation and tax.', 'TRUE — Fiscal policy links government interests to business activity.'], '3/5', 27, 'full' ),
( '3.6', 'CASE 3.6.28', 'Environment beyond slogan', 'Assess whether environmental concerns require substantive measures, not slogans alone:', ARRAY['Eco-slogans alone can satisfy environmental stakeholders without any change to production processes.', 'Cosmetic eco-labels on packaging fully meet environmental stakeholder expectations without operational change.', 'Beyond slogans, environmental stakeholders still expect substantive measures rather than marketing alone.', 'Cosmetic branding changes satisfy environmental stakeholders without process improvement.', 'Using the word sustainable in advertising matters more than real environmental action on the shop floor.'], ARRAY[false, false, true, false, false], ARRAY['FALSE — Genuine action is required, not greenwash slogans alone.', 'FALSE — Real action, not slogans, is required on environmental issues.', 'TRUE — Genuine environmental action is expected, not slogans alone.', 'FALSE — Real operational action is expected, not cosmetic changes alone.', 'FALSE — Genuine action is prioritised over superficial claims.'], '4/5', 28, 'full' ),
( '3.6', 'CASE 3.6.29', 'Stakeholders not shareholders only', 'Evaluate breadth of stakeholder concept beyond owners alone:', ARRAY['Employees count as stakeholders through wages and job security even without owning shares.', 'Suppliers are stakeholders because payment and order decisions affect their operations.', 'Communities affected by traffic and jobs from a nearby plant count as stakeholders.', 'Stakeholders include anyone affected by or interested in the business, extending beyond shareholders.', 'Customers who depend on a firm''s products are stakeholders through mutual dependency.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Stakeholder status does not require ownership.', 'TRUE — Suppliers are stakeholders through payment and order dependency.', 'TRUE — Communities are affected by business activity and count as stakeholders.', 'TRUE — Stakeholders are defined broadly as affected or interested parties.', 'TRUE — Customers are affected by and interested in firm performance.'], '2/5', 29, 'full' ),
( '3.6', 'CASE 3.6.30', 'Owner risk bearing', 'Owners bear financial risk if the venture performs poorly; assess:', ARRAY['Poor trading performance can reduce owner returns and the value of capital they invested.', 'Rising share or business value rewards owners who accepted earlier business risk.', 'Owners receive reward without risk because businesses guarantee profits.', 'Owners typically seek profit and a return for bearing business risk.', 'Owners accept that poor results can reduce the value of their invested capital.'], ARRAY[true, true, false, true, true], ARRAY['TRUE — Risk bearing is central to the owner stakeholder position.', 'TRUE — Share or business value growth is a recognised owner interest.', 'FALSE — Owners face risk when performance is poor despite seeking profit.', 'TRUE — Owners want profit and reward for risk.', 'TRUE — Risk bearing includes potential loss of capital when performance is weak.'], '3/5', 30, 'full' ),
( '3.6', 'CASE 3.6.31', 'Manager employee dependence', 'Managers and employees rely on firm performance for livelihood; evaluate:', ARRAY['Managers can ignore firm health because their salaries are fixed regardless of results.', 'Staff wages continue unchanged even when the employing firm stops trading permanently.', 'Managers and employees both rely on the firm''s continued operation for income and jobs.', 'Employees need the firm for wages but the firm does not need employees to operate.', 'Mutual dependence between staff and firm is limited to customer-supplier links in the market.'], ARRAY[false, false, true, false, false], ARRAY['FALSE — Income and job security tie managers to firm performance.', 'FALSE — Closure harms staff jobs and income tied to the firm.', 'TRUE — Mutual dependence links managers, employees, and the firm.', 'FALSE — The business depends on staff to operate and generate revenue.', 'FALSE — Managers and employees are mutually dependent on the business.'], '4/5', 31, 'full' ),
( '3.6', 'CASE 3.6.32', 'Supplier buyer relationship', 'Tina and Steve''s flour supplier relies on their bakery for orders and payment; assess:', ARRAY['Only the bakery owners are stakeholders in the flour supply arrangement.', 'The flour supplier expects payment and future orders from Tina and Steve''s bakery.', 'Tina and Steve depend on the supplier for quality flour while the supplier depends on their orders.', 'Delayed bakery orders threaten the flour supplier''s cash flow and staffing plans.', 'Supplier survival depends on steady bakery orders as well as timely payment.'], ARRAY[false, true, true, true, true], ARRAY['FALSE — Suppliers are stakeholders through payment and order dependency.', 'TRUE — Suppliers expect payment and orders without needing ownership.', 'TRUE — Mutual dependency runs both ways between buyers and suppliers.', 'TRUE — Order volumes affect supplier livelihoods as stakeholders.', 'TRUE — Suppliers rely on order volume and payment for ongoing operations.'], '4/5', 32, 'full' ),
( '3.6', 'CASE 3.6.33', 'Customer firm reliance', 'Customers lose access if a relied-upon supplier closes; evaluate mutual dependency:', ARRAY['Firms depend on customers for revenue but customers depend on no particular supplier.', 'Closing a relied-upon supplier affects customers, but they have no stakeholder link to that firm.', 'Suppliers need customers but customers do not rely on suppliers for availability.', 'Customers lose access if a relied-upon supplier closes.', 'Buyers need reliable suppliers just as suppliers need paying customers.'], ARRAY[false, false, false, true, true], ARRAY['FALSE — Customers rely on specific firms for product quality and availability.', 'FALSE — Customer welfare ties to firm performance through mutual dependency.', 'FALSE — Mutual dependency means customers rely on suppliers too.', 'TRUE — Customer welfare ties to firm performance through mutual dependency.', 'TRUE — Mutual dependency runs both ways between customers and firms.'], '4/5', 33, 'full' ),
( '3.6', 'CASE 3.6.34', 'Community facility impact', 'A new warehouse affects traffic and jobs in a town; assess community stakeholder claims:', ARRAY['Communities affected by noise from a new plant hold stakeholder interests in how the firm operates.', 'Local employment linked to a warehouse gives the community a stake in the firm''s continued operation.', 'A new warehouse affects traffic and jobs in a town, creating community stakeholder interests.', 'Community opposition to a new warehouse signals conflicting interests with the developer.', 'Residents near a new facility may experience stakeholder effects from increased lorry movements.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Communities are affected by business activity and count as stakeholders.', 'TRUE — Local employment ties community interests to firm outcomes.', 'TRUE — Communities are affected by facility impacts and local employment.', 'TRUE — Community and owner interests may conflict on expansion impacts.', 'TRUE — Traffic impacts create community stakeholder interests.'], '3/5', 34, 'full' ),
( '3.6', 'CASE 3.6.35', 'Government regulation aim', 'Regulators set standards protecting public interest in business conduct; evaluate:', ARRAY['Regulation aims to balance business activity with protection of wider stakeholder interests.', 'Business rules set by regulators reflect protection of the wider public interest.', 'Regulators have no stakeholder role because businesses operate independently of public policy.', 'Environmental rules reflect government acting as a stakeholder for the wider community.', 'Government builds roads solely for private amusement unrelated to business logistics.'], ARRAY[true, true, false, true, false], ARRAY['TRUE — Government stakeholder role includes protecting public interest via regulation.', 'TRUE — Government protects public interest through regulation.', 'FALSE — Government is a stakeholder via tax, regulation, and policy.', 'TRUE — Regulation can represent environmental and community stakeholder concerns.', 'FALSE — Infrastructure links to economic activity affecting business and public stakeholders.'], '3/5', 35, 'full' ),
( '3.6', 'CASE 3.6.36', 'Sustainability reporting duty', 'Investors and communities may demand sustainability reporting; assess environmental reporting claims:', ARRAY['Published sustainability data can inform investors and communities about environmental impacts.', 'Communities may rely on published environmental data when assessing local facility impacts.', 'Investors may use sustainability disclosures to judge whether environmental claims are credible.', 'Green marketing labels replace the need for environmental reporting.', 'Sustainability reporting is meant to hide impacts from community stakeholders.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Environmental reporting serves stakeholder information needs.', 'TRUE — Reporting addresses community stakeholder information needs.', 'TRUE — Reporting supports stakeholder evaluation of environmental performance.', 'FALSE — Reporting remains part of environmental stakeholder expectations.', 'FALSE — Reporting informs stakeholders rather than concealing impacts by design.'], '4/5', 36, 'full' ),
( '3.6', 'CASE 3.6.37', 'Profit versus environment conflict', 'Higher profit targets may clash with environmental spending; evaluate conflict claims:', ARRAY['Higher profit targets may clash with environmental spending on cleaner production.', 'Profit and environmental protection align perfectly with no trade-offs in every decision.', 'Owners and environmental stakeholders agree on every spending priority without exception.', 'Pollution control investments raise costs but create no tension with owner stakeholder interests.', 'Cleaner production spending can lower short-term profit and tension owner and environmental aims.'], ARRAY[true, false, false, false, true], ARRAY['TRUE — Profit and environmental goals can conflict in the same decision.', 'FALSE — Conflicting stakeholder interests include environmental tensions.', 'FALSE — Conflicting interests among stakeholders are common.', 'FALSE — Owner profit aims can clash with environmental demands.', 'TRUE — Owner profit aims can clash with environmental demands.'], '4/5', 37, 'full' ),
( '3.6', 'CASE 3.6.38', 'Growth versus community conflict', 'Tina and Steve plan a larger bakery extension opposed by neighbours; assess stakeholder conflict:', ARRAY['Expansion plans may clash with community preferences about noise and traffic.', 'Community objections to a bakery extension illustrate conflicting stakeholder interests in practice.', 'Neighbours near the bakery hold community stakeholder interests in delivery traffic from expansion.', 'Profit from a larger bakery and community concerns about noise can pull owners and neighbours in different directions.', 'Neighbours opposing Tina and Steve''s extension show conflicting stakeholder interests over local amenities.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Community and owner interests may conflict on expansion impacts.', 'TRUE — Conflicting stakeholder interests arise when growth affects local amenities.', 'TRUE — Local residents are community stakeholders affected by expansion plans.', 'TRUE — Profit and community concerns can conflict in expansion decisions.', 'TRUE — Community and owner interests can conflict in expansion decisions.'], '4/5', 38, 'full' ),
( '3.6', 'CASE 3.6.39', 'Stakeholder synthesis', 'Synthesise stakeholder theory and success factors for exam review:', ARRAY['Mutual dependence exists only between customers and suppliers, not among staff and the firm.', 'Exam review: stakeholders include anyone affected by or interested in the business.', 'Stakeholder analysis applies only to shareholders because they provide capital.', 'Greenwash satisfies environmental stakeholders if marketing slogans are persuasive enough.', 'Conflicting stakeholder interests do not arise when success factors are managed well.'], ARRAY[false, true, false, false, false], ARRAY['FALSE — Mutual dependence links managers, employees, customers, suppliers, and the firm.', 'TRUE — Stakeholders are defined broadly as affected or interested parties.', 'FALSE — Stakeholders include anyone affected or interested, not shareholders alone.', 'FALSE — Genuine environmental action is expected, not greenwash slogans alone.', 'FALSE — Conflicting stakeholder interests arise in many decisions.'], '1/5', 39, 'full' ),
( '3.6', 'CASE 3.6.40', 'Tina Steve stakeholders', 'Tina and Steve''s bakery affects owners, staff, suppliers, and neighbours; assess stakeholder map:', ARRAY['Bakery staff depend on the shop for wages and job security as employee stakeholders.', 'Tina and Steve as owners seek profit and bear risk from how the bakery trades.', 'Tina, Steve, staff, flour suppliers, and neighbours all hold stakeholder interests in the bakery.', 'Only Tina and Steve count as stakeholders because they provided the original capital.', 'The flour supplier expects payment and future orders as a supplier stakeholder.'], ARRAY[true, true, true, false, true], ARRAY['TRUE — Employees depend on firm success for livelihood.', 'TRUE — Owners typically seek profit and bear business risk.', 'TRUE — Multiple groups affected by the bakery fit the stakeholder definition.', 'FALSE — Stakeholders include staff, suppliers, customers, and neighbours too.', 'TRUE — Suppliers expect payment and orders without needing ownership.'], '2/5', 40, 'full' ),
( '3.6', 'CASE 3.6.41', 'AT&S stakeholder spread', 'AT&S affects owners, employees, suppliers, communities, and regulators in many countries; assess:', ARRAY['Employees at AT&S PCB plants are stakeholders affected by corporate decisions.', 'Government regulators in host countries hold stakeholder interests in AT&S operations.', 'Communities near AT&S facilities may be stakeholders affected by jobs and local spending.', 'AT&S affects employees, suppliers, communities, and regulators across its operating countries.', 'A multinational like AT&S has stakeholders only among its shareholders.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Employees are stakeholders through income, security, and identification.', 'TRUE — Government is a stakeholder via regulation, tax, and policy.', 'TRUE — Communities are affected by business activity and count as stakeholders.', 'TRUE — Large multinationals have broad stakeholder groups.', 'FALSE — Stakeholders include employees, suppliers, communities, and regulators too.'], '2/5', 41, 'full' ),
( '3.6', 'CASE 3.6.42', 'Greenwash marketing trap', 'A firm advertises eco-friendly packaging while increasing pollution; evaluate greenwash claims:', ARRAY['Honest green reporting builds less stakeholder trust than bold unsupported eco-claims.', 'Superficial eco-labels without operational change fail environmental stakeholder expectations.', 'Green packaging claims satisfy environmental stakeholders even when pollution rises.', 'Greenwash misleads stakeholders by exaggerating environmental performance in advertising.', 'Advertising recyclable boxes while dumping waste illegally illustrates greenwash risk.'], ARRAY[false, true, false, true, true], ARRAY['FALSE — Greenwash misleads stakeholders and undermines trust when uncovered.', 'TRUE — Real action, not slogans, is required on environmental issues.', 'FALSE — Genuine action is required, not greenwash slogans alone.', 'TRUE — Greenwash means exaggerated claims without real action.', 'TRUE — Misleading green claims without real action exemplify greenwash.'], '5/5', 42, 'full' ),
( '3.6', 'CASE 3.6.43', 'Supplier contract fairness', 'Suppliers argue for fair payment terms when the buyer delays invoices; assess:', ARRAY['Supplier cash flow concerns are unrelated to stakeholder analysis of payment fairness.', 'Delayed invoices affect only the buyer''s finance department, not supplier stakeholders.', 'Fair payment terms matter to suppliers as stakeholder treatment, not only to accountants.', 'Suppliers have no stakeholder interest in payment timing once a contract is signed.', 'Extending payment deadlines ignores supplier interests in cash flow and fair treatment.'], ARRAY[false, false, true, false, false], ARRAY['FALSE — Payment and order treatment reflect supplier stakeholder interests.', 'FALSE — Payment timing affects supplier stakeholders directly.', 'TRUE — Payment and order treatment reflect supplier stakeholder interests.', 'FALSE — Timely payment is a core supplier stakeholder interest.', 'FALSE — Payment timing is a core supplier stakeholder concern in fair dealings.'], '4/5', 43, 'full' ),
( '3.6', 'CASE 3.6.44', 'Employee shared values', 'Staff engagement rises when personal values align with company practices; evaluate:', ARRAY['Staff engagement improves when employees feel company practices match their personal values.', 'Shared values between staff and the organisation can support overall business success.', 'Alignment of personal and company values can improve cooperation on business objectives.', 'Staff who share organisational values may identify more closely with firm success.', 'Aligned values help employees and managers cooperate on shared business objectives.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Alignment of values supports cooperation on business goals.', 'TRUE — Shared values link employees with organisational performance.', 'TRUE — Shared values support cooperation between employees and management.', 'TRUE — Identification with firm success is an employee stakeholder theme.', 'TRUE — Shared values support mutual dependence and identification themes.'], '3/5', 44, 'full' ),
( '3.6', 'CASE 3.6.45', 'Owner long term value', 'Owners weighing reinvestment versus dividends affect long-term value; assess:', ARRAY['Owners have no interest in long-term business value, only in immediate cash extraction.', 'Long-term value growth is unrelated to owner stakeholder concerns about risk and reward.', 'Weighing dividends against reinvestment affects the long-term value owners seek.', 'Retaining profit in the business rather than paying dividends can build long-term owner value.', 'Reinvestment decisions affect only accountants, not owner stakeholder interests.'], ARRAY[false, false, true, true, false], ARRAY['FALSE — Owners may want share or business value to increase.', 'FALSE — Value growth links to owner risk and reward.', 'TRUE — Reinvestment versus payout shapes owner value interests.', 'TRUE — Reinvestment choices shape owner value interests.', 'FALSE — Reinvestment choices shape owner value interests.'], '3/5', 45, 'full' ),
( '3.6', 'CASE 3.6.46', 'Customer boycott power', 'Customers may switch suppliers if quality falls; evaluate stakeholder power:', ARRAY['Customers cannot influence firms because switching suppliers is impossible in all markets.', 'Falling quality gives customers power to switch suppliers and reduce firm revenue.', 'Customers may switch if quality falls, exercising stakeholder influence on revenue.', 'Customer boycotts after poor service show stakeholder power over firm revenue.', 'Buyers at a bakery have no power because they purchase small quantities each visit.'], ARRAY[false, false, true, true, false], ARRAY['FALSE — Mutual dependency gives customers influence when they can switch.', 'FALSE — Customers depend on firms for product quality and availability.', 'TRUE — Poor performance can drive customers to switch suppliers.', 'TRUE — Customers can influence firms through switching or boycotts.', 'FALSE — Customers can switch suppliers, exercising stakeholder influence on revenue.'], '3/5', 46, 'full' ),
( '3.6', 'CASE 3.6.47', 'Community employment stake', 'A town relies on one factory for many jobs; assess community stakeholder interest:', ARRAY['If the factory closes, the community loses jobs linked to that employer.', 'A major employer''s expansion or closure decision affects community stakeholders beyond the factory gate.', 'Residents whose family members work at the plant hold a community stakeholder interest in its future.', 'Local spending from factory wages links community welfare to the firm''s continued operation.', 'Closure of the town''s main employer would remove wages that support local shops and services.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Community interests are affected when a major local employer closes.', 'TRUE — Communities are affected by business activity and count as stakeholders.', 'TRUE — Local employment ties community interests to firm outcomes.', 'TRUE — Local spending and jobs link community interests to firm activity.', 'TRUE — Community welfare is tied to jobs and spending from major local employers.'], '3/5', 47, 'full' ),
( '3.6', 'CASE 3.6.48', 'Government infrastructure role', 'Government builds roads used by a regional distributor; assess stakeholder link:', ARRAY['Infrastructure used by firms links government investment to business stakeholder context.', 'Tax revenue from trading firms helps fund public infrastructure used by business.', 'Public roads built for general use have no connection to business logistics needs.', 'Regulators may set transport standards affecting firms that depend on road networks.', 'Roads built for public use also support business logistics and distributor operations.'], ARRAY[true, true, false, true, true], ARRAY['TRUE — Government affects and is affected by business as a stakeholder.', 'TRUE — Fiscal links connect government and business stakeholder interests.', 'FALSE — Infrastructure links to economic activity affecting business and public stakeholders.', 'TRUE — Government stakeholder role includes regulation affecting business logistics.', 'TRUE — Infrastructure links government investment to business activity.'], '3/5', 48, 'full' ),
( '3.6', 'CASE 3.6.49', 'Environment stakeholder status', 'Assess the environment as a stakeholder expecting concrete action and reporting:', ARRAY['Environment is not a stakeholder because it cannot sign contracts.', 'Pollution control matters only to regulators, not to environmental stakeholder theory.', 'Cosmetic eco-labels fully satisfy environmental stakeholders without operational change.', 'Environmental stakeholder theory treats nature as a party expecting action and reporting.', 'Environmental reporting is optional fiction unrelated to stakeholder expectations.'], ARRAY[false, false, false, true, false], ARRAY['FALSE — Environment is treated as a stakeholder expecting action and reporting.', 'FALSE — Environment is a stakeholder expecting genuine action and reporting.', 'FALSE — Real action, not slogans, is required on environmental issues.', 'TRUE — Environment is a stakeholder expecting action and reporting.', 'FALSE — Reporting communicates impacts to environment-focused stakeholders.'], '3/5', 49, 'full' ),
( '3.6', 'CASE 3.6.50', 'Success factors context', 'Relate stakeholder interests to legal, financial, market, and cost success factors:', ARRAY['Legal and financial structure shapes how well a firm can meet stakeholder expectations.', 'Market awareness serves only rival analysis and not customer stakeholder needs.', 'Cost control and profitability influence wages, orders, and returns for stakeholder groups.', 'Understanding market trends helps firms respond to customer and competitive pressures.', 'Legal structure is unrelated to business success and stakeholder outcomes.'], ARRAY[true, false, true, true, false], ARRAY['TRUE — Legal and financial structure are success factors affecting stakeholders.', 'FALSE — Market awareness helps meet customer and competitive pressures.', 'TRUE — Costs and profitability connect to owner and employee outcomes.', 'TRUE — Market awareness supports meeting customer and competitive pressures.', 'FALSE — Legal structure is listed among success factors affecting performance.'], '1/5', 50, 'full' )
